D.ItemDescriptions[89812]={["335a2ff094ef4e55:70"]="灌溉系统的安装包。可安装在日歌农场。"}
D.ItemDescriptions[89813]={["95a0259f982ea44e:78"]="超声波驱虫器的安装包。可安装在日歌农场。"}
D.ItemDescriptions[89814]={["52fd470cdc4eb593:72"]="大型犁的装配包。可用于开垦日歌农场的一行土地。"}
D.ItemDescriptions[89869]={["7f0b27ba6b8b3313:26"]="在我看来，它相当吓人。"}
