D.ItemDescriptions[89903]={["93089729bbaa31ee:40"]="罐中的金水散发着微光。"}
D.ItemDescriptions[89906]={["20ccc891e01599da:27"]="低脂肪，零碳水化合物！"}
D.ItemDescriptions[89991]={["c4c463938b4f3952:25"]="一捆随机烟火！"}
D.ItemDescriptions[89992]={["c7fef715fb31e5a4:43"]="教你学会制作神龙之心烟火。"}
D.ItemDescriptions[89993]={["a16806fad09a67c5:45"]="教你学会制作盛典烟火。"}
D.ItemDescriptions[89994]={["d8895cbcf5c54f53:38"]="教你学会制作天神烟火。"}
D.ItemDescriptions[89996]={["943c341deef1fc2c:42"]="教你学会制作秋英烟火。"}
D.ItemDescriptions[89997]={["4a2577595f85a760:40"]="教你学会制作玉蕊烟火。"}
D.ItemDescriptions[90006]={["bb4272ceaee20c93:29"]="在事态失控时使用。"}
D.ItemDescriptions[90045]={["248a2353c6fedc74:38"]="可兑换你想要的先祖凤凰。"}
D.ItemDescriptions[90047]={["3e2e97865b4c5b8b:28"]="最好不要把这些食品喂给任何生物吃。"}
D.ItemDescriptions[90048]={["9447af8b710dad82:53"]="精心制作，佩戴舒适，十分贴合鱼人的脖子。"}
D.ItemDescriptions[90078]={["7a500f89a72a21d0:36"]="好几处都泄露出了邪恶能量。"}
D.ItemDescriptions[90105]={["88c47559561a4178:89"]="由熊猫人铭文师以血红墨水写成，由于某些原因而落入了螳螂妖之手。"}
D.ItemDescriptions[90135]={["8cacca6fafee3970:11"]="格外新鲜。"}
D.ItemDescriptions[90173]={["9d6d0e19bc8fb050:35"]=S[13094]}
D.ItemDescriptions[90174]={["e770fbfd7ba79aaa:71"]="这份浸水的影踪派信函描述了龙虾人的诡异行为。"}
D.ItemDescriptions[90177]={["2689053e7c647751:31"]="教会你如何召唤爆虫。"}
D.ItemDescriptions[90385]={["b27775d82956b4a1:31"]="恐怕不止能用来割绷带。"}
D.ItemDescriptions[90470]={["3c89ce99f78dd0b8:30"]="教你学会制作碧玉猫头鹰。"}
D.ItemDescriptions[90471]={["4495bee92ae637f6:34"]="教你学会制作墨玉幼豹。"}
D.ItemDescriptions[90531]={["2b962a04b0ad6a3f:42"]="教你学会制作幽冥铁盾刺。"}
D.ItemDescriptions[90532]={["b1e13aa544adc1a2:44"]="教你学会制作活化钢武器链。"}
D.ItemDescriptions[90548]={["3b4251b403949b5b:85"]="关于获得这一印记的不幸事件已无相关记载。"}
D.ItemDescriptions[90551]={["ef55766ed5ad1521:87"]="不适宜人类饮用。是否适合机器人饮用尚且存疑。你最好不要让机器人消耗过度。"}
D.ItemDescriptions[90555]={["03ecfefdf41cd33a:32"]="警告标签：谁开谁死。"}
D.ItemDescriptions[90556]={["eb84e9c82e07043d:42"]="书页浸满了机油，难以阅读。"}
D.ItemDescriptions[90557]={["3122b5b73dea3982:58"]="这个可怜的家伙可能是不小心挖到了布林顿的电源。"}
D.ItemDescriptions[90561]={["06ee8cbf7e9cb9f8:103"]="某人或许会对这种稀有的花感兴趣。如果你想卖掉它的话，可以去藏宝海湾找利刃凯特琳。"}
D.ItemDescriptions[90578]={["8cc3fc23f13580ec:26"]="沾满天空的泪痕。"}
