D.ItemDescriptions[91030]={["e6029d7db16f6f84:47"]="尽管被挖了出来，却依然闪烁着明亮的光芒。"}
D.ItemDescriptions[91031]={["9d6d0e19bc8fb050:35"]=S[13094]}
D.ItemDescriptions[91040]={["9d6d0e19bc8fb050:35"]=S[13094]}
D.ItemDescriptions[91802]={["69f5e24752b91ada:50"]=S[13091]}
D.ItemDescriptions[91806]={["32dcc1240b67a1a1:172"]="出自高能传送门的混乱奥术能量结晶。日歌牧场的泥土能够稳定这种能量，从而生产出一种特殊的碎片。在农场打碎这种碎片可以打开一扇通往某座主城的一次性传送门。"}
D.ItemDescriptions[91807]={["0011d10a8e809e99:59"]="对于失败的困惑仍然凝固在奥这颗空无一物的右脑袋上。"}
D.ItemDescriptions[91808]={["e8776d484df52263:73"]="达克的脑袋仍然吐着舌头，以表达他对失败的最后蔑视。"}
D.ItemDescriptions[91809]={["94b2e04498e00d2d:75"]="库卡隆特有的骄傲和轻蔑永远凝固在了这颗兽人脑袋上。"}
D.ItemDescriptions[91810]={["86bc0e9042edd19f:33"]="这颗脑袋上还戴着防毒面具。"}
D.ItemDescriptions[91814]={["1377086ec5c66d67:50"]="一根纤尘不染的蜷曲翎毛，取自某只赤精的子嗣。"}
D.ItemDescriptions[91815]={["c0a19745bd6f2a68:41"]="一根漆黑发亮的羽毛，从巨型仙鹤身上拔下来的。"}
D.ItemDescriptions[91816]={["36278fa7fc5f5d0e:41"]="肥厚的牦牛肉。每一只老虎的梦中美味。"}
D.ItemDescriptions[91817]={["1c6eea8b6f3491ec:22"]="这味儿……太重了。"}
D.ItemDescriptions[91819]={["2d17f126d10cd60d:62"]=S[298]}
D.ItemDescriptions[91821]={["0fa53dbb6bbd0cd6:61"]=S[297]}
D.ItemDescriptions[91822]={["f8c96bbd5ac64946:54"]=S[311]}
D.ItemDescriptions[91823]={["3c360a4fa172ad3e:32"]=S[10658]}
D.ItemDescriptions[91834]={["6a066cedd5773f34:37"]="一只强大的巨型仙鹤的躯体，大得惊人。"}
D.ItemDescriptions[91835]={["910e68bffde1b97e:37"]="一只强大的巨型老虎的躯体，大得惊人。"}
D.ItemDescriptions[91836]={["1a7c4f1cf49e9c4f:36"]="一只强大的巨型螃蟹的躯体，大得惊人。"}
D.ItemDescriptions[91838]={["7d4320d00c94c369:116"]="这是一份授予在雄狮港服役的联盟成员的委任状。将它交给统御岗哨的奥格罗姆·黑牙。"}
D.ItemDescriptions[91846]={["f9fe06855ad1faec:60"]="污臭的海水和燃油的混合物在桶里晃荡。"}
D.ItemDescriptions[91848]={["c7831f610a354ece:43"]="这块矿石内涌动着黑暗能量。这很糟糕。"}
D.ItemDescriptions[91854]={["2d17f126d10cd60d:62"]=S[298]}
D.ItemDescriptions[91855]={["0fa53dbb6bbd0cd6:61"]=S[297]}
D.ItemDescriptions[91856]={["f8c96bbd5ac64946:54"]=S[311]}
D.ItemDescriptions[91869]={["ff2cb073af7ac2ba:41"]="这块滑腻的肉散发着腐烂的臭气。"}
D.ItemDescriptions[91871]={["655333c946da6004:29"]="摸上去很粗糙，但出奇地温暖。"}
D.ItemDescriptions[91874]={["38e1d666423d457b:80"]="这块肉上滴着气味可怕的黏液。这种怪味将在你的背包里留上好几天。"}
D.ItemDescriptions[91875]={["942ccea3ca252d24:73"]="比克希的家族燃料秘方，由圆锯家族代代相传。"}
D.ItemDescriptions[91877]={["d295357d7b64bf08:130"]="一块小令牌，以部落语写成，还配有一副溅上了红墨水的潘达利亚地图。将它交给雄狮港的普凡迪特·格兰特利。"}
D.ItemDescriptions[91902]={["27aa4f8f8b830cec:41"]="避免接触眼睛。安全无保障。"}
D.ItemDescriptions[91907]={["7f86edbbbdfa4c0e:99"]="刚从雄狮港周围的树林里采来的木材——而且刚被胆小的农夫丢下！"}
D.ItemDescriptions[92019]={["c3e715a56269bc98:90"]="一种极不稳定的强力易燃化学合剂，顶上扎着一条鲜艳的红巾。"}
D.ItemDescriptions[92035]={["cba1ba6ab5866141:22"]="一件古代魔古遗物。"}
D.ItemDescriptions[92036]={["62c0752de403a7fe:86"]="你感到这根看似普通的节杖中蕴含着惊人的能量。即使你用尽全力尝试，它也不会屈从于你的掌握。"}
D.ItemDescriptions[92070]={["410aa6058dd6433e:30"]="需要火金派熊猫人：崇敬"}
D.ItemDescriptions[92071]={["bace421a72a8051b:30"]="需要水土派熊猫人：崇敬"}
D.ItemDescriptions[92072]={["9d07894fca861316:133"]="这张坚韧的牛皮纸上画着一副昆莱山东北部的地图。地图中心以暗红色墨水画出的古代符文向外散发着能量。"}
D.ItemDescriptions[92425]={["f4448229639e8d52:45"]="这块石板上刻着强大的魔古符文。"}
D.ItemDescriptions[92426]={["6b3768c8aa526f39:65"]="除了缠在外面的锁链和插槽外，这本书看上去异常普通。"}
D.ItemDescriptions[92440]={["dcf970b7da025c86:81"]="古代寇茹石板拓片，上面记载了圣钟的起源。"}
D.ItemDescriptions[92441]={["85ddef95938f8692:66"]="当你拿起这本书时，耳边就会响起神秘而恐怖的低语……"}
D.ItemDescriptions[92471]={["12f42c97798294f6:55"]="这本被啃掉了一半的皮面日志已经失去了往日的光鲜。"}
D.ItemDescriptions[92472]={["6252beeca886672f:44"]="在这里发现这件东西的几率只有百万分之一。"}
D.ItemDescriptions[92474]={["58798bd4da795a93:44"]="闪闪发光！"}
D.ItemDescriptions[92475]={["032023d410872fbb:37"]="完全看不出新在哪里，又改良在哪里……"}
D.ItemDescriptions[92484]={["4c53abb3759f39c2:32"]="看上去出奇的普通。"}
D.ItemDescriptions[92493]={["0378e6cb81072884:21"]="很适合用来搞爆破！"}
D.ItemDescriptions[92499]={["9a6e9336e1dfaf41:48"]="这根坚硬的松针散发着一股舒缓的松树清香。"}
D.ItemDescriptions[92501]={["9fb9ee30415d9d43:100"]="朋友，我遇见了你的一位盟友。此人现已身受重伤，请尽快赶来滨岸村。"}
D.ItemDescriptions[92523]={["312e5495f0fa4fcc:47"]="它精美的外观掩盖了其出自魔古族之手的事实。"}
D.ItemDescriptions[92539]={["5437c8520946501f:76"]="这块硬化的宝石是从野生琥珀巨蝎尾针上摘下的，其内部闪烁着火光。"}
D.ItemDescriptions[92550]={["6951dcd2fadce285:28"]="内含塔布羊肉的订单。"}
D.ItemDescriptions[92556]={["5138737b17274c1a:41"]="这件物品里充满了奥术能量。"}
D.ItemDescriptions[92557]={["6f36f0393c94f16a:94"]="既有灼热熔炉般的火辣口感，又有大地般醇厚浓烈的劲道，这美酒的味道真是棒极了。"}
D.ItemDescriptions[92560]={["a8d468a3a1e8c7a6:131"]="岁月几乎没能在这个异常精美的金属杵头上留下任何痕迹。但那些把它当成餐桌的猢狲们还是在上面留下了不少食物的污渍。"}
D.ItemDescriptions[92561]={["9631a48e8459febf:86"]="这根精美的短杖作为权力的象征，一直在猢狲酋长中世代相传。"}
D.ItemDescriptions[92562]={["1721b567674edb0a:114"]="当你触摸这种药膏时，几乎能听见它在歌唱。这种本质上的共鸣通过你的手指，让你感到宁静与放松。"}
D.ItemDescriptions[92563]={["2daa8fbe15157a2b:37"]="这颗纳鲁水晶蕴含着巨大的能量。"}
D.ItemDescriptions[92580]={["a8babed62a9464cb:33"]="看起来能值一、两个金币。"}
D.ItemDescriptions[92581]={["01bef4d19648d244:25"]="迷人的芬芳，似曾相识……"}
D.ItemDescriptions[92582]={["a4cf7a5ae480eee5:34"]="或许还能卖上几个银币。"}
D.ItemDescriptions[92583]={["09c618fe6a9ff7ab:16"]="干了，但还有点香味。"}
D.ItemDescriptions[92584]={["1e08eb23b72365a0:25"]="看上去相当珍贵……"}
D.ItemDescriptions[92585]={["624bead09d5bd943:40"]="耀眼的火彩掩盖了它真正的魅力。"}
D.ItemDescriptions[92586]={["08ea6cc4e91e424d:35"]="看上去能值一、两个钱……"}
D.ItemDescriptions[92587]={["624bead09d5bd943:40"]="耀眼的火彩掩盖了它真正的魅力。"}
D.ItemDescriptions[92588]={["cffeaf62d188a9f5:30"]="有些人会为它出个大价钱……"}
D.ItemDescriptions[92589]={["93d4f7f91543a374:41"]="当你拿起它时，这座雕像毫无征兆地破碎了。"}
D.ItemDescriptions[92590]={["fb27cca251844e51:17"]="能值几个钱……"}
D.ItemDescriptions[92591]={["2a4ebf0a54af328f:36"]="血红色的宝石在光源下闪耀。"}
D.ItemDescriptions[92592]={["2ad5b6b1e9f361ba:20"]="能值一些钱……"}
D.ItemDescriptions[92593]={["4c999e3f5a82ea38:30"]="当你握住这块冰蓝色石头时，它会发出微弱的嗡鸣声。"}
D.ItemDescriptions[92594]={["5334a792b7afdabd:34"]="没以前那么值钱了……"}
D.ItemDescriptions[92595]={["04d984cdcfea3d22:20"]="廉价，但依然闪耀。"}
D.ItemDescriptions[92596]={["47ccd0f2f2fa52bd:19"]="相当值钱……"}
D.ItemDescriptions[92597]={["4cbbbb07ac71f504:46"]="只有红宝石做的珠宝，才最能彰显血精灵的高贵气质。"}
D.ItemDescriptions[92598]={["fb27cca251844e51:17"]="能值几个钱……"}
D.ItemDescriptions[92599]={["f699ee4b690cb27e:19"]="纯金打造，真不赖！"}
