D.ItemDescriptions[92601]={["1c0f992e9d16e66d:74"]="只有少量金币，但收集者或许会发现它们还是有点价值的。"}
D.ItemDescriptions[92602]={["69d179fc31c80b4f:24"]="一大堆金币……"}
