D.ItemDescriptions[92604]={["fb27cca251844e51:17"]="能值几个钱……"}
D.ItemDescriptions[92605]={["9245e916ed71e2f1:61"]="出于某些原因，当你握住它时，会产生莫名的优越感。"}
D.ItemDescriptions[92606]={["8d21fab4192c81fd:33"]="能值一大笔钱……"}
D.ItemDescriptions[92607]={["f65273b99a27387c:50"]="这件超越时间的杰作凸显了她的优雅与美丽。"}
D.ItemDescriptions[92608]={["d1f324c58dcc6bb8:18"]="能值一、两个金币……"}
