D.ItemDescriptions[92754]={["e79df64534ae1920:128"]="白色的液体散发着辛辣刺鼻的气味。抿一口就能让你的胃里火烧火燎的，然后让你的脑袋迅速进入暖洋洋的迷糊状态。"}
