D.ItemDescriptions[93955]={["904e89b19bb57dec:59"]="这条精心雕刻的毒蛇正盘踞在一枚巨大的蛇牙上。"}
D.ItemDescriptions[93956]={["ab14b9576b7f0cba:79"]="这个雕像由蜘蛛牙雕刻而成，上面仍然沾有毒液，估计是用于制毒仪式。"}
D.ItemDescriptions[93957]={["aed1d3d3e8cdb13c:65"]="长矛尖上的装饰雕像是用恐角龙的颈椎和头骨雕刻而成。"}
D.ItemDescriptions[93958]={["ede6c63c28dc0ed7:81"]="这个千年陶罐是个无价之宝，蜥蜴人却用它来当夜壶。"}
D.ItemDescriptions[93959]={["e6513c37df85e30a:76"]="这枚珠宝蟑螂的两只虫翼上贴有切割粗糙的大块宝石，看得出制作者的手法十分笨拙。"}
D.ItemDescriptions[93960]={["94b67d1349c26a4e:89"]="来自赞达拉巨魔的礼物，这枚魔暴龙卵的表面覆满了细小的宝石，拼成了一位魔古帝王的肖像。"}
D.ItemDescriptions[93961]={["e378f0b05a9d5d63:58"]="当你将这枚宝石握在手中时，你仿佛听到了一阵虚弱而遥远的惨叫。"}
D.ItemDescriptions[93962]={["9bb2e6ac5f5f970b:41"]="不管是什么任务，它都能搞定。"}
D.ItemDescriptions[93969]={["e863f9e0277920d9:59"]="这些宝石里束缚的灵魂曾经用来驱动赞达拉魔像。"}
