D.ItemDescriptions[95394]={["f56b435d9b048ed6:65"]="古克罗克常常出产低劣的珍珠，但这颗是例外。"}
D.ItemDescriptions[95396]={["3c2dc52186b6e006:28"]="真的非常美丽，而且异常稀有。"}
D.ItemDescriptions[95398]={["c34e91ff95d019d2:36"]="它散发出的光能平复你的心情。"}
D.ItemDescriptions[95399]={["58ff3fd6e7310d73:62"]="必须从鱼线上摘下来。毕竟，谁会用钻石来钓鱼呢？"}
D.ItemDescriptions[95401]={["246f1dc9c5bc2070:51"]="经过你的辨认，标签上写着乌贼墨和鲑鱼眼。"}
D.ItemDescriptions[95402]={["ff35397e2edcf4d5:38"]="巧克力，坚果……还有棉花糖？"}
D.ItemDescriptions[95403]={["a95af6c4bed30701:25"]="散发着生姜的辛辣气味……"}
D.ItemDescriptions[95404]={["8c6a04ccdae7572b:39"]="我知道有些锦鱼人很喜欢这东西。"}
D.ItemDescriptions[95405]={["db1d78e2115fbd0f:52"]="据说里面真的存放着他的弟子们的泪水。"}
D.ItemDescriptions[95406]={["a674bb8679223833:51"]="这肯定是从某个许愿的人手上滑下来的。"}
D.ItemDescriptions[95407]={["c702695f6dab47c8:46"]="最好不要去追究锦鱼人珍珠是怎么形成的。"}
D.ItemDescriptions[95416]={["2ac33c4d5ac42e44:50"]="教你学会驾驭飞天魔像。这是一种飞行坐骑。"}
