D.ItemDescriptions[104286]={["2582c10c12fee55d:85"]="一枚即将孵化的稀有龙蛋。百木园的安离长老肯定会对这枚蛋十分感兴趣的。"}
D.ItemDescriptions[104287]={["6d4cbfe1f1d36504:99"]="风翎鹤的羽毛摸上去格外轻盈，一点微风就能将它吹跑。"}
D.ItemDescriptions[104288]={["77facde73f62cb82:74"]="翠雾舞者向来以能够天衣无缝地融入岛屿周围的迷雾而著称。"}
D.ItemDescriptions[104290]={["6cbf020bb73aa224:83"]="永恒岛上的蚕虫有一种十分奇特且强大的捕猎技能。"}
D.ItemDescriptions[104291]={["ae2c5188406c4763:45"]=S[13083]}
D.ItemDescriptions[104292]={["53b13a0a720b6ccb:89"]="这条蛇显然一口吞下了太多东西，以至于大部分食物都还是完整的，尚未消化。"}
D.ItemDescriptions[104293]={["150984533f9fa178:73"]="钳爪蟹的微光甲壳可用来迷惑潜在的掠食者。"}
D.ItemDescriptions[104295]={["9d6d0e19bc8fb050:35"]=S[13094]}
D.ItemDescriptions[104296]={["88256a7a6a96f27b:59"]="这件华丽的衣服可分解成有用的材料。"}
D.ItemDescriptions[104298]={["eac63e32838643ed:53"]="斡耳朵信徒会在向斡耳朵斯献祭前敲响这些钟。"}
D.ItemDescriptions[104299]={["56c155c3b6dcea22:42"]="在落烬的核心中发现的白热碎片。"}
D.ItemDescriptions[104302]={["4dc65719186b9dea:40"]="斡耳朵斯的勇士们所使用的仪式匕首。"}
D.ItemDescriptions[104303]={["48e4956a9d0432bd:67"]="潘达利亚淘气的水灵似乎与天气有着某种神秘的联系。"}
D.ItemDescriptions[104304]={["4b6f928778b1f0be:115"]="斡耳朵的高阶咏者能够操纵天气，以确保雨水和大雪永远不会落到斡耳朵圣殿永不熄灭的火焰上。"}
D.ItemDescriptions[104305]={["2db5fb99290475b2:74"]="在攻击前，斡耳朵野牛人常常会召唤一场灰烬风暴来蒙蔽敌人的视线。"}
D.ItemDescriptions[104306]={["3f58f6e3cda321be:83"]="一块古怪的石头，可能相当危险，可以使小范围内的时间停止流逝。"}
D.ItemDescriptions[104307]={["ae2c5188406c4763:45"]=S[13083]}
D.ItemDescriptions[104309]={["d42a1447f06304ac:82"]="斡耳朵斯的追随者会在深入荒野时随身带一个小火炉。"}
D.ItemDescriptions[104313]={["3f96d47addfb04cb:106"]="这些苔藓已经在潮湿的洞穴中生长了数千年，其中慢慢混入了黄金和其他贵金属。"}
D.ItemDescriptions[104314]={["ed9ee6d5fd379b2e:31"]="由格里姆索恩·红须手工制作。"}
