D.ItemDescriptions[104340]={["4d73561143143320:27"]="含有微量毒素，但十分美味！"}
D.ItemDescriptions[104341]={["8420ea154cb69026:44"]="香气扑鼻的面汤里加入了羊肉和山羊奶。"}
D.ItemDescriptions[104342]={["74b34b1e3e184c65:41"]="营养丰盛又热气腾腾，就像野牛人热烈奔放的性格！"}
D.ItemDescriptions[104343]={["43cdd36f99f88a02:31"]="馥郁、清淡、鲜美。"}
D.ItemDescriptions[104344]={["59d26e40c1a4d41b:16"]="味道鲜美量又足。"}
D.ItemDescriptions[104348]={["7c9b57d32d5dc4a0:32"]="清新提神的草药饮品。"}
