D.ItemDescriptions[105701]={["0a963a3e58308be3:49"]="加入了玉粉的绿石村的丛林特色美酒。"}
D.ItemDescriptions[105702]={["ed70787c78e40f95:48"]="酒仙布兰琪的翡翠林春酒，能令人嘴唇发麻。"}
D.ItemDescriptions[105703]={["5e843bff430e5604:71"]="由四风谷最大最著名的酿造厂出品，但稍嫌寡淡。"}
D.ItemDescriptions[105704]={["575e4cd7e929ba4c:62"]="高老伯的“终极美酒”，极其辛辣，十分易燃。"}
D.ItemDescriptions[105705]={["652bacf383ccc7b0:60"]="加入了超大量的昆莱啤酒花，后劲十足。"}
D.ItemDescriptions[105706]={["78287bab02a034a0:86"]="影踪禅院的武僧们所酿造的壮胆烈酒，集熊猫人和野牛人酿酒工艺之大成。"}
D.ItemDescriptions[105707]={["ca617d73a4593a64:59"]="珀酒仙的另类丛林果酒。"}
D.ItemDescriptions[105708]={["f477355945d2a352:48"]="加入了凯帕圣树树脂的稀有美酒。"}
D.ItemDescriptions[105711]={["76eeeb368d786923:68"]="用珀酒仙的盎迦陈酿与海岛猢狲的烈性“劲酒”调合而成，酒性极烈。"}
D.ItemDescriptions[105713]={["6b87824256dfd9a5:42"]="金莲教的慷慨遗赠。"}
D.ItemDescriptions[105715]={["09853a3d7e18df1a:45"]="你感觉到这块石头散发着沉甸甸的岁月感。"}
D.ItemDescriptions[105716]={["72281551b6b89948:31"]="这颗巨大且遍布血管的心脏非常沉。"}
D.ItemDescriptions[105891]={["a0a061cc8dd7ab15:38"]="一张发出微光的雪白狼皮。"}
D.ItemDescriptions[105920]={["5fa6a54eb0f676b9:35"]="在安全距离送上一杯啤酒。"}
