D.ItemDescriptions[106256]={["8a7ca4a488fb0f37:37"]="教你学会召唤财宝地精。"}
D.ItemDescriptions[106869]={["1b48bbcc1a0bd9c9:42"]="镶嵌在德拉诺珠宝上时，就跟稀有宝石一样珍贵。"}
D.ItemDescriptions[106876]={["3534975d8a4ef7a4:50"]="这块火山岩散发着阴森的能量。"}
D.ItemDescriptions[106877]={["af6847ebd80c70bc:49"]="被兽人部族所珍视的战利品，被当做猎人好运的象征。"}
D.ItemDescriptions[106890]={["e676eb821816950d:78"]="德莱尼工程师常将它装在灯柱上，用于道路和公共场所的照明。"}
D.ItemDescriptions[106902]={["2bffb11e4397ae21:103"]="一张仔细折叠好的羊皮纸，已经因年代久远而泛黄。和这个箱子一样，它似乎已经在这里存放了好多年了。"}
D.ItemDescriptions[106941]={["de7ae5ad4825a80c:102"]="一种稀有的草药，可以防止感染，甚至解除某些毒素。全德拉诺的医生都在搜寻这种草药。"}
D.ItemDescriptions[106942]={["7b57ab9a2987902d:31"]="它见识过许多酷刑。"}
D.ItemDescriptions[106943]={["9c417f265c91ea6b:18"]="格外轻盈。"}
D.ItemDescriptions[106944]={["aea44ad85748a20d:27"]="黏糊糊的，散发着恶臭。"}
D.ItemDescriptions[106986]={["677836e98f03553c:51"]="散发着纯粹的邪恶气息，缓慢腐蚀着它接触到的一切。"}
D.ItemDescriptions[107066]={["815475c9211e2cc0:25"]="穆维里克的双斧之一。"}
D.ItemDescriptions[107075]={["74650d039eeab95e:41"]="一把钥匙，可以解开穆维里克的牢笼。"}
D.ItemDescriptions[107086]={["1c372a4879933393:41"]="封蜡上有着青铜龙军团的徽记。"}
D.ItemDescriptions[107195]={["3ca8f226bcbec417:30"]="温暖你的口袋，烧死你的敌人。"}
D.ItemDescriptions[107200]={["5642635dd5596d08:159"]=S[8217]}
D.ItemDescriptions[107268]={["5642635dd5596d08:159"]=S[8217]}
D.ItemDescriptions[107269]={["f01ba52a7c899b6b:137"]="尽管这张图纸上的管道规模惊人，但设计十分原始。图纸大部分都被前所有者的鲜血所浸染了。"}
D.ItemDescriptions[107272]={["8eea38ca97fd7edd:174"]="“乳牙”是霜狼幼崽长出恒牙时替换下来的第一颗牙齿。霜狼氏族的兽人常常将自己的动物伙伴的乳牙当做幸运符保存起来。"}
D.ItemDescriptions[107276]={["6bc76138cdd42a63:55"]="这把武器显然是由某位铸剑大师亲手铸造并保养的。"}
D.ItemDescriptions[107278]={["8bdd580c43ec7b49:49"]="这把血迹斑斑的钉锤显然是出自某位锻造大师之手。"}
D.ItemDescriptions[107335]={["45db7e7fccc204f0:37"]="这本尘封的日记中写满了黑暗的秘密。"}
D.ItemDescriptions[107338]={["ac644c3a414e13eb:61"]="自从它的主人成年后，这个面具就一直在经受岁月的侵蚀。"}
D.ItemDescriptions[107361]={["8c901717360272c6:42"]="取自裂蹄牛，效力之强令人吃惊。"}
D.ItemDescriptions[107391]={["aa8f53dcc08b1327:111"]="通天峰严禁使用暗影魔法。被发现私藏这本书的鸦人都将被打上异教徒的烙印并遭到流放。"}
D.ItemDescriptions[107394]={["1e15a5c34ee1af6c:50"]="只要小心使用，这颗宝珠可以提供数日的燃料。"}
D.ItemDescriptions[107399]={["59fcec60fcf13455:67"]="这把恶毒的武器制作粗糙，但却砍伤过很多受害者。"}
D.ItemDescriptions[107400]={["0cc482c7f4a016a2:68"]=S[17730]}
D.ItemDescriptions[107401]={["8fa2c12236b013fb:129"]="这些水果和蔬菜上面没有可疑的粉末和香料，看来这就是嘲颅部落里唯一能吃的东西了。"}
D.ItemDescriptions[107463]={["9347ca65716ec052:51"]="有着完美无瑕，且不反光的球面。"}
D.ItemDescriptions[107471]={["061e64bad3c80cdd:66"]="残余的能量使其成为萨满教仪式中宝贵的聚焦道具。"}
D.ItemDescriptions[107474]={["00701d4190a6050a:6"]="杂物。"}
D.ItemDescriptions[107499]={["c7beeac5e7b2d1de:13"]="甜香滚烫"}
D.ItemDescriptions[107526]={["87f31aae81282143:48"]="可用来盛放挥发性或腐蚀性液体。"}
D.ItemDescriptions[107532]={["1a5df45e5f2d1261:32"]="德拉诺猎手们的一种游戏道具。"}
D.ItemDescriptions[107604]={["8c1164f5de876f68:107"]="象牙比钢铁轻盈，比骨骼坚韧，可以用来制造轻武器，也是织染工喜爱的工具。"}
D.ItemDescriptions[107642]={["f912f2f6e463cee5:91"]="这个面具的模样和气味说明它已经在这些疯狂的酋长中传承了数代之久。"}
D.ItemDescriptions[107644]={["1f9adcf7c129d31c:49"]="可以有效阻挡攻击和阳光。"}
