D.ItemDescriptions[120356]={["a795e4bf99528118:41"]=S[5491]}
D.ItemDescriptions[120358]={["611662be2befe09d:53"]="别喝，否则你就得付出一切作为代价。"}
D.ItemDescriptions[120401]={["c2a2a3ba9fe3f419:55"]="这块水晶散发着微弱的嗡鸣声，里面显然还残留了一些能量。"}
D.ItemDescriptions[120432]={["0343fa2e2736ff5f:24"]="几乎和原版的一样红"}
D.ItemDescriptions[120857]={["5627f0e68d278559:37"]="装的不是头巾，而是满满一桶欢乐！"}
D.ItemDescriptions[120939]={["69e24b8cb115b21d:44"]="这颗蛋散发着微弱的魔力荧光。"}
D.ItemDescriptions[120940]={["51d98ab4a98d5a39:46"]="加鲁霍德要怎么把这些东西加到他的饮料里？"}
D.ItemDescriptions[120945]={["6df68e25fbefca0a:60"]="可以用来制造物品或者和你要塞里的特殊商人交易。"}
D.ItemDescriptions[120946]={["ebbf0101e60c8256:23"]="中级冰霜法术"}
D.ItemDescriptions[120947]={["cd1b357a6f5306e3:34"]="你的标准尖顶巫师帽。"}
D.ItemDescriptions[120948]={["e625229e22b38d53:49"]="这完全是透明的。你真的该穿吗？"}
D.ItemDescriptions[120949]={["e7cd4ce6132373a5:8"]="嗖——"}
D.ItemDescriptions[120959]={["2a1da25f142f9482:35"]="警告：不要在明火旁饮用"}
D.ItemDescriptions[120968]={["9d69c7e79ea21f8c:26"]="雇佣你的私人代驾。"}
D.ItemDescriptions[120978]={["f8a3f83c5fb3d805:167"]="逐渐地，人和武器似乎化为了一体。灰烬使者这个名字成为了传说，它不仅仅是指这把令敌人闻风丧胆的利器，也是指挥舞此剑的残酷骑士。"}
D.ItemDescriptions[121334]={["a87951f4c1f4a4e7:56"]="这把剑已经破得没法修了。长剑并不适合采矿。"}
D.ItemDescriptions[121335]={["dac653c9c6b915b0:33"]="显然不如长矛有效。"}
D.ItemDescriptions[121340]={["b20875c8e490a813:48"]="使用金属战锤跟风暴巨龙作战是有风险的。"}
D.ItemDescriptions[121374]={["3816f7dbb84690b0:107"]="好几片同样的大陆互相叠加在一起，上面还布满了各种划线。"}
D.ItemDescriptions[121375]={["a2aeaf093d62b25e:33"]="没人知道它到底怎么榨汁。"}
D.ItemDescriptions[121376]={["ad9a1f954845d6f4:81"]="尽管被弃置了数千年，剑身上的精密刻痕仍然清晰可见。"}
D.ItemDescriptions[121377]={["a178f20f6c1e7126:47"]="似乎被一头巨熊咬了一口。"}
D.ItemDescriptions[121378]={["2dd536d9c7023692:96"]="这把弓太久没用，已经有些松了。上面刻着精美的纹饰，讲述了一位古代精灵英雄的事迹。"}
D.ItemDescriptions[121379]={["18e0c7ebfda6d3b0:60"]="比普通步枪要小，上面刻着两个缩写缩写字母“A.F.”"}
D.ItemDescriptions[121380]={["fa0efcc381ade4a6:59"]="前主人在记住它独特的外观后，就把它扔了。"}
D.ItemDescriptions[121381]={["89fc37e594f34632:28"]="不幸的是，上面没有插槽。"}
D.ItemDescriptions[121382]={["c3368535a26f1eb0:121"]="这把巨大的武器基本就是一只巨型昆虫的节肢，装了雕花岩石作为配重锤。"}
D.ItemDescriptions[121383]={["bb730f90de014c4d:113"]="一头刻着“云中大师9000”几个字，另一头系着一簇马毛。这到底是做什么用的呢？"}
D.ItemDescriptions[121384]={["7c7a26b441ec8651:65"]="某个未知的胜利者从一个强大的水元素残骸上拾取的。"}
D.ItemDescriptions[121385]={["27bd48b3b20f78d4:80"]="你只能勉强从这些褪色的卡牌上辨认出长着胳膊的树和绿色的小个子人形生物。"}
D.ItemDescriptions[121386]={["32413303689ef212:112"]="这条原始的腰带是由保存完好、约有成年人前臂那么长的昆虫颚骨连缀而成的。作为服装而言完全不实用。"}
D.ItemDescriptions[121387]={["82e1eeeabe49e0d7:31"]="有额外的口袋，可以盛放金币和骰子。"}
D.ItemDescriptions[121388]={["34827b9d2c4251d8:54"]="这些镣铐标志着圣骑士艾朗德的绝望挣扎。"}
D.ItemDescriptions[121389]={["c1eba5f511b7a43e:104"]="相比宝石，更像是黑曜石。当你将它握在手中时，心中会产生一种不安的恐怖感。"}
D.ItemDescriptions[121390]={["33ad43ad69864490:85"]="考尔不会承认，安努德曾试图用这些绷带为他治疗卡尔卓葛斯的魔法吐息伤害。"}
D.ItemDescriptions[121391]={["a918f79c24db4a1d:38"]="沾满了恶心的液体和玻璃碎片。"}
D.ItemDescriptions[121392]={["28c4475811d24f71:77"]="这条破裤子上缝着几十个隐蔽的口袋，每一个都恰好能装下一把飞刀。"}
D.ItemDescriptions[121393]={["2bd907f2edb586ff:49"]="曾属于一个误入歧途的传奇英雄。"}
D.ItemDescriptions[121394]={["17c8b0e700d51014:78"]="让我换几件装备和饰品……好了！倒计时，25、24、23、22、21……"}
D.ItemDescriptions[121395]={["eec1babc4e1d6267:50"]="或许能大大提升在挑战地下城的表现。"}
D.ItemDescriptions[121396]={["a69838dfde8068e6:79"]="即使以艾萨拉时代的标准来看，这些肩甲也十分古老，上面蚀刻着神灵的徽记。"}
D.ItemDescriptions[121397]={["d5fbd4b54406ced4:41"]="为什么会有人喜欢这么重的肩甲？"}
D.ItemDescriptions[121398]={["6648cd2634ababf1:57"]="莎赫拉丝主母会把这种东西发给表现平平的人。"}
D.ItemDescriptions[121399]={["bcc8e034b60705a3:32"]="肯定会射偏的。"}
D.ItemDescriptions[121400]={["204c5ff70a663e74:40"]="萨拉恩的手套，更适合女性使用。"}
D.ItemDescriptions[121401]={["0066e9c2366122a1:35"]="四海为家，终无所依。"}
D.ItemDescriptions[121402]={["5eba8929121d6dde:37"]="可能属于过去的某个屠夫。"}
D.ItemDescriptions[121403]={["accd2d8563c7397e:35"]="边上还有几缕烧焦的头发。"}
D.ItemDescriptions[121404]={["aa8dc33ce870182d:65"]="低劣的工艺令这顶头盔损失了许多潜力。"}
D.ItemDescriptions[121405]={["b0c5f54bd76bd5be:39"]="穿上它的人会变得十分愤怒。"}
D.ItemDescriptions[121406]={["fd7e2e9cde210101:24"]="由于反复使用而变得陈旧。"}
D.ItemDescriptions[121407]={["e6faa66d2fbc6d0e:105"]="要不是上一次启动时发生了零件爆炸，只要重新充能就能轻松地将你发射到很远的地方。"}
D.ItemDescriptions[121408]={["ed8ef8a6fb81d5a5:33"]="它曾对某人非常珍贵。"}
D.ItemDescriptions[121409]={["8f2e84280d7c4cef:108"]="这副铠甲上绘制着一副栩栩如生，但已经残破的装饰画，表现了一些长着獠牙的人型生物和一群没有脸的巨型生物战斗的场面。"}
D.ItemDescriptions[121410]={["ede5a336e2fc3011:77"]="这件长袍上既有艾露恩的徽记，也有一些受到膜拜的神灵印记。"}
D.ItemDescriptions[121411]={["9eb392aa9afda9c1:45"]="闻上去像落水的猫，落水的熊，和落水的枭兽。"}
D.ItemDescriptions[121412]={["a69981e6a0f58b6b:67"]="有人发现，如果不穿它们，可以通过其他方式跑得更快。"}
D.ItemDescriptions[121413]={["6d32d36e31f41db7:149"]="这双靴子的前端一分为二，形成了两个巨大的尖角。即使经过了这么多年的腐朽风化，它们看上去依然让人觉得肉疼。"}
D.ItemDescriptions[121414]={["a900a20d2a526c12:54"]="他的法术唯一一次被反制时，就是穿着这双靴子。"}
D.ItemDescriptions[121415]={["2fce236f79c7d516:56"]="你还以为一个术士知道，他是不能装备这个东西的。"}
D.ItemDescriptions[121652]={["b85443e1b32c8064:25"]="它最后等来的是悲惨的结局。"}
D.ItemDescriptions[121736]={["fd015baf0e5abc48:44"]="有时，你必须沉沦，才能明白自己真正的潜力。"}
D.ItemDescriptions[121796]={["4a735fce63436749:32"]="相同的血统是一种强有力的羁绊。"}
D.ItemDescriptions[121815]={["24146c488b5a7fa3:31"]=S[13087]}
D.ItemDescriptions[121816]={["c7ed2abdd3003a48:55"]="这些微尘颗粒充斥着狂暴的魔法能量。"}
D.ItemDescriptions[121817]={["a0985c6ee37a41a5:65"]="这棵树的树皮已经在纯净的魔法能量浸染下变得坚硬并结成晶体了。"}
D.ItemDescriptions[121821]={["0d0d0a1490b973e1:92"]="这颗聚焦水晶刻有强大的魔法符文，是非常充沛的能量源。"}
D.ItemDescriptions[121837]={["9d629fd70c3e2cda:58"]="内含无数爆炸品的制作方法。"}
D.ItemDescriptions[122095]={["00c502867ec51fc9:21"]="纯净的法力结晶。"}
D.ItemDescriptions[122104]={["9bbd0b4c93e5317d:41"]="教你学会召唤海兽幼崽。"}
D.ItemDescriptions[122105]={["2770287d5dbcd7dc:32"]="教你学会召唤怪诞魔。"}
D.ItemDescriptions[122106]={["6c1005b07f074d4f:30"]="教你学会召唤深渊小魔怪。"}
D.ItemDescriptions[122107]={["1113a61489a5c7bf:38"]="教你学会召唤暴怒残片。"}
D.ItemDescriptions[122108]={["df752a90d7266d53:42"]="教你学会召唤苦难残片。"}
D.ItemDescriptions[122109]={["065410034be34d0c:39"]="教你学会召唤欲望残片。"}
D.ItemDescriptions[122110]={["87904c729cfc1ced:44"]="教你学会召唤诱惑魔女。"}
D.ItemDescriptions[122111]={["5d976a5b7cef5c6c:30"]="教你学会召唤恶臭腐尸。"}
D.ItemDescriptions[122112]={["9d6d0e19bc8fb050:35"]=S[13094]}
D.ItemDescriptions[122113]={["c2a77630305eb5c5:45"]="教你学会召唤微型炎刃防御者。"}
D.ItemDescriptions[122114]={["3172d768eb38a6cf:42"]="教你学会召唤虚空中的混沌幼崽。"}
D.ItemDescriptions[122115]={["9c2045979d42637c:38"]="教你学会召唤痛苦的仆从。"}
D.ItemDescriptions[122116]={["d7e7587dc2c2cdf4:27"]="教你学会召唤库特。"}
D.ItemDescriptions[122122]={["6384019a02697d77:29"]="MC-14“迦顿”级坦克模型。"}
D.ItemDescriptions[122123]={["2f81a79d1eb4aae4:38"]="一根装满了彩环的小型手持烟火。"}
D.ItemDescriptions[122125]={["581bed15d2684ac2:34"]="教你学会召唤迷你竞速飞艇。"}
D.ItemDescriptions[122126]={["12672bc5fba04876:12"]="快站出来吧！"}
D.ItemDescriptions[122128]={["72ba9b59850cac5e:16"]="来体验一段胜利的赛程吧！"}
D.ItemDescriptions[122129]={["742f4f4035d78031:50"]="内含各种五彩缤纷的爆炸性物质。"}
D.ItemDescriptions[122132]={["b425953ddd3b1d42:40"]="只有刃牙虎人才会觉得这玩意儿开胃。"}
D.ItemDescriptions[122133]={["5908c294e1197563:72"]="它似乎正用尖锐的回响诉说着某些紧急的事情。"}
D.ItemDescriptions[122134]={["1678ddbfd6019fd8:49"]="虽然有着冰晶一般的结构，可塑性却意外的强。"}
D.ItemDescriptions[122139]={["68eb53f8301f6985:48"]="用于治疗钢铁前线上受伤的要塞士兵。"}
D.ItemDescriptions[122153]={["108df8111bd7fd3c:23"]="跃动着魔网的能量。"}
D.ItemDescriptions[122155]={["96c0f966d21c17fd:79"]="这颗暗影议会宝珠在对你窃窃私语，令你的脑海中充斥着各种超乎想象的力量幻象。"}
D.ItemDescriptions[122157]={["6d5635e53289ebe4:133"]="大法师罗宁在魔枢之战的最后时刻使用这根法杖将达拉然与永恒之眼联结了起来，使这座城市成为全新的魔法能量枢纽。"}
D.ItemDescriptions[122158]={["518f921a494c4347:108"]="吉安娜·普罗德摩尔通过这块不起眼的水晶使魔法能量流经整个达拉然，供全城的人使用。"}
D.ItemDescriptions[122159]={["32ca1169a3976c98:116"]="由大法师安东尼达斯制作，将魔网导向达拉然的中心，使肯瑞托能够随时监控艾泽拉斯的魔法使用情况。"}
D.ItemDescriptions[122176]={["9100112d0a109a90:59"]="缝满了小口袋，里面装着各式各样的爆炸物。"}
D.ItemDescriptions[122179]={["0630a34256bab6af:12"]="气味很难闻。"}
D.ItemDescriptions[122181]={["8baa885112937034:71"]="这条挂毯在你要塞的前门位置画了一个潦草的红色箭头。"}
D.ItemDescriptions[122188]={["d0aab28e6d0f7e0d:40"]="这块水晶散发着微弱的魔力。"}
D.ItemDescriptions[122190]={["e094bcd2054f29ed:39"]="但愿它流出来的不是真的鲜血。"}
D.ItemDescriptions[122191]={["53276f6d1e7850d2:50"]="内含三份来自纳格兰鲜血竞技场的邀请函。"}
D.ItemDescriptions[122270]={["54090703e10e9672:80"]="可以在拍卖行中售出，换取金币。拍卖行买家可以用它换取30天游戏时间。"}
D.ItemDescriptions[122274]={["7c15ab9acc28b449:32"]="为一名追随者增加2000点经验值。"}
D.ItemDescriptions[122275]={["e19f8d3d5f30decc:65"]=S[411]}
D.ItemDescriptions[122283]={["b3490161114a39a2:89"]="这颗散发着微光的宝石将鲁克玛的意志灌入你的脑海，将你变成她的追随者。"}
D.ItemDescriptions[122284]={["4ca9281ed29a7865:53"]=S[2438]}
D.ItemDescriptions[122291]={["8eb70ad5b6478fb4:26"]="闪闪发亮。从哪儿来的？"}
D.ItemDescriptions[122292]={["17f2b5e3d7f489ca:53"]="这头雏龙似乎比它的大部分同类都要瘦小虚弱。"}
D.ItemDescriptions[122294]={["6edf5af49554636d:24"]="有了它，尤特纳才能看见你。"}
D.ItemDescriptions[122296]={["6edf5af49554636d:24"]="有了它，尤特纳才能看见你。"}
D.ItemDescriptions[122297]={["d45bdc1685dc611b:48"]="米希卡特别调制的治疗及急速药水。"}
D.ItemDescriptions[122304]={["a6af2f8bacd6e7dc:65"]="里面的种子已经被火焰之地的高温烤成了焦黑色。"}
D.ItemDescriptions[122306]={["c5a84bbd5493f664:41"]="里面仍然含有微量魔力。"}
D.ItemDescriptions[122393]={["b0d3b5fb68dbd386:74"]="这一部分详细介绍了酿造著名的夜玫瑰深红葡萄酒所需的原料。"}
D.ItemDescriptions[122394]={["06c237391af49bba:82"]="这一部分详细介绍了在调制夜玫瑰深红葡萄酒前必须完成的复杂准备条件。"}
D.ItemDescriptions[122395]={["da69be33041fdffe:92"]="这一部分详细介绍了酿造夜玫瑰的复杂步骤，并给出了每一步的操作方法。"}
