D.ItemDescriptions[122425]={["47373500686261c7:93"]="瓦尔莎拉德鲁伊的知识与教诲都将通过灌输在智慧石中的记忆得到传承。"}
D.ItemDescriptions[122426]={["8e0245ed3fa7279c:41"]="将这瓶鲜血交给被禁锢的小鬼以释放他。"}
D.ItemDescriptions[122429]={["ee94c4b08f30f82f:47"]="里面的书页似乎都烧焦了，已经无法辨认。"}
D.ItemDescriptions[122445]={["da764db330d04bb8:27"]="带有红色和黑色斑点的白色羽毛。"}
D.ItemDescriptions[122446]={["bc0705031840e7a4:40"]="和生产它的堕落野兽一样邪恶。"}
D.ItemDescriptions[122447]={["42b894425a567f8f:14"]="刚从树上掉下来的。"}
D.ItemDescriptions[122469]={["78282fdc5942d741:85"]=S[13093]}
D.ItemDescriptions[122484]={["9993061bc0c14e2c:53"]="内含一件来自黑石铸造厂团队副本的670级物品。"}
