D.ItemDescriptions[128286]={["77b62c8b88fcd8e6:40"]="一张厚实的毛皮，带有浓密、尖锐的鬃毛。"}
D.ItemDescriptions[128288]={["6fa7746fe75f54e6:79"]="真正的力量之源，来自世界深处，也来自每个人的内心深处。"}
D.ItemDescriptions[128289]={["d991a55b271f8082:189"]="……奈萨里奥蜕下的一块鳞片。它救了马格纳的命。黑色的鳞片挡开了汹涌的烈焰，但磅礴的力量将马格纳撞出了巢穴，让他一直滚到了至高岭的山脚下。"}
D.ItemDescriptions[128290]={["5a1157edf61212a2:37"]="是用一种你看不懂的语言写成的。"}
D.ItemDescriptions[128291]={["617746e44b35f183:34"]="用一种你能看懂的语言写成的。"}
D.ItemDescriptions[128292]={["ecdef4dac3efa185:41"]="总有一天，我的生命将抵达终点。而你，将加冕为王。"}
D.ItemDescriptions[128293]={["8e1371455d2d9520:59"]="我要让你见识一下死亡的制裁……以及恐惧的真谛。"}
D.ItemDescriptions[128294]={["0ba2d87cb476ff95:77"]="一份在你的要塞与剩余的鸦人岗哨间建立补给线的合同。"}
D.ItemDescriptions[128301]={["32832b58a92d7579:53"]=S[428]}
