D.ItemDescriptions[128303]={["16a62692fd06822b:58"]=S[427]}
D.ItemDescriptions[128304]={["91c55ecf9cc4f44a:75"]=S[5484]}
D.ItemDescriptions[128305]={["58fa0aef2f8192da:24"]="召唤奥丁的力量。"}
D.ItemDescriptions[128306]={["41c4ca8033abb36d:87"]="但最开始，确实有一个治愈和平衡的源头，一切生灵可以在此处休养生息、重获新生。"}
D.ItemDescriptions[128309]={["9d6d0e19bc8fb050:35"]=S[13094]}
D.ItemDescriptions[128310]={["f175cc93b6fcf812:44"]="剑圣所携带的旗帜和武器。"}
D.ItemDescriptions[128311]={["24146c488b5a7fa3:31"]=S[13087]}
D.ItemDescriptions[128312]={["3af565a0da7a7d57:24"]="闻上去有股淡淡的薰衣草香味。"}
D.ItemDescriptions[128314]={["b2de4f6ebc4f9b4d:36"]="一位已故的德拉诺英雄的遗物。"}
D.ItemDescriptions[128315]={["6cf020b4a1c1d601:23"]="人人都恨燃烧军团。"}
