D.ItemDescriptions[128329]={["600c066b4a97e3ec:58"]="收集魔网能量，让这个喷灯再次熊熊燃烧起来。"}
D.ItemDescriptions[128330]={["45d69f4fe5880294:55"]="腐林食人树的油腻根茎，以苦涩著称。"}
D.ItemDescriptions[128331]={["f2d23e3d722322ac:33"]="由奥丁神创造的魔法橡实。"}
D.ItemDescriptions[128343]={["2ad22a61ec61c05e:42"]="这颗水晶散发着强大的大地能量。"}
D.ItemDescriptions[128345]={["36acfd7a06659519:84"]="各种稀有的维库炼金原料，包括一大批强大的灰烬状粉末。"}
D.ItemDescriptions[128354]={["4fd8be41a23f7a72:28"]="教你学会召唤不高兴。"}
D.ItemDescriptions[128355]={["529741c5a30d44c2:27"]="这是一种花，不是真胡须。"}
D.ItemDescriptions[128356]={["fe1e6ccc122d5b17:37"]="显然它很想回到海里去。"}
D.ItemDescriptions[128357]={["5d237846b2385f7d:21"]="呃……它们“曾经”是干的。"}
D.ItemDescriptions[128367]={["19669a0d83a24244:27"]="这些补给品散发着鱼腥味儿。"}
D.ItemDescriptions[128380]={["eceeb9f73d52e32c:14"]="一根鹰身人羽毛。"}
D.ItemDescriptions[128386]={["e3e220d7fae6ee26:43"]="等等——这不是蛋——这是一个断掉的布林顿脑袋！"}
D.ItemDescriptions[128391]={["c01681f1030670b2:58"]="内含一件来自地狱火堡垒团队副本随机难度掉落的物品。"}
