D.ItemDescriptions[128396]={["9367c081bca20904:72"]="一份有关黑曜石森林的土地被龙息腐蚀情况的详细研究报告。"}
D.ItemDescriptions[128397]={["1850f626716028a9:47"]="可对昆虫产生致命吸引力的信息素。"}
D.ItemDescriptions[128398]={["64f089cd2dcc640a:71"]="上面有一些咬痕，但这件装备似乎不太适合卓格巴尔。"}
D.ItemDescriptions[128402]={["68e28c919d84dfc4:100"]="诅咒之喉的饥渴是永无止尽的。如果吞噬不到新的牺牲品，它就会毫不犹豫地吸取主人的鲜血。"}
D.ItemDescriptions[128403]={["9011e379122ecbb2:92"]="它由毁灭与战争、饥荒与死亡交织而成，以权力为饵，最终带来众生的末日。"}
D.ItemDescriptions[128404]={["46f31cd5102d47a2:12"]="相当强劲。"}
D.ItemDescriptions[128405]={["4c19d3733cc6b7c4:75"]="关于萨隆邪铁矿，以及它与异世界物质的关联性的详细研究报告。"}
