D.ItemDescriptions[128428]={["cbd688bf7b050d3a:54"]="一把附魔的扭曲利刃，用来在躯体上雕刻血符。"}
D.ItemDescriptions[128429]={["a78aca8e86794d73:49"]="非常重要的情报，详细记载了航线及时刻表。"}
