D.ItemDescriptions[128431]={["3dcddb2f47836298:59"]="尸体早已冷去，但魔血依然灼热。"}
D.ItemDescriptions[128432]={["74d9f3aabb137db1:99"]="列举有姓名和地点，有些是用密文写成。这份重要的情报能够揭示出古尔丹在塔纳安的行动计划。"}
D.ItemDescriptions[128433]={["ab9f9932e339cf95:70"]="虽未经打磨，但只要有人在附近施法，这些矿物就会发出能量脉冲。"}
D.ItemDescriptions[128434]={["f9469f181ab1b989:72"]="经过精心设计的火炮几乎不会让戈隆感受到它的重量，而且可以随时开火。"}
D.ItemDescriptions[128438]={["8a9f98457354ea9a:48"]="塔纳安的食草动物都有着锋利的牙齿。"}
D.ItemDescriptions[128443]={["a751b670f2720f35:66"]="一捆月棘树枝，经过了一口古老月亮井井水的净化。"}
D.ItemDescriptions[128472]={["5e5296bebd7704ed:51"]="内含一整套霜狼氏族所穿的皮甲。"}
D.ItemDescriptions[128473]={["38b60d10fcf8935f:52"]="内含一整套卡拉波祭司所穿的布甲。"}
D.ItemDescriptions[128476]={["ae2a409b66e8706e:99"]="即使在猎犬死后很久，其撕咬造成的伤口仍然迟迟无法愈合。对于如此粗糙的武器而言，其效果意外出色且神奇。"}
