D.ItemDescriptions[128655]={["d9b41a5899a863e5:46"]="体型很小，足以当成炮弹塞入小动物手炮。"}
D.ItemDescriptions[128658]={["0c51153b4fdef8d6:42"]="可以在你要塞的活动组织者处兑换。"}
