D.ItemDescriptions[128664]={["4a29d6248c4fbdb3:46"]="一盒幽灵老鼠、蛆虫和蜘蛛。"}
D.ItemDescriptions[128665]={["78ef13f11b5e1fbe:34"]="一套节日专用的彩灯和花环。"}
