D.ItemDescriptions[128667]={["c38b12d08b8e33f5:38"]="冬幕节助手和一个冬幕欢乐制造器。"}
D.ItemDescriptions[128668]={["1211fdbf7b661fe8:36"]="为你的要塞守卫穿上当季的服装。"}
D.ItemDescriptions[128669]={["6eecf0b8d6b71ce7:46"]="一套糖棒、槲寄生和袜子。"}
