D.ItemDescriptions[128676]={["57e20e63a98df580:43"]="这些滴定管无法精确地测量液体。"}
D.ItemDescriptions[128679]={["4d99a17c783324a7:69"]="这个坩埚的内胆已经修补好了，但似乎还需要回火。"}
