D.ItemDescriptions[128693]={["ac8826405677c229:80"]="一张德拉诺海图，上面还煞费苦心地标上了许多魔法符号和导航信息。"}
D.ItemDescriptions[128706]={["78282fdc5942d741:85"]=S[13093]}
D.ItemDescriptions[128707]={["ff4d0eca116940f3:35"]="详细介绍了阿苏纳的侦察结果。"}
D.ItemDescriptions[128712]={["59846fbea2e8310f:63"]="一张随机的暗月军团卡片。集齐全套即可获得奖励。"}
D.ItemDescriptions[128745]={["b289021604a1a553:51"]="传奇铁匠萨里斯·迅锤的锤子。"}
D.ItemDescriptions[128746]={["a7d340b237b2ffc1:65"]="这本书里记载了萨里斯·迅锤关于魔石锻造的所有心得。"}
D.ItemDescriptions[128747]={["de9a7d9977d8244e:39"]="详细介绍了瓦尔莎拉的侦察结果。"}
D.ItemDescriptions[128748]={["41e749e3f3c6b6d2:41"]="详细介绍了至高岭的侦察结果。"}
D.ItemDescriptions[128749]={["d4700fb09a990ef1:38"]="详细介绍了风暴峡湾的侦察结果。"}
D.ItemDescriptions[128751]={["bee4355de9f1c1f6:64"]="一件极其坚固的胸甲，使用了建造黑鸦堡垒的石料制成。"}
D.ItemDescriptions[128752]={["07759b3d9fee4e9c:48"]="一块易碎的水晶，可以用来囚禁一只恶魔。"}
D.ItemDescriptions[128753]={["fff08b20394de3d5:43"]="狗头人用颅骨来代表权力。"}
D.ItemDescriptions[128754]={["deed0281bda66db4:21"]="这根蜡烛上燃烧着黄色的火焰。"}
D.ItemDescriptions[128755]={["4a46f2560006ab51:20"]="这根蜡烛上燃烧着绿色的火焰。"}
D.ItemDescriptions[128757]={["f3297482990fcbc3:27"]="一些脆弱的鹰蛋。"}
D.ItemDescriptions[128758]={["5eab2fb0da2b9993:44"]="鲜美可口，但大量食用也会致命。"}
D.ItemDescriptions[128759]={["b93592cf86c1e732:28"]="在任何光照条件下都能闪闪发光。"}
D.ItemDescriptions[128760]={["ddc851dd7ba4abd0:49"]="一枚巨大但脆弱的至高岭巨鹰蛋。"}
D.ItemDescriptions[128763]={["84e51b5f77f8a720:30"]="据说放得越久会越‘好吃’。"}
D.ItemDescriptions[128764]={["10c3729e88705939:24"]="有着美丽的乳白色纹理。"}
D.ItemDescriptions[128765]={["38149bbc03b4b4e1:31"]=S[20123]}
D.ItemDescriptions[128767]={["a13b0bfe75cbffff:96"]="这把矿锄是用阿苏纳海岸的沙子铸造而成的，轻便但是脆弱，在使用时一定要小心。"}
D.ItemDescriptions[128769]={["16da145a98cda551:23"]="精心开采出来的魔石。"}
D.ItemDescriptions[128770]={["9d6d0e19bc8fb050:35"]=S[13094]}
D.ItemDescriptions[128771]={["4535a3a34a057a2a:63"]="感染珀疫的铁角驯鹿的鹿角。"}
D.ItemDescriptions[128773]={["716ba14d45b21e0c:73"]="一块极其厚实的肉排，因其可提供极高的能量而受到猎人们欢迎。"}
D.ItemDescriptions[128774]={["3483f656b64f864d:48"]="这条大尾巴里包含着多汁的龙虾肉。"}
D.ItemDescriptions[128775]={["68fc3940becdbe67:42"]="一枚刻有塞纳留斯徽记的小硬币。"}
D.ItemDescriptions[128777]={["572ce6ee9e383f4b:37"]="用于奥拉尔德·施米尔的特别项目。"}
D.ItemDescriptions[128778]={["0caac53dedce665e:54"]="这块奇怪的水晶经过了处理，可以盛放魔法材料。"}
D.ItemDescriptions[128779]={["533e400a3066959d:26"]="北郡标准口粮。"}
D.ItemDescriptions[128780]={["10f072d05b966069:26"]="幽影谷标准口粮。"}
D.ItemDescriptions[128781]={["65b42f9e1c1a3e2d:24"]="安威玛尔标准口粮。"}
D.ItemDescriptions[128782]={["75384e03bf144692:29"]="新工匠镇标准口粮。"}
D.ItemDescriptions[128783]={["9d47e0469cba55f5:21"]="阿古斯标准口粮。"}
D.ItemDescriptions[128784]={["6f524b67b2eb2d54:23"]="吉尔尼斯标准口粮。"}
D.ItemDescriptions[128785]={["4d25d8b6bce983b7:23"]="尚喜武院标准口粮。"}
D.ItemDescriptions[128786]={["00d5f25d58ef764e:24"]="太阳之塔标准口粮。"}
D.ItemDescriptions[128787]={["8942699d92b461ee:21"]="科赞标准口粮。"}
D.ItemDescriptions[128788]={["c1b37261912cea24:25"]="暗矛标准口粮。"}
D.ItemDescriptions[128789]={["51f73cdba3afae8e:19"]="大兽穴标准口粮。"}
D.ItemDescriptions[128790]={["ad049a970aacb19e:27"]="纳拉其营地标准口粮。"}
D.ItemDescriptions[128791]={["26c75240d367da69:26"]="丧钟镇标准口粮。"}
D.ItemDescriptions[128793]={["3cd831ba9807b521:20"]="你藏着这种东西干什么？"}
D.ItemDescriptions[128794]={["91d2974e8e6a6503:35"]="总能冒出更多幽灵蜘蛛。"}
D.ItemDescriptions[128801]={["8cb2fef4c347a343:71"]="这块水晶里的矩阵已经被纳瓦罗格篡改过，可以严重破坏卓格巴尔仪式。"}
D.ItemDescriptions[128803]={["d9e746f3b0ad49b2:53"]=S[16103]}
D.ItemDescriptions[128808]={["4fb1cdbf93dc84ae:99"]="雄鹰之矛、荒野诸神之矛、雄鹰之爪。它有许多名字，也承载了众多祝福，它是一件传奇武器。"}
D.ItemDescriptions[128809]={["72410d0cd5965729:52"]="大领主莫格莱尼将带回一位我们的骑士，可会是谁呢？"}
D.ItemDescriptions[128810]={["c2ca15a2aabd995b:21"]="完美的样本！"}
D.ItemDescriptions[128813]={["0a57e7e1e337e5a2:34"]="充斥着邪能能量的脉动核心。"}
D.ItemDescriptions[128819]={["4debc2d9e87c51b0:59"]="一位陌生人将高举这把战锤，将正义带回凡世。"}
D.ItemDescriptions[128820]={["be010a8914a6360e:153"]="……这不是精灵的武器。在经过魔法、仇恨与熊熊燃烧的复仇渴望的重新锻造后，它们已经不是了。不，阿尔萨斯。烈焰之击比过去更加强大——我也一样。——凯尔萨斯·逐日者"}
D.ItemDescriptions[128821]={["9ba83f298868eaec:89"]="乌索克，乌索尔的兄弟，熊怪部族的守护者……森林之力的继承者。"}
D.ItemDescriptions[128822]={["ce878c493ec57674:56"]="艾泽拉斯很快就会需要你们。如果你们不做好准备，世界就将陨落。"}
D.ItemDescriptions[128823]={["ba3ac0aaa69f03c9:158"]="提尔解释道，他并不把自己的白银之手视为失败的象征。对他来说，这象征着他为了守护艾泽拉斯而付出的牺牲，他希望这个世界也如此看待它。"}
D.ItemDescriptions[128824]={["f2053956fbd0aa77:21"]="我们以鲜血捍卫荣誉。"}
D.ItemDescriptions[128825]={["1449ecf59e1a87ce:53"]=S[2619]}
D.ItemDescriptions[128826]={["d77f0d479f62a2c0:126"]="从太阳井中取出后，这把弓能量四溢。塔拉纳斯满怀敬畏地接受了这份礼物，并将它命名为萨斯多拉，意为“森林的勇气”。"}
D.ItemDescriptions[128827]={["5058be28690e8c43:160"]="萨拉塔斯有自己的思想。不要理会它疯狂的耳语，不要相信它的谎言。让它为你所用，但别忘了，这把利刃中的黑暗存在，并不是你的盟友。"}
D.ItemDescriptions[128831]={["a38ea4c54bdfa250:161"]="托兰纳尔的战刃在喧嚣的战场上咆哮，撕碎靠近他的一切敌人。每消灭一头恶魔，似乎都能为托兰纳尔注入新的活力和力量。他一个人就抵得上一支大军。"}
D.ItemDescriptions[128832]={["5767cd3a64c760bf:132"]="奥达奇是一个骄傲的民族，不愿臣服于任何人。恶魔付出了数百万伤亡的代价才灭绝了他们，而他们的国王更是由萨格拉斯亲自出手击杀的。"}
D.ItemDescriptions[128850]={["01abb4d81e60c24f:21"]="不知为何，这种水总是冷冰冰的。"}
D.ItemDescriptions[128852]={["bf8a69fe6c8c074b:38"]="一块散发着恶臭的恶魔石核。"}
D.ItemDescriptions[128855]={["dfc727ec03dfa0a5:80"]="这块盾牌所用的木头还没有完全烂掉，所以还能抵挡几次攻击。"}
D.ItemDescriptions[128856]={["2af9d2204b38aa77:69"]="它已经不再锋利了，但至少还不会断掉。"}
D.ItemDescriptions[128858]={["4e0fd4c25960b5c3:91"]="蕴含着需要被释放的力量。在平衡与控制的作用下，野狼也能被驯服，但这只是暂时的。"}
D.ItemDescriptions[128859]={["03adc65175423dca:192"]="她曾撕开恶魔的阵线，然后消失在树林里。她曾从高悬的树枝上一跃而下，击倒燃烧军团的指挥官。她是一头可怕的野兽，从不退缩，从不手软。"}
D.ItemDescriptions[128860]={["7bbf9bfb4b5bfb96:124"]="直至今日，人们依然铭记着阿莎曼的牺牲。我们因她的仁慈而得以生存，她的子嗣至今仍在森林中出没，是我们最亲密的伙伴。"}
D.ItemDescriptions[128861]={["f106dde0c3f83595:72"]="魔法科技工程学的完美典范，灌注了风暴的能量。"}
D.ItemDescriptions[128862]={["ca0fb01e93effcb1:98"]="黑檀之寒中只包含了阿洛迪的一丝力量，但是即便是这么一点，也足以让大多数法师望尘莫及。"}
D.ItemDescriptions[128864]={["7d5ab7926f726a07:38"]="山羊的唾液已经令上面的墨水模糊了。"}
D.ItemDescriptions[128866]={["e21fbfde3028f24b:211"]="锤头第一次落下，寒冰山脉中喷溅出熔岩之河。第二次，天空嚎叫嘶鸣，闪电点燃了天际。第三次，一道阳光穿透了雷云，对真理守护者的盾面呢喃。"}
D.ItemDescriptions[128867]={["fc4f57c6db56cf53:115"]="为了杀戮而杀戮……为了征服而征服……这种事毫无荣耀可言。它们只会带来耻辱和悔恨。"}
D.ItemDescriptions[128868]={["6b8024656c322cf2:116"]="它承载着我们当日最殷切的期望和最诚挚的祷告……失去它是我们最刻骨铭心的伤痛。"}
D.ItemDescriptions[128869]={["27f2e5bfbe81a888:183"]="虽然不得善终，但他至少死得迅速、安静、迅速。当他咽下最后一口气时，致命伤口非常不规则。没有人能看出来，他到底是死于匕首、战斧还是长矛之下。"}
D.ItemDescriptions[128870]={["775d4e9d1ca48f74:139"]="在他一时兴起的邪恶指令下，无数人死于非命，无数领袖跌下云端。这种行为已经无药可救，等着他的只有孤独和悲伤。"}
D.ItemDescriptions[128872]={["f6c914b459f39ad3:192"]="她看到自己号令着一支举世无双的海盗舰队，足以征服艾泽拉斯的所有海域，所有国度。任何胆敢挑战她的舰船都会在炮火中灰飞烟灭，所有的城市，要么拱手献上他们的财宝，要么被夷为平地。"}
D.ItemDescriptions[128873]={["8210d4ab3c5f9794:66"]="以毁灭之锤以及持有它的强大萨满的力量铸成。"}
D.ItemDescriptions[128875]={["5be15dd25acd9653:43"]="蛆虫留下了它们消化不了的部分。"}
D.ItemDescriptions[128908]={["430016bbdf33d636:84"]="海拉的背叛不可原谅。她必将远离英灵殿，在起伏的波涛之下腐烂。"}
D.ItemDescriptions[128910]={["92ea1e725cfc62d7:119"]="野蛮人王者打出最后一击的钢剑。它将平息战争的喧嚣，将第一个人类王国带入一个和平的纪元。"}
D.ItemDescriptions[128911]={["32f5213b5f52a8e2:147"]="艾萨拉和她的上层精灵沉入了深海，可他们并没有被击垮。无穷无尽的黑暗包裹着他们，于是女王命令莎拉达尔带来光明……"}
D.ItemDescriptions[128921]={["055815112bfb1102:35"]="整个城市的法师累积下来的残渣。"}
D.ItemDescriptions[128922]={["dfede5770f8e5e38:50"]="在炼金师中俗称“液火”。"}
D.ItemDescriptions[128923]={["ed1bd8b1eb2d62a6:57"]="特别制作出来，用于隔绝热量和魔网能量。"}
D.ItemDescriptions[128924]={["69ea5f7e7093666b:64"]="比起魔法更偏向机械。或许它是从工程学商店里买来的？"}
D.ItemDescriptions[128933]={["61087244ce4e3929:51"]="这只琥珀色的眼睛散发着柔和温暖的光，吸引着你靠近去看。"}
D.ItemDescriptions[128934]={["098d8bb4161ebf49:167"]="海洋即将夺走他们的生命时，远古生物在黑暗中兴风作浪。它们的呢喃在海水中搅动，它们的力量包裹着女王与上层精灵。"}
D.ItemDescriptions[128935]={["bb00aaf3441c87f8:149"]="为了摧毁奥拉基尔，主宰莱将自己的拳头砸进了山顶。天空裂开一条大口子，烈焰与怒火降到风元素领主的头上。"}
D.ItemDescriptions[128936]={["bf18ede79c97c8e2:157"]="莱和海拉制造了一面盾牌，至高守护者之盾，作为进入元素位面的钥匙。它充盈着四大元素的能量，莱可以在需要时召唤出元素之力。"}
D.ItemDescriptions[128937]={["03864598879e3977:178"]="你寻求的是不动声色但又不可阻挡的大河之力，足以切开最坚固的石头形成峡谷，足以冲走无数战士而不会泛起一点涟漪。神龙就是这一理念的化身。"}
D.ItemDescriptions[128938]={["14db61d02e218f09:130"]="从一开始，这根法杖就伴随着那些传奇生物与不朽英灵前往艾泽拉斯各地完成各种意义重大、影响深远的任务。"}
D.ItemDescriptions[128940]={["acf70cff7d5fc252:88"]="当伊尔马特举起他的武器，测试它们的力量时，无法控制的怒火爆发了出来。"}
D.ItemDescriptions[128941]={["2f31841dbeedf754:169"]="当耐奥祖最终采取行动时，他没有半分犹豫，也不考虑后果。他完全不在乎德拉诺是否会毁灭。事实上，他很期待这也能成为他的一部分遗产。"}
D.ItemDescriptions[128942]={["d5fe55254fab747a:143"]="这把镰刀的主人如果不能征服萨泰尔，就会被它吞噬，使它变得更强大。接着，下一任拥有者将取代他的位置，然后是再下一任。"}
D.ItemDescriptions[128943]={["86b7e37cb36289ad:210"]="当萨奇尔最终现身时，他完全变了。他老了几百岁，在黑暗中陪伴他的只有思绪和奴隶。他的背脊扭曲弯折，眼中闪着诡异的光芒。他召唤他的启迪者，而我们响应了召唤。"}
D.ItemDescriptions[128960]={["5e464089a95410dc:58"]="使用这个奥丁制造的魔法装置净化被诅咒的维库人。"}
D.ItemDescriptions[128966]={["40616aa109391858:37"]="瓦尔莎拉某个强大恶魔的位置。"}
D.ItemDescriptions[128967]={["91d4de79fc4ac052:37"]="瓦尔莎拉某个泰坦圣物的位置。"}
D.ItemDescriptions[128968]={["264a263ee8bee9c9:39"]="有关梦魇入侵计划的情报。"}
D.ItemDescriptions[128969]={["63097bb86e887867:36"]="风暴峡湾某个强大恶魔的位置。"}
D.ItemDescriptions[128970]={["cd51496c5a2771f7:39"]="风暴峡湾某个力量祭坛的位置。"}
D.ItemDescriptions[128971]={["103d535d36d970f0:36"]=S[14329]}
D.ItemDescriptions[128972]={["311d98eb00da45dc:39"]="至高岭某个强大恶魔的位置。"}
D.ItemDescriptions[128973]={["bad0fa1f789b784c:42"]="至高岭某个力量祭坛的位置。"}
D.ItemDescriptions[128975]={["103d535d36d970f0:36"]=S[14329]}
D.ItemDescriptions[129032]={["1fc158fb77cc2e8e:52"]=S[14347]}
D.ItemDescriptions[129033]={["18c0af1f1f1b0b56:48"]="这似乎大概可能是一叠炉石套牌。"}
D.ItemDescriptions[129034]={["1fc158fb77cc2e8e:52"]=S[14347]}
D.ItemDescriptions[129037]={["a397ebcee71ba44f:30"]="猎人就要有猎人的样子。"}
D.ItemDescriptions[129043]={["498bc4b6e4f55a83:34"]="帕林教授的合同，已经签好了。"}
D.ItemDescriptions[129047]={["fc51d66b85956e68:79"]="一份典型的合同，你所有的知识产权将在你身亡之后移交给联署人……"}
D.ItemDescriptions[129054]={["929a3b134fe86b04:41"]="这是欧库纳的鱼竿。他肯定就在附近。"}
D.ItemDescriptions[129057]={["0427e01c3c872a03:31"]="附加了魔法，总能击中目标。"}
D.ItemDescriptions[129064]={["7bf3c80a80ea7b19:54"]="一股神秘的魔法力量将这些金属板紧紧联结在了一起。"}
D.ItemDescriptions[129072]={["b870a24c363f9fc3:75"]="这是墨古尔从托格尔那里抢来的，托格尔是从鲁格尔那里偷来的，鲁格尔是杀了普格拿到的，普格……"}
D.ItemDescriptions[129073]={["d45d0ac390924362:63"]="在破碎群岛的海地精中，苦水的戒指是独一无二的。"}
D.ItemDescriptions[129078]={["0b1dbb29669d5d5a:58"]="一位出身高贵的女士不会因为任何原因丢掉漂亮的鞋子。"}
D.ItemDescriptions[129079]={["e82fd8e29c806efb:93"]="虽然拜尔班的大部分实验都没成功，他的靴子对胆汁的抵抗力却意外地高。"}
D.ItemDescriptions[129084]={["23fd8279346cf828:41"]="这件环甲里卡着许多树枝和稻草。"}
D.ItemDescriptions[129090]={["ea3db69ec92fee93:41"]="弗洛格并不在乎他们是不是真的船长。"}
D.ItemDescriptions[129092]={["9f39437c0d1d6557:41"]="来自风行全球的《炉石传说》的一张卡牌。"}
D.ItemDescriptions[129094]={["09c5ac76f9bd8ed7:37"]="让一名堕夜精灵完全恢复力量。"}
D.ItemDescriptions[129095]={["1351dc9c3aa239b1:33"]="一小块充斥着邪能的水晶。"}
D.ItemDescriptions[129107]={["6f25b276e30afce7:35"]="这只恶魔敢于嘲笑死亡……"}
D.ItemDescriptions[129108]={["9d6d0e19bc8fb050:35"]=S[13094]}
D.ItemDescriptions[129113]={["1bd5cd89a5bb2a7a:29"]="为什么会有人喝这种玩意儿？"}
D.ItemDescriptions[129117]={["c7441f5001b24d2d:63"]="这朵半透明的花朵显然是魔法的产物，但却出人意料的耐久。"}
D.ItemDescriptions[129118]={["685975ebf2cb1780:62"]="只有训练有素的草药师才能在不害死植株的情况下分离出这种叶片。"}
D.ItemDescriptions[129119]={["e7cdea61e54a9d04:82"]="这朵花散发着一种既恶心又诱人的气味。"}
D.ItemDescriptions[129120]={["7f4c3ead03839be0:36"]="多刺，粗糙，很难处理。"}
D.ItemDescriptions[129121]={["746b6cee440b721d:30"]="花朵在你的手中消散。"}
D.ItemDescriptions[129122]={["3d3b2ed766aec1ce:41"]="说是植物，更像是恶魔，整个球茎都散发着愤怒的气息。"}
D.ItemDescriptions[129123]={["2884bdb523b2ca70:76"]="挂满了这位船长获得的各种奖章，后来被其他船长纷纷效仿。"}
D.ItemDescriptions[129124]={["4e8b1109e6224974:59"]="出自蔑潮者之手，它躲过了族人的批判，内容非常病态。"}
D.ItemDescriptions[129128]={["32867c5d33abd356:40"]="你所见过的最夸张俗艳的雌蕊。"}
D.ItemDescriptions[129131]={["7eef0052b47eb83d:54"]="通常来说，巨大的雄蕊说明这棵植物的根系也很大。"}
D.ItemDescriptions[129133]={["5c18eb7e349848bd:67"]="用她的盾牌碎片制成，上面的金属环跟任何盾牌一样结实。"}
D.ItemDescriptions[129135]={["18c6305d6e56a724:25"]="一块扯破的丝绸。"}
D.ItemDescriptions[129136]={["b0d3f3712d39d61a:59"]="叶片卷得紧紧的，已经从植株上脱离了。"}
D.ItemDescriptions[129137]={["053f48d094b10c71:36"]="布满了细小的齿痕。"}
D.ItemDescriptions[129138]={["6c9b5cc0a9a01ed7:45"]="刻满符文的手柄显示出它是源于维库文化。"}
D.ItemDescriptions[129139]={["130bb335c4b4e458:76"]="教你学会德拉诺探路者，允许你在德拉诺飞行，别以为这是作弊。"}
D.ItemDescriptions[129140]={["13511aaed4a72a3b:46"]="一件挖掘工具的柄，和刃的部分脱离了。"}
D.ItemDescriptions[129141]={["a4fdd311ad01d792:56"]="这片叶子已经完全被邪恶的梦魇能量熏死了。"}
D.ItemDescriptions[129142]={["3fd9250b1a927b2c:24"]="一张撕下来的维库书页。"}
D.ItemDescriptions[129143]={["6d5cd30503e52f82:55"]="某个显然已经陷入疯狂的人的手写笔记。"}
D.ItemDescriptions[129149]={["2df2225c74cea777:27"]="让你想起在冥狱深渊的时光。"}
D.ItemDescriptions[129150]={["690cc6d61399f063:29"]="这棵植物充沛的生命力几乎都要溢出来了。"}
D.ItemDescriptions[129151]={["9960491228562171:49"]="虽然还活着，但这片叶子已经扭曲并极度渴望空气。"}
D.ItemDescriptions[129153]={["65017e7472ff447d:73"]="堕夜精灵会咀嚼安瑟瑞尔花，直到吸干里面的魔法能量。"}
D.ItemDescriptions[129155]={["a145c12fba8ee4e4:45"]="这根断掉的铲子上还附有微弱的魔力。"}
D.ItemDescriptions[129158]={["92e76da0074b3ff5:21"]="一堆无法使用的粉尘。"}
D.ItemDescriptions[129159]={["7756574fa326dc3c:69"]="完全就是某位工程师的随手涂鸦，无法理解。"}
D.ItemDescriptions[129164]={["338390c1e2bec1c4:45"]="一块古老的石板，上面刻着古老的维库文字。"}
D.ItemDescriptions[129169]={["d7123926f1371c3b:76"]="一把用古代维库秘法师的骨头制成的小刀，上面刻有强大的符文。"}
D.ItemDescriptions[129170]={["ad52ce34a2c9d563:28"]="一位”诚实“商人的印记。"}
D.ItemDescriptions[129173]={["f9d69dd5ec7163b6:65"]="这些破损的书页上只能勉强辨认出记录者裂蹄的名字。"}
D.ItemDescriptions[129174]={["d8844d5cd7ec03af:34"]="刻着他所属海船的名字，“纳格法尔号”。"}
D.ItemDescriptions[129175]={["9d6d0e19bc8fb050:35"]=S[13094]}
D.ItemDescriptions[129176]={["8033ca212b36b9a2:54"]="古隆的日志，记载着他在附魔方面的丰富知识。"}
D.ItemDescriptions[129177]={["f9ed16e601abdd73:88"]="一张旧塔罗牌，边缘已经烂了，但在阳光下还能看到一丝魔力反光。"}
D.ItemDescriptions[129178]={["9d6d0e19bc8fb050:35"]=S[13094]}
D.ItemDescriptions[129179]={["1bb4f5b8d8f52a19:39"]="专为激烈的战斗和健康的体魄而烹制。"}
D.ItemDescriptions[129183]={["08c23c6f92727c26:23"]="以一碰就炸而著称。"}
D.ItemDescriptions[129188]={["9d6d0e19bc8fb050:35"]=S[13094]}
D.ItemDescriptions[129190]={["74f5e2e665a61333:25"]="一种团队建设时用的道具。"}
D.ItemDescriptions[129191]={["a42b3f40c1eef45d:61"]="有点发潮发霉，但这不妨碍鱼人使用。"}
D.ItemDescriptions[129193]={["2e87fc5bc5550218:43"]="结实的皮革，切割后专门用来装订书籍。"}
D.ItemDescriptions[129194]={["81b48393f24070ec:50"]="简单的金属环，用来加固装订书籍。"}
D.ItemDescriptions[129197]={["db5c32a8fca27141:38"]="一件古代暗夜精灵的艺术杰作。"}
D.ItemDescriptions[129199]={["fd464bb2b302d6e9:39"]="当代蔑潮族长的徽章。"}
D.ItemDescriptions[129203]={["78bbe5d033e4108b:58"]="这枚树妖制作的指环能够吸收原始怒火本身。"}
D.ItemDescriptions[129205]={["0046052ae33b28ff:29"]="教你学会召唤邪能幼崽。"}
D.ItemDescriptions[129206]={["fd5cbebcb4968f1b:42"]="这枚散发着死亡恶臭的戒指中透出一道金光。"}
D.ItemDescriptions[129207]={["9f7996b7cd938666:86"]="作为创世之柱之一，阿格拉玛之盾以泰坦之力保护着它的持有者。"}
D.ItemDescriptions[129208]={["9d6d0e19bc8fb050:35"]=S[13094]}
D.ItemDescriptions[129209]={["700f87f6bbaa663f:61"]="内含塔里隆所知道——或者曾经知道的——一切草药学知识。"}
D.ItemDescriptions[129212]={["acea594d65168aee:60"]="一系列关于邪能球茎可能的生长模式的详细记录。"}
D.ItemDescriptions[129213]={["e37d31fa9c56048d:29"]="主要介绍了邪能球茎的解剖情况。"}
D.ItemDescriptions[129214]={["b400772b52b4c818:37"]="主要介绍了邪能球茎的剧毒成分。"}
D.ItemDescriptions[129215]={["1f03618562582048:80"]="这枚树妖制作的指环燃烧着从萨斯塔拉的鹰身人那里吸收来的仇恨和怒火。"}
D.ItemDescriptions[129216]={["2b3d5c0c60f14661:42"]="教你学会召唤活跃的嗜魔者。"}
D.ItemDescriptions[129217]={["346227d702f70dfc:42"]="教你学会召唤强化的嗜魔者。"}
D.ItemDescriptions[129218]={["f46ad0eed283aac9:41"]="教你学会召唤以太嗜魔者。"}
D.ItemDescriptions[129220]={["98557c2040cca1a5:21"]="似乎非常美味。"}
D.ItemDescriptions[129276]={["df0358c0fb4a3067:108"]="这本可以在一周内掌握的七步速成宝典提供了各种必要的知识。*免责声明：仅含少量知识。"}
D.ItemDescriptions[129277]={["9d6d0e19bc8fb050:35"]=S[13094]}
D.ItemDescriptions[129278]={["15a1052cd0489e4b:31"]="小到几乎看不见。"}
D.ItemDescriptions[129279]={["2394a37c36d3eef9:70"]="在他最喜欢的童年宠物过世后，送给年轻的法罗迪斯王子的礼物。"}
D.ItemDescriptions[129280]={["24146c488b5a7fa3:31"]=S[13087]}
D.ItemDescriptions[129283]={["55eaab16258d270f:99"]="我，食魂者阿莱利，正式请求大法师星歌协助对抗燃烧军团。"}
D.ItemDescriptions[129284]={["91c55ecf9cc4f44a:75"]=S[5484]}
D.ItemDescriptions[129285]={["91c55ecf9cc4f44a:75"]=S[5484]}
D.ItemDescriptions[129286]={["91c55ecf9cc4f44a:75"]=S[5484]}
D.ItemDescriptions[129287]={["91c55ecf9cc4f44a:75"]=S[5484]}
D.ItemDescriptions[129288]={["91c55ecf9cc4f44a:75"]=S[5484]}
D.ItemDescriptions[129289]={["91c55ecf9cc4f44a:75"]=S[5484]}
D.ItemDescriptions[129290]={["ed69cf3b8e8da04e:66"]="许多书页的边缘都潦草地写着“我宁可不要\"。"}
D.ItemDescriptions[129291]={["c92f13f81e9f9bed:44"]="装饰有大量风暴幼龙的鳞片。"}
D.ItemDescriptions[129292]={["04614e1a6d7430d7:59"]="他们真不该把这些宝石就这样放在柜台上。"}
D.ItemDescriptions[129293]={["9fd3ec3eb3c43eed:60"]="这件物品散发着一位古代维库女附魔师的力量。"}
D.ItemDescriptions[129294]={["e813353dc348e424:70"]="维库骨语部族的狂战士身上所描绘的传统图案。"}
D.ItemDescriptions[129295]={["394bcfa45098b895:23"]="不再仅对苦力使用！"}
D.ItemDescriptions[129356]={["0952d25fc59357de:43"]="这只古老的酒桶上带有艾萨拉女王的印记。"}
D.ItemDescriptions[129362]={["9d6d0e19bc8fb050:35"]=S[13094]}
D.ItemDescriptions[129370]={["2f53cfb1371c5ebe:66"]="代表对其邪恶女王忠诚的纳迦徽记所分解出的残留物。"}
D.ItemDescriptions[129371]={["cdb92ffd67e643da:84"]="积怨纳迦所佩戴的徽记，代表其对艾萨拉女王的忠诚。可分解出背叛之尘。"}
D.ItemDescriptions[129372]={["382e35e3c4044ab6:63"]="作为一名正直的绅士，杰瑞喜欢在打劫受害者之前先警告他们一下。"}
