D.ItemDescriptions[130937]={["1cccd861c62aa0d0:16"]="护腕用的腕轮。"}
D.ItemDescriptions[130942]={["85efb5ca11792391:28"]="切割工艺、色彩和纯净度都很完美。"}
D.ItemDescriptions[130943]={["0a3c0387381b1e2e:56"]="带有精致传统的烟林牧场商标。"}
D.ItemDescriptions[131346]={["ad7003b61c989981:38"]="保护你不受水中其他生物的侵害。"}
