D.ItemDescriptions[131544]={["857093da78c094c3:28"]="就在那里，只是你看不到而已。"}
D.ItemDescriptions[131646]={["90c2ad5d07dc437e:39"]="使用真正的黑熊皮手工缝制而成。"}
D.ItemDescriptions[131647]={["dc0a51b75dae9eae:37"]="这副手套似乎已经在太阳下面晒了很久了。"}
D.ItemDescriptions[131683]={["90820ba75375ee2a:14"]="有点重。"}
D.ItemDescriptions[131689]={["d2257460542ddfbb:19"]="让你免受感染！"}
