D.ItemDescriptions[131719]={["6d61f37cbe37e36b:52"]=S[20187]}
D.ItemDescriptions[131720]={["51166d1215f7ec4f:27"]="双子狱卒中斯勒基的精华。"}
D.ItemDescriptions[131721]={["a406bcbab4a3292f:28"]="双子狱卒中库拉什的精华。"}
D.ItemDescriptions[131722]={["8c3e186c2dd29059:72"]="怪物伊莫拉斯的力量已经凝聚成了一颗高度浓缩的小珠子。"}
D.ItemDescriptions[131723]={["6fbdca81ad9dc594:72"]="这块石头上燃烧着邪能之火。所有触摸它的凡人都会被活活烧焦。"}
D.ItemDescriptions[131734]={["24146c488b5a7fa3:31"]=S[13087]}
D.ItemDescriptions[131737]={["390c904bc29dfcf0:7"]="宠物"}
D.ItemDescriptions[131743]={["fa303f47ee378c92:99"]="古老的浓缩恶魔精华，放入抑魔金熔炉后会释放出庞大的能量。"}
D.ItemDescriptions[131752]={["174e7c3536da8c54:41"]="封底绣着两个字母H.H。"}
D.ItemDescriptions[131753]={["0cbfea1df2fa64f2:32"]="捆扎的皮带已经陈旧褪色了。"}
D.ItemDescriptions[131757]={["d13fd5b08b54e691:52"]="松岩盆地的某些居民对其格外敬畏。"}
D.ItemDescriptions[131758]={["d13fd5b08b54e691:52"]="松岩盆地的某些居民对其格外敬畏。"}
D.ItemDescriptions[131763]={["5431341d5a73e1c8:28"]="这肯定是某个人弄丢的。"}
D.ItemDescriptions[131766]={["5fd8962f708d4504:11"]="拿来烧的。"}
D.ItemDescriptions[131768]={["ff02f18ff42a3188:25"]="大部分镜头都碎了。"}
D.ItemDescriptions[131773]={["6b8e86c4cf58b139:24"]="通常使用海水淬火。"}
D.ItemDescriptions[131775]={["030afd2e7af74699:35"]="上面只剩一点点玩具碎片了。"}
D.ItemDescriptions[131777]={["bec27724ab0134f5:21"]="栩栩如生，令人印象深刻。"}
D.ItemDescriptions[131778]={["bec27724ab0134f5:21"]="栩栩如生，令人印象深刻。"}
D.ItemDescriptions[131780]={["200dd618a9fda103:29"]="暗影轻抚着你的双脚。"}
D.ItemDescriptions[131781]={["4616dcdd54a22b32:35"]="质量差强人意……不过十分耐用。"}
D.ItemDescriptions[131782]={["0b88738c32a94929:3"]="送给"}
D.ItemDescriptions[131784]={["0b88738c32a94929:3"]="送给"}
D.ItemDescriptions[131788]={["a4b72198df03d9ff:63"]=S[1206]}
D.ItemDescriptions[131789]={["a4b72198df03d9ff:63"]=S[1206]}
D.ItemDescriptions[131794]={["f7591b16a50b5bc7:39"]="上面的珠子是用木头和兽骨雕成的。"}
D.ItemDescriptions[131803]={["c5794124ca0428c3:24"]="每个猎人都喜欢战利品。"}
D.ItemDescriptions[131809]={["24f423fe03642405:17"]="充斥着魔力。"}
D.ItemDescriptions[131810]={["80ad78e6ae39b229:59"]="这个褪色的风筝已经失去了往日的光鲜亮丽。或许可以把它翻新一下？"}
D.ItemDescriptions[131812]={["45b92f6b74937432:45"]="一开始感觉很难吃，但你慢慢也习惯了。"}
D.ItemDescriptions[131813]={["55acb6c47d8fddd1:17"]="马凯斯的徽记"}
D.ItemDescriptions[131926]={["08df10fb73053154:15"]="十分柔韧。"}
D.ItemDescriptions[131927]={["f886ba8592790362:20"]="似乎会发光。"}
D.ItemDescriptions[131928]={["be190b9ca396a27f:35"]="英灵殿中某位英雄的饰品。"}
D.ItemDescriptions[131930]={["47eabbf5c5a79184:30"]="让你神不知鬼不觉地猎杀燃烧军团。"}
D.ItemDescriptions[131932]={["82273599bf782f68:16"]="可燃性极强。"}
D.ItemDescriptions[131933]={["0377d2b2d339e8cf:66"]=S[323]}
D.ItemDescriptions[132098]={["f22faf447fdf41d5:64"]="斧尾蜥蜴的脊椎可以用来打造出色的武器。"}
D.ItemDescriptions[132102]={["22d058f30bac43fe:50"]="这些鱼排十分巨大，足够一个维库人吃上一整天了。"}
D.ItemDescriptions[132118]={["0d15c6e513a173ac:67"]="当你将它放到耳边时，可以听到来自风暴峡湾的风声。"}
D.ItemDescriptions[132119]={["17683e35e1094b38:61"]="强大的魔法符文石，在最艰难的时期授予部落的英雄们。"}
D.ItemDescriptions[132120]={["d9d9cf1c6c675e4d:64"]="强大的魔法符文石，在最艰难的时期授予联盟的英雄们。"}
D.ItemDescriptions[132123]={["47c62361de895eca:39"]=S[13034]}
D.ItemDescriptions[132124]={["abbfb013d7391a5c:37"]=S[13035]}
D.ItemDescriptions[132132]={["67cb5646bcc38635:54"]="一块刻有发光符文的冰冷石头。它和结界的样子很像。"}
D.ItemDescriptions[132172]={["268f43aca0c6a625:64"]="一根看起来很不结实的撬棍，在断掉之前，或许可以撬开一些东西。"}
D.ItemDescriptions[132176]={["94bfd0419f487ae4:45"]="警告：酒可能会沾到胡须上。"}
D.ItemDescriptions[132177]={["a42627abe820debc:44"]="掺了水的法力酒，足够喝上好几天了。"}
D.ItemDescriptions[132178]={["dbc495589b6b5b33:26"]="有点旧了，但很光滑，非常光滑。"}
D.ItemDescriptions[132179]={["38149bbc03b4b4e1:31"]=S[20123]}
D.ItemDescriptions[132188]={["599f3ebada6e2485:41"]="这只动物躲过了更可怕的命运。"}
D.ItemDescriptions[132194]={["0b5d392ef6cd0039:53"]="没有人知道这只手是不是属于某个已经被消化掉的人。"}
D.ItemDescriptions[132203]={["61dd9bb8e996a3a1:20"]="这块鱼鳍还是一件战利品。"}
D.ItemDescriptions[132224]={["72e06ae1c1e2a528:45"]="是谁遗失的吗？还是跟手一起被咬下来的？"}
D.ItemDescriptions[132244]={["e261cbda91398ff5:48"]="从萨吉塔纳迦嘴里拔出来的完整獠牙。"}
D.ItemDescriptions[132246]={["2d67a4663692df2f:22"]="脉动着大地的魔力。"}
D.ItemDescriptions[132247]={["9a5a1c13091f16b0:25"]="这些火花看起来就像活的一样。"}
D.ItemDescriptions[132248]={["d5e45b8c3ba94401:29"]="这种液体按照自身的规律流动着。"}
D.ItemDescriptions[132253]={["ce2522242d0805d9:35"]="一个沉重并散发着芬芳气味的皮囊。"}
D.ItemDescriptions[132255]={["21fa8456373fad11:28"]="格外干燥，而且完好无损。"}
D.ItemDescriptions[132259]={["005ee5ad3da9468c:41"]="里面装满了给黛比·摩尔的真宝石。"}
D.ItemDescriptions[132262]={["5c625403413db9d6:35"]="教你学会切割致命深海琥珀。"}
D.ItemDescriptions[132265]={["3d5c22414067c1d0:72"]="它和蒂凡妮·卡蒂亚所描述的致命深海琥珀非常相似。"}
D.ItemDescriptions[132266]={["479d1199ebd4333e:70"]="它和蒂凡妮·卡蒂亚所描述的迅捷阿苏奈特黄晶非常相似。"}
D.ItemDescriptions[132267]={["d82b4b00dea10c3f:77"]="它和蒂凡妮·卡蒂亚所描述的精湛女王猫眼石非常相似。"}
D.ItemDescriptions[132268]={["3effaa1bfdf9b568:33"]="教你学会切割迅捷阿苏奈特黄晶。"}
D.ItemDescriptions[132269]={["6bacdec2951becd9:40"]="教你学会切割精湛女王猫眼石。"}
D.ItemDescriptions[132274]={["21283387bf0d0916:65"]="一个身经百战、武艺高强的战士，凯恩说的到底是谁呢？"}
D.ItemDescriptions[132331]={["49487d0daad7a650:35"]=S[13060]}
D.ItemDescriptions[132332]={["7f3226923b4e3f49:36"]=S[13043]}
D.ItemDescriptions[132333]={["042cf6a048f8e16d:35"]=S[13073]}
D.ItemDescriptions[132357]={["a7be4ea8d1433f7b:154"]="被恶魔之王萨格拉斯腐蚀后，麦迪文联系上了兽人术士古尔丹。他们合力打开了黑暗之门，让燃烧军团开始了对艾泽拉斯的入侵。"}
D.ItemDescriptions[132365]={["5ec4e420aa3676d5:74"]="由于他所犯下的罪孽，布伦达尔被罚永远看守冥狱深渊的大门。"}
D.ItemDescriptions[132366]={["3d2505ce6277bc7f:170"]="在圣光之愿礼拜堂一战后，两位亲密战友分道扬镳了。萨萨里安选择侍奉他的国王，而奎尔萨拉斯的前守护者库尔迪拉则选择与他的人民，血精灵站在一起。"}
D.ItemDescriptions[132367]={["874ff194395c4c2b:90"]="在死后，血魔作为第一位死亡骑士重新归来并宣誓效忠奥格瑞姆·毁灭之锤。"}
D.ItemDescriptions[132368]={["2765cd31a92d9e48:32"]=S[336]}
D.ItemDescriptions[132369]={["c792fe33cf2dc78e:49"]="在银色锦标赛期间的一个重要日子里被落在了家里。"}
D.ItemDescriptions[132370]={["6305b6e696d1dbf1:50"]="一枚粗糙的环，适合鱼人穿在鼻孔、嘴唇和鳍上。"}
D.ItemDescriptions[132374]={["afc15531878205f4:85"]="当末日领主跨过黑暗之门进入外域时，他给自己的敌人留下了一件礼物……"}
D.ItemDescriptions[132375]={["33f1b137fb0ef8f6:52"]="在伊米海姆的村庄废墟下发现的，仍然完好无损。"}
D.ItemDescriptions[132376]={["e2cfb71502f941f0:101"]="……因为你们要面对的不仅是我一个人，而是整个黑锋骑士团。我们是不死的，我们是不可阻挡的，我们渴望生命！"}
D.ItemDescriptions[132377]={["8ef1eca0e40475f5:57"]="一个老旧的罗盘，与逆风小径的黑暗骑士有着密切的联系。"}
D.ItemDescriptions[132378]={["38b72a5e779e0675:51"]=S[17011]}
D.ItemDescriptions[132379]={["ed58a78fb79b7f9c:119"]="燃烧军团扭曲奴役了我们那么多人民。现在该轮到我们以牙还牙了。"}
D.ItemDescriptions[132381]={["eb46822c670c8f17:32"]="唯一的风险就是可能让你发疯。"}
D.ItemDescriptions[132393]={["a38185e827a890e3:105"]="外来者常常会感到好奇，某些维库术士是怎么召唤和指挥一大群魔犬的。"}
D.ItemDescriptions[132394]={["3aa0b31eefc8cec5:101"]="戴上这顶兜帽的人都能获得邪恶的力量和意志，但将永远失去仁慈与同情之心。小心点……"}
D.ItemDescriptions[132406]={["c67411a83878a3b5:104"]="和大众的印象不同，凯尔萨斯最喜欢对敌人说的最后一句话，其实通常都是“炎爆术！”"}
D.ItemDescriptions[132407]={["3c28005167de28a6:100"]="瓦罗森疯狂地爱着他的女王。不幸的是，他从来都没有机会对她使用这些束具。"}
D.ItemDescriptions[132409]={["85ad409419e7495b:141"]="所有人都在猜测为什么安努德会站在卡尔卓葛斯面前。不过，传说安努德的最后一个暗言术：痛才是帮助考尔击败这头恐怖巨龙的关键。"}
D.ItemDescriptions[132410]={["403b1f9b0df57e24:122"]="德莱尼的主城能够超越维度，甚至扭曲时间。如果把它的一小部分力量交给凡人会怎样？"}
D.ItemDescriptions[132411]={["6fa00044244ce5e1:103"]="灌注了纳迦海女巫的力量，让你手指冰凉但却异常灵活且精力充沛。"}
D.ItemDescriptions[132413]={["cf910935a802b640:128"]="像肯瑞托的前领袖罗宁这样强大的法师，常常会使用魔法护腕来稳定从他们指尖溢出的魔法。"}
D.ItemDescriptions[132436]={["484cf987f49db872:137"]="在黑海岸斩杀风鳞纳迦的战斗中，伊瓦贡特像往常一样与卡库善并肩作战。因为有他的守护，他们俩毫发无伤。"}
D.ItemDescriptions[132437]={["9ef1d484af6a08dd:22"]="你看起来有点紧张……"}
D.ItemDescriptions[132438]={["99add358a1904995:112"]="通常会被授予那些必须证明自己有资格晋升至教派最高层的瓦尔基拉。"}
D.ItemDescriptions[132440]={["7602836e233480cb:40"]="英灵殿之主奥丁的大盾。"}
D.ItemDescriptions[132441]={["fc69120e976c04b1:199"]="传说泰坦后裔的身躯由于包含造物者的力量，所以会在其凡人宿主死亡后留下一些碎片。据说这根腰带就是用这种碎片辛苦缝制起来的。"}
D.ItemDescriptions[132442]={["0352e477f1f1a6a2:60"]="它蕴含的魔力似乎就像燃烧军团一样无穷无尽。"}
D.ItemDescriptions[132443]={["bd250936d7e6eacf:71"]="时间与空间是统一的。对于一位宇宙的观察者而言，距离几乎毫无意义。"}
D.ItemDescriptions[132444]={["34fe0d003836fb99:98"]="这个护符的佩戴者哼着一首阴森的曲子，在音符流转间，还有来自远方的痛苦哀嚎不时响起。"}
D.ItemDescriptions[132445]={["20466214d7cf52b5:49"]="据说它曾属于第一位瓦格里。"}
D.ItemDescriptions[132446]={["876112fe6b1fba51:34"]="一大袋各类珠宝。"}
D.ItemDescriptions[132447]={["f3d7e8b7f902f0d8:57"]="这条裤子的穿戴者常常具有远超他人的使命感。"}
D.ItemDescriptions[132448]={["60978ef5ef9b763e:153"]="据说是拉苏维奥斯送给他最有天赋的学生的礼物——但我们不清楚它是怎么离开纳克萨玛斯的。也许巫妖王已经向破碎群岛派出了密探？"}
D.ItemDescriptions[132449]={["568074c28b28535d:175"]="皮瑞克丝是一位传奇牧师，曾领导冒险者穿越了熔火之心以及黑翼之巢。她不幸死于奈法利安之手，但她的灵魂至今仍庇佑着艾泽拉斯的英雄们。"}
D.ItemDescriptions[132450]={["531daff76152590c:160"]="从银月城到黑石山，穆兹始终坚定不移地为她的同伴们进行治疗，将他们从死亡边缘拯救回来。"}
D.ItemDescriptions[132451]={["116b2719c958b718:104"]="虽然诺森德的半巨人天生就不擅长魔法，但风暴峡湾的神秘维库人却是符文魔法的大师。"}
D.ItemDescriptions[132452]={["3b1454aad61ebfa3:135"]="无形是一种神奇的概念。这个词总是让人想到某种魔法能力，但在现实世界中，它仅指能够身在此处或彼处，现在或未来的能力。"}
D.ItemDescriptions[132453]={["92518a035ae48d8e:125"]="笨重的恐魔血骨傀儡的残骸仍然含有强大的死灵能量，能够对那些有着强大意志，能够控制它们的人做出回应。"}
D.ItemDescriptions[132454]={["8b9b92130d5514c6:94"]="在冬拥湖深处的宝库内，火焰看守者科拉隆对于闯入者的出现深感恼火。"}
D.ItemDescriptions[132455]={["69cd85172ecdb1ce:128"]="魔法应当受到调节，管理和控制。但同时也应当受到理解和珍视，而不是束之高阁。你必须彻底理解这种矛盾。"}
D.ItemDescriptions[132456]={["5b38edeada926195:77"]="从不同角度看，似乎能依稀看到三张不同的面孔。"}
D.ItemDescriptions[132457]={["4432d25cf222013d:82"]="蕾瑟塔蒂丝制造了一个装置来吸取厄运之槌内强大的腐蚀能量为自己所用。"}
D.ItemDescriptions[132458]={["36e3e6d50fb5b816:96"]="在冬拥湖深处的宝库内，寒冰看守者图拉旺想要残忍地将入侵者一网打尽。"}
D.ItemDescriptions[132459]={["e7aeaa6edf8d8c9d:50"]="冰冷的钢铁沉甸甸地压在这顶冠冕的佩戴者的眉毛上。"}
D.ItemDescriptions[132460]={["5b8fd0dcfe2e7497:46"]=S[18104]}
