D.ItemDescriptions[133927]={["245e8372b0a2235b:54"]="从蓝风海湾的船只残骸上回收的巨大木板。"}
D.ItemDescriptions[133928]={["4a11b4a9d2c1d82e:50"]="霍巴特的初代绷带枪。可能需要校准。"}
