D.ItemDescriptions[133935]={["92548c9b248ab20a:63"]="蒂迪的便携式高能萨隆邪铁烟火。魅蓝版。"}
D.ItemDescriptions[133936]={["c428b32bfc1978c8:65"]="蒂迪的便携式高能萨隆邪铁烟火。炫紫版。"}
D.ItemDescriptions[133937]={["aefa9e620daf5e3b:35"]="谁会响应无冕者的召唤呢？"}
D.ItemDescriptions[133939]={["9c5f61ea4a1d53bf:28"]="散发着冰冷而稳定的光芒。"}
D.ItemDescriptions[133941]={["0f8907ea10353671:17"]="在水上都能运转！"}
D.ItemDescriptions[133943]={["b5d09cbbc7bfe388:29"]="这把鱼叉看起来完好无损。"}
D.ItemDescriptions[133946]={["54f181ed80a932ea:40"]="用来加固最复杂的牢房。"}
D.ItemDescriptions[133947]={["edba16aac29a0581:66"]="对于那些知道如何驾驭的人来说，这块未经雕琢的宝石里蕴含着巨大的能量。"}
D.ItemDescriptions[133948]={["339c0d7d114e1e82:133"]="先是一道巨大的闪电划过，然后一阵狂风吹过。闪电和狂风都消失后，伊尔马特感觉自己的武器——阿布尔克和奥拉艾德震荡着元素的力量。"}
D.ItemDescriptions[133958]={["1c8180a7b82d3ec8:147"]="在触碰到这把短剑时，我的脑海中响起了一个名字：萨拉塔斯。我知道我不能摧毁这把匕首。现在还不行。一个人怎么可能摧毁她根本不理解的力量呢？"}
D.ItemDescriptions[133959]={["3490fb6dea246dca:186"]="战斗结束后，达斯雷玛仍然屹立不倒，身上沾满了恶魔的鲜血。当夜幕降临时，我们知道还有更多战斗在等着我们。但只要有这个精灵和这把剑在，胜利的希望就还在我们手中。"}
D.ItemDescriptions[133960]={["cb4b2d08b67406db:55"]="这些眼球所蕴含的液体之多出人意料。"}
D.ItemDescriptions[133961]={["38f3652f8302b86c:55"]="纳迦使用这种气囊帮助他们在游动时增加浮力。"}
D.ItemDescriptions[133962]={["c1d351e2971b07db:29"]="萨吉塔海妖的黑色血液。"}
D.ItemDescriptions[133970]={["d608ad4d9a50da7c:115"]="扎奈苏法师部族为了寻找能够击败巫妖王的完美魔法，而离开了自己的家乡布伦希尔达。他们再也没有回去。"}
D.ItemDescriptions[133971]={["65347a3e6e249825:78"]="由最精美的恶魔布制成，伊尔迪曾从这顶冠冕中抽取力量击败了卓贡纳克斯。"}
D.ItemDescriptions[133972]={["0227be6a18eeb3b9:49"]="如果不煮熟的话，这块生蜥蜴肉不但非常难嚼，而且还有剧毒。"}
D.ItemDescriptions[133973]={["7ec6d29c99a4fbed:70"]="“别再玩球了菲奥拉，让我们解决这些挑战者。”——黑暗邪使艾蒂丝"}
D.ItemDescriptions[133974]={["60403d1efe18c1f1:144"]="兰娜瑟尔还曾为诺森德征途中可能会牺牲的血精灵而流下眼泪。那时她完全没有想到自己以后会亲手杀害多少生命。"}
D.ItemDescriptions[133975]={["24b7a8ee7563121f:79"]="大部分书页都污渍斑斑了，但有一小部分还能读。"}
D.ItemDescriptions[133976]={["f605bd65f4c22e7e:97"]="这个恶魔共生体习惯于从激烈的战斗中获取给养，有时会模仿其宿主的行动。"}
D.ItemDescriptions[133977]={["036f4c1ed1c36291:119"]="第三次大战时期，奎尔萨拉斯的大魔导师贝洛瓦尔·萨罗纳在城市陷落时所做的最后一件事，就是将女伯爵莉亚德琳传送到安全的地方。"}
D.ItemDescriptions[133978]={["de2f9d9c2e149dd3:58"]="似乎跟藤蔓纠缠在了一起，表面都被尖刺刮花了。"}
D.ItemDescriptions[133983]={["dc0725d9c9746d5a:14"]="热乎乎的，而且泡沫丰富。"}
D.ItemDescriptions[133985]={["89d748fd555fa104:26"]="警告：可能会致盲。"}
D.ItemDescriptions[133988]={["2638f73e5636c079:59"]="黏糊糊的泔水，但按照卓格巴尔的标准，已经算得上是爽口的美酒了。"}
D.ItemDescriptions[133989]={["0ee6f13c6d10f311:22"]="与其说是饮料，不如说是毒药。"}
D.ItemDescriptions[133993]={["8364c4e5a0ca3eac:23"]="卓格巴尔的风格。"}
D.ItemDescriptions[133997]={["ff9e37ea352b5dd1:54"]="带着这么大颗的黑钻石，你肯定是众人目光的焦点。"}
D.ItemDescriptions[134001]={["0786c136a42ec505:79"]=S[300]}
D.ItemDescriptions[134002]={["0786c136a42ec505:79"]=S[300]}
D.ItemDescriptions[134003]={["0786c136a42ec505:79"]=S[300]}
D.ItemDescriptions[134004]={["53091f98da97d029:107"]="这枚高雅华贵的戒指使用最为珍稀的材料精心雕琢而成，只有世界上最杰出的精英人物才能购买并代代相传。"}
D.ItemDescriptions[134007]={["0628245052730dc1:79"]="与传说中的黑冰一样，这枚指环也已经传承了数代之久。"}
D.ItemDescriptions[134014]={["acafb8895bfdc1e8:39"]="这些柔美的花瓣中蕴含着强烈的毒性。"}
D.ItemDescriptions[134015]={["775e4507c5dcaf04:64"]="这种鱼的油在卓格巴尔的炼金合剂中广泛使用。"}
D.ItemDescriptions[134016]={["31b1983936501aa2:66"]="这种来历可疑的物质对于卓格巴尔酿酒师来说非常宝贵。"}
D.ItemDescriptions[134023]={["e820179a77c18c2f:68"]="螳螂妖早就学会了如何让潘达利亚的风屈从于女皇的意志。"}
D.ItemDescriptions[134024]={["5df7b14047448e8b:82"]="用于将低级水手变成无脑的猢狲蛮兵，可划动幽灵船瓦祖维斯号。"}
