D.ItemDescriptions[134041]={["4afd6bc70b004fbc:41"]="指环内测刻着“LS”两个小字。"}
D.ItemDescriptions[134047]={["9d6d0e19bc8fb050:35"]=S[13094]}
D.ItemDescriptions[134048]={["947f16963bbd0bd7:44"]="这个瓶子里的每一滴法力都被吸干了。"}
D.ItemDescriptions[134049]={["07947f0e0da9f77b:57"]="上古之战时期地狱猎犬最喜欢的零食……"}
D.ItemDescriptions[134050]={["c33f374f12162cf2:43"]="地狱猎犬的消化能力也是有极限的。"}
D.ItemDescriptions[134051]={["7536145f812ae2ec:55"]="这张卡牌基本完好……就是气味有些古怪，仅此而已。"}
D.ItemDescriptions[134052]={["7d0e504f40288b28:31"]="上面刻着……“毛毛”。"}
D.ItemDescriptions[134053]={["ebd3f93151971932:64"]="上面墨迹似乎被弄花了。经过仔细检查，你发现那不是墨水。"}
