D.ItemDescriptions[134055]={["633d302f0fc38d14:34"]="安古斯·雷酒一直在找这个东西……"}
D.ItemDescriptions[134056]={["7e12c49bc5f74c22:17"]="这是从哪儿分泌出来的？"}
D.ItemDescriptions[134060]={["2309c9f9eb09f22e:24"]="每一位地精最好的朋友。"}
D.ItemDescriptions[134063]={["74f5455b6f0b5114:43"]="阿卡扎曼扎拉克要带一个新人回来，会是谁呢？"}
D.ItemDescriptions[134065]={["f8b70dba41177da5:81"]="沾满了鲜血，让人想起噩梦般的恐翼。"}
D.ItemDescriptions[134080]={["0b58cf0bfea482e0:29"]="可打开邪魂牢笼。"}
D.ItemDescriptions[134082]={["f0d90cf7c27e33b2:38"]="来自上古之战的恶魔碎片。"}
D.ItemDescriptions[134083]={["0b38c5c602f1e877:38"]=S[352]}
D.ItemDescriptions[134084]={["1ec07abe48461eaf:39"]="布莱恩发现的一个地狱火装置零件。"}
D.ItemDescriptions[134085]={["4913efb5fa767b94:41"]="开启苏拉玛某个密室的钥匙碎片。"}
D.ItemDescriptions[134086]={["ef5633e133c5782c:47"]="一箱刷子、鹤嘴锄以及勘测设备零件。"}
D.ItemDescriptions[134089]={["6409e8f2049cf421:83"]="关于玛凯雷的故事。它在恶魔入侵之前是阿古斯最辉煌的城市之一。"}
D.ItemDescriptions[134090]={["602a13c8ffbd0f67:46"]="《玛凯雷的紫色群山》缺失的章节。"}
D.ItemDescriptions[134091]={["0b38c5c602f1e877:38"]=S[352]}
D.ItemDescriptions[134092]={["bb6dfde5c0930e78:41"]="这个箱子封得十分严实，而且分量很轻。"}
D.ItemDescriptions[134093]={["dee1642d6f545c88:46"]="它看上去是一把长矛。或许莱莎会知道更多内情。"}
D.ItemDescriptions[134094]={["ec9743933e8baa34:54"]="一条制作粗糙，但蕴含能量的珠宝项链。"}
D.ItemDescriptions[134095]={["c56e0663055a2872:60"]="胡恩·高岭的坐骑艾特洛的遗骨残片。"}
D.ItemDescriptions[134108]={["dd2c3d75b5859dc2:66"]="它看起来是某种装置，但你看不出它究竟有什么用。"}
D.ItemDescriptions[134114]={["5705454d2772d92a:46"]="一块来自大魔导师之冠的宝石。"}
D.ItemDescriptions[134115]={["cb87d820ffeec8d3:64"]="考虑到发生过爆炸，碎片看起来还算完好。"}
D.ItemDescriptions[134116]={["7d8e404012f065d1:54"]="一条关于斯卡拉克斯宝珠下落的线索。"}
D.ItemDescriptions[134117]={["e380876ef4b989df:52"]="一件用于铸造钥匙的大型模具的组件。"}
D.ItemDescriptions[134119]={["57e05bb476248c7f:21"]="这块水晶发出轻柔的嗡鸣声。"}
D.ItemDescriptions[134120]={["ce7482ea8fad55e7:47"]="光是看到这个项圈，你的意识就开始恍惚起来。"}
D.ItemDescriptions[134125]={["61d473cf73b256cc:49"]="让你可以追踪并驯服机械类宠物。"}
D.ItemDescriptions[134128]={["02829cf6430bcfcf:30"]="陷阱上符文闪烁着微弱的光芒。"}
D.ItemDescriptions[134129]={["c31f5d051b79373c:59"]="生活在高海拔地区的铁角牛有着更加厚实、更能抗寒的毛皮。"}
D.ItemDescriptions[134130]={["eeb661948e493bd1:64"]="至高岭刃豹的毛发比其他地方的同类更加浓密。"}
D.ItemDescriptions[134131]={["38ac94e578c02e66:55"]="巨大、结实，在制作链甲时格外有用。"}
D.ItemDescriptions[134132]={["f0e94eade63de5fc:60"]="至高岭蠕虫背上的鳞片向来以坚韧著称。"}
D.ItemDescriptions[134322]={["0503d0612cc146c6:32"]="已经没有法力了，但是仍然效果极佳。"}
D.ItemDescriptions[134323]={["5098a95da88a49be:27"]="它看起来比实际上更加魔幻。"}
D.ItemDescriptions[134399]={["22cc4a7e6e72e2a7:9"]="砰！"}
D.ItemDescriptions[134400]={["538b232523769c66:22"]="一条健康、强壮的鱼。"}
D.ItemDescriptions[134539]={["3dc9c605aff60f9c:37"]="内侧刻着一个名字，“布兰蒂”。"}
D.ItemDescriptions[134547]={["4491be9c646d908f:56"]="相当适应至高岭酷寒的北方水域。"}
D.ItemDescriptions[134548]={["d8afb18241cc33af:7"]="临时描述"}
D.ItemDescriptions[134549]={["14ffe35e7abc7d61:31"]="竟然会散发出鱼腥味。"}
D.ItemDescriptions[134550]={["ecc9eeae8f0da633:41"]="艾泽拉斯第一片森林的遗种。"}
D.ItemDescriptions[134552]={["16afa59e761a5c39:93"]="没有哪把剑能在沾上这么多无辜者的鲜血之后，还能让它的持有者毫发无伤。它们绝不是什么宝物。"}
D.ItemDescriptions[134553]={["d468a6519ab1349a:185"]="事实上，是她的力量让这些武器真正变得光彩照人。她的力量，以及她对奥丁之魂的无尽仇恨，这两种激烈的能量永远渗入了这些利刃中……"}
D.ItemDescriptions[134564]={["92a28461f0bf336c:55"]="活蹦乱跳的女王鱼，简直看不出被诅咒的迹象。"}
D.ItemDescriptions[134565]={["5c402c5b4f34d0f8:59"]="这条大鱼已经在阿苏纳的池塘里潜伏了几十年了。"}
D.ItemDescriptions[134566]={["a2245e6d13bc2282:66"]="在阿苏纳的水域中游动的黑梭鱼也被染上了魔法色彩。"}
D.ItemDescriptions[134567]={["c549de0f205ddb5c:13"]="它看起来很快活。"}
D.ItemDescriptions[134568]={["9989f1000e628763:23"]="特别老，特别大，肉特别多。"}
D.ItemDescriptions[134569]={["882e4c0a87947f3d:68"]="不止一个渔夫在利齿梭鱼口中丢了手指。"}
D.ItemDescriptions[134570]={["3a3c7abc8d0fc44f:31"]="浑身充满了活力。"}
D.ItemDescriptions[134571]={["94f7bbc61eced37f:9"]="好大！"}
D.ItemDescriptions[134572]={["767972dd579f8ae8:48"]="统治着风暴峡湾与提瑞斯法之间的大片海域。"}
D.ItemDescriptions[134573]={["08e698fd4e1d06e6:22"]="特别闪亮。"}
D.ItemDescriptions[134574]={["9e6f170bf5e4dc78:18"]="一条暴躁的池塘老锦鲤。"}
D.ItemDescriptions[134575]={["3c28a1b1ef1a2aee:27"]="就连鱼也会对魔力上瘾。"}
D.ItemDescriptions[134806]={["c44e622d4f41cef6:49"]="大部分角鹰兽鳞片都带有明显的啄痕。"}
D.ItemDescriptions[134807]={["5495245a2ab29c7f:30"]="厚实，光滑，味道也不错！"}
D.ItemDescriptions[134808]={["58ac5289918c10d8:34"]="这头徘徊者真的很爱惜它的毛皮。"}
D.ItemDescriptions[134809]={["3a9e449b1af20120:16"]="漂亮且富有弹性。"}
