D.ItemDescriptions[134813]={["bbc2e6ce975eba7b:36"]="每一头牡鹿都渴望拥有的毛皮。"}
D.ItemDescriptions[134814]={["f4d4efb8271e9de9:37"]="你从未见过这样的鳞片。"}
D.ItemDescriptions[134815]={["b6040a168ce09b7f:22"]="可以做成漂亮的绒毛玩具。"}
