D.ItemDescriptions[134819]={["94ad5a16b7dd9425:50"]="说到恶魔皮的话，最臭的就是最好的。"}
D.ItemDescriptions[134820]={["c7ba186587991800:15"]="越大越好。"}
D.ItemDescriptions[134821]={["0a4d3bcecdc50901:46"]="广受追求时尚的夜之子贵族追捧。"}
D.ItemDescriptions[134822]={["8a5db37fdf9c803e:40"]="极其坚硬，很难分清它到底是鳞片还是矿石。"}
D.ItemDescriptions[134831]={["563ea9758e07bc48:15"]="最近刚洗过。"}
D.ItemDescriptions[134832]={["3b2dafbaba4ad179:38"]="红热的金属液，可以倒入模具中了。"}
D.ItemDescriptions[134833]={["963cf1af24c81172:23"]="这把钥匙散发着能量。"}
D.ItemDescriptions[134837]={["4f6a7dcf1f557b70:69"]="比暮光之锤所用的更粗糙，但一样危险。"}
