D.ItemDescriptions[135488]={["ecc83d065a0de9b3:104"]="经过精心测量后填入了最低剂量的火药，可以将任何神器从岩层中分离出来。"}
D.ItemDescriptions[135489]={["6cddafec5fcb918f:32"]="边缘也有一点烧焦了。"}
