D.ItemDescriptions[135582]={["3ea218f2220df8bd:65"]="这件神器的力量已经被其内部根深蒂固的腐蚀削弱了。"}
D.ItemDescriptions[135587]={["fe5150d234729db5:57"]="流转的云气和咆哮的狂风在这个轻若无物的球体内搅动着。"}
