D.ItemDescriptions[135589]={["0cbe162136d66f3c:53"]="形成天空之墙位面的永恒精华。"}
D.ItemDescriptions[135590]={["7a3af3674a5cc4e2:60"]="这顶不断震颤的冠冕是奥拉基尔送给西方第一位灯神的礼物。"}
D.ItemDescriptions[136269]={["467d8353e9197e12:27"]="装饰着精美的金银丝线。"}
