D.ItemDescriptions[136342]={["fc9447013ee1ec60:58"]=S[5472]}
D.ItemDescriptions[136343]={["881d1eee57fccf39:39"]="这些破损碎裂的蹄子暗藏着一个曲折的故事。"}
D.ItemDescriptions[136350]={["dd16284906a09f6c:75"]="这把古老的维库锤子可能是普通锻造锤的替代品。"}
D.ItemDescriptions[136352]={["8b468b646cc82a97:94"]="一件有着美丽刺绣的布袍。如果被扔进恶魔的熔炉就太可惜了……"}
D.ItemDescriptions[136353]={["fd2f1b541705c38d:52"]="没用了……你或许能把它卖给收废品的。"}
D.ItemDescriptions[136354]={["ad5eda9e204374d1:65"]="无论它原本是什么，都已经看不出来了，也失去了魔力。"}
D.ItemDescriptions[136355]={["94a7077556a11af2:93"]="无论上面原本写了什么，都已经无法辨认了。你或许能找到什么人愿意把它买回去当柴火烧。"}
D.ItemDescriptions[136356]={["5273a81263631a8f:82"]=S[10438]}
D.ItemDescriptions[136357]={["f30c3a4c5e2c7cbb:91"]="使用产于瓦尔莎拉的原料调制，但愿它的味道能比气味好一些。"}
D.ItemDescriptions[136358]={["fb385fadda16b8b0:66"]="这些祭品由熊牙制成，上面还点缀了孔雀石碎片。"}
D.ItemDescriptions[136359]={["237cc470f3f16597:33"]="让我们看看这个萨满带了些什么……"}
D.ItemDescriptions[136361]={["b3f2825a47068f2d:32"]="多年前的某场大战中留下来的护甲部件。"}
D.ItemDescriptions[136362]={["680fc5a489ed2ab1:61"]="上古之战期间，风暴峡湾曾爆发过多场野蛮的战役。"}
D.ItemDescriptions[136363]={["9eee8f65b4c775da:41"]="匆忙写成，几乎无法辨识。"}
D.ItemDescriptions[136369]={["94502a20f61daae1:42"]="即使是已经死了，这枚鳞片依然电光缭绕。"}
D.ItemDescriptions[136370]={["d2b1f111ae5f89b8:43"]="这个头骨与其原先的形状已经大相径庭了。"}
D.ItemDescriptions[136371]={["439396c1766b1374:40"]="这是你所见过的、最完美的幼龙头骨。"}
D.ItemDescriptions[136381]={["ee4aa6faebe1e71b:81"]="这把钥匙的边缘已经磨损了，但头上仍然装饰着珍贵的金属和宝石。"}
D.ItemDescriptions[136382]={["40a28615ffe5c9d8:58"]="各类文件，介绍了拉文凯斯家族财产状况。"}
D.ItemDescriptions[136383]={["9ae47556af7118ef:29"]="带有一个渡鸦徽记。"}
