D.ItemDescriptions[136966]={["564bd7530ac7d620:74"]=S[361]}
D.ItemDescriptions[136967]={["564bd7530ac7d620:74"]=S[361]}
D.ItemDescriptions[136968]={["abb4c51358a6f69e:42"]="有电光在蛋壳表面流转。"}
D.ItemDescriptions[136969]={["ddb4a5b685cbf9a7:18"]="教你学会妖术：蜘蛛。"}
D.ItemDescriptions[136971]={["ef499e014a244090:17"]="教你学会妖术：蛇。"}
D.ItemDescriptions[136972]={["c673eb9c282cee9b:21"]="教你学会妖术：蟑螂。"}
D.ItemDescriptions[136981]={["d9b5420739ea603c:34"]="一本用邪能书写的恶魔法术书。"}
D.ItemDescriptions[136983]={["2d11e83c238e1883:35"]="充满了逝者的悲伤。"}
D.ItemDescriptions[136984]={["c739d90ccedacc6b:76"]="一位强大的天神为你执行任务，可大幅提高成功率。"}
D.ItemDescriptions[136985]={["f47760e8a69a55c3:46"]="漆黑的油膏，仿佛液态的虚空。"}
D.ItemDescriptions[136986]={["89c3a59154bd7140:15"]=S[12593]}
D.ItemDescriptions[136987]={["ec01e9784ee903b1:36"]="四年陈的美酒。"}
D.ItemDescriptions[137010]={["a939569c61887b95:27"]="另外半瓶被塔莉萨喝了。"}
D.ItemDescriptions[137011]={["d2de9929b2af1ccc:28"]="莉莉丝给塔莉萨的礼物。"}
D.ItemDescriptions[137014]={["066e9961ca3df856:78"]="恶魔猎手对于战斗的渴望，就像他们最痛恨的死敌——燃烧军团一样无穷无尽。"}
D.ItemDescriptions[137015]={["2abbf80649b08bd7:140"]="我们不再只能回忆那片故土了，现在我们可以创造出属于自己的土地。迄今为止所有存在过的……空间都服从于我们的梦境。现在……倾听我所听到的一切吧。"}
D.ItemDescriptions[137016]={["47bd9ab1c677dada:56"]="这可能是在萨萨拉比姆昏迷的6小时里遗失的……"}
D.ItemDescriptions[137017]={["acb0dbd7757b4144:99"]="一位从天而降打击敌人的伟大指挥官的遗物，散发着太阳般的光辉。"}
D.ItemDescriptions[137018]={["88ac1f0519f7d468:47"]="扭曲时间，保护世界免遭毁灭。"}
D.ItemDescriptions[137019]={["0886c38bd7552768:74"]="知己知彼，百战不殆。"}
D.ItemDescriptions[137020]={["678323097aaff05e:32"]="真可怜……你就这点儿能耐？"}
D.ItemDescriptions[137021]={["569cac1a33cc329f:84"]="年轻的王子，我等你很久了。我就是玛尔加尼斯。如你所见，你的子民现在已经属于我了……"}
D.ItemDescriptions[137022]={["ccb6ed902a526d4f:110"]="拉瑟莱克被封印石匕困在污染者洛拉姆斯体内以后，只留下了这双靴子。"}
D.ItemDescriptions[137023]={["2acb3220bb23f2a9:76"]="赐予他人生命与活力者，亦将从我处获得生命与活力。"}
D.ItemDescriptions[137024]={["d23d3d1a54b0bdff:61"]="据说，玛尔·虫棘的疯狂强化了这些靴子。"}
D.ItemDescriptions[137025]={["3acaafa8cf24d407:155"]="在海加尔山之战中，诺达希尔的守护者斯凯塞克抵挡住了无穷无尽的天灾及燃烧军团。最终，他在保卫上古世界之树的战斗中光荣地献出了生命。"}
D.ItemDescriptions[137026]={["2e078849afe9c240:34"]="感受自然在你的血管中流淌的滋味。"}
D.ItemDescriptions[137027]={["3c4797c826b5e773:125"]="“亚当兄弟和戴维兄弟都是杰出的数学家及武僧，总是说着算盘和抛物线之类的话。”——酒仙布瑞尼德"}
D.ItemDescriptions[137028]={["e53abb7e07b7c16b:55"]="埃拉玛斯·炽光总是强调它们有多么舒服。"}
D.ItemDescriptions[137029]={["5c0426a8478b9beb:125"]="卡尔德对他的兄弟卡特索说过：“通过训练，你的反应会变得更快，拳头会更有力量，让敌人应接不暇。”"}
D.ItemDescriptions[137030]={["ddc031f052a23bd5:98"]="如果你被凯瓦娜这样的军情七处密探发现，你最好赶快逃跑，跑得远远的。"}
D.ItemDescriptions[137031]={["b5e3d78cb6d4acc7:64"]="萨茜总是把自己伪装成酒仙武僧，以欺骗她的敌人。"}
D.ItemDescriptions[137032]={["35ae8fc0a40552d3:156"]="虽然暗影萨特真正的起源还未确认，但他们是家喻户晓的精神生物，不仅存在于翡翠梦魇，也存在于艾泽拉斯的许多地方。"}
D.ItemDescriptions[137033]={["36340cade4b3e212:81"]="它们让这位女猎手感觉轻若无物——如同暴风雨中的宁静。"}
D.ItemDescriptions[137034]={["86a735b0b26d0659:59"]="某种有着巨大牙齿的动物曾想要从这些靴子上咬一块下来。"}
D.ItemDescriptions[137035]={["73789b3bcbcb7032:132"]="影月氏族的萨满长老耐奥祖为了拯救他的人民，终于获得了他渴望的力量和尊重。可惜，他被骗了……"}
D.ItemDescriptions[137036]={["e4207b8085b043fb:154"]="原本是强大的末日守卫用来毁天灭地的工具，现在却被用于平衡他们先前所造成的破坏。"}
D.ItemDescriptions[137037]={["0af4206dc870b07e:111"]="这个戒指中流淌着暗夜井的腐蚀能量，能让持有者从他们的属下身上吸取能量。"}
D.ItemDescriptions[137038]={["a39cfbdfe376f738:101"]="你绝对不会想在一到诺森德时就遇见那些魁梧的维库人。去北风苔原找亡灵试试吧。"}
D.ItemDescriptions[137039]={["80c8e8eee8ab7413:101"]="翡翠议会的德鲁伊通过操纵这块石头所蕴含的邪能，来提高他们与荒野的协调性。"}
D.ItemDescriptions[137040]={["97bea8d0d19d0f8f:76"]="莱雅娜内心的烈焰赋予了这枚玺戒魔力。你能感她到终于获得了安宁。"}
D.ItemDescriptions[137041]={["cb7a7713a8337688:100"]="利爪德鲁伊能够变形，让自己变得更快或更结实。他们通常都会选择后者。"}
D.ItemDescriptions[137042]={["674069d244e88f63:113"]="作为艾泽拉斯的少数真神之一，艾露恩有许多传说。这说明她真正的身份可能还没有被大众完全认识。"}
D.ItemDescriptions[137043]={["7bf964f12e1e5818:37"]="只要涂上一点点黄油，就容易脱下来了！"}
D.ItemDescriptions[137044]={["25e0585d089d849a:123"]="原本是法师维利萨斯的赠礼。据说这件饰品是在一次武僧与精灵的冲突之后从失落修道院里偷出来的。"}
D.ItemDescriptions[137045]={["c0ec1de254656577:20"]="好吧……是他的其中一只眼睛。"}
D.ItemDescriptions[137046]={["884b7979c4b5a264:190"]="银月城由熠熠生辉的白石建造而成，并以深红色织锦作为装饰。但是，这座城市并非仅以美丽而著称。银月城是魔法研究中心，也是许多强大施法者的故乡。"}
D.ItemDescriptions[137047]={["e4671071cf58f77a:152"]="据说，号称永生者的希斯克利夫永远不会受到重创。有人质疑这个血骑士的顽强已经超越了这个世界的自然法则。"}
D.ItemDescriptions[137048]={["833e18fcb79cf683:152"]="那个被我们称为王子的男人背叛了我们。我以血骑士的佩剑起誓，击败基尔加丹，恢复银月城昔日的辉煌。我们会和您并肩战斗，阿达尔。"}
D.ItemDescriptions[137049]={["bbcfb6dbc43e57c0:96"]="这种徽记只授予展现过高超暗影技巧，并曾为拉文霍德出生入死的人士。"}
D.ItemDescriptions[137050]={["171f75e8b887b1d9:96"]="虽然世界的元素在虚空中被扭曲得面目全非，但它们的力量无与伦比。"}
D.ItemDescriptions[137051]={["6af1356000a53311:109"]="在约纳特·汉的训练下，掠龙氏族的新晋萨满都掌握了治疗单体和群体的水之道。"}
D.ItemDescriptions[137052]={["6954d8d4121df20d:145"]="在瓦哈拉斯的竞技场中，无情的阿亚拉击倒了一个又一个敌人，铸就了他的传奇。当对手被削弱时，他会变得更加致命。对于观众而言，他真的非常可怕。"}
D.ItemDescriptions[137053]={["73605c07bd56d3fe:104"]="锦鱼们传颂着伟大的战士，弗吉达的传说，他在一个浅浅的小水塘里埋伏了几个小时，最后击杀了一头强大的邪魔。"}
D.ItemDescriptions[137054]={["a4496a3366b7c280:83"]="在第三次大战中，由卡利姆多的守护者组成的人墙纷纷倒下，但战争古树沙卡却仍然屹立不倒。"}
D.ItemDescriptions[137055]={["781a8134a7ffc089:59"]="它的力量来自牺牲在厄运之槌的猎人们。"}
D.ItemDescriptions[137056]={["c371da459efd10fc:32"]="没有比丝瓜更好用的了。"}
D.ItemDescriptions[137057]={["731b56528c314a9f:108"]="数千年来，操纵命运的古老知识在一位位大师之间秘密地代代相传。"}
D.ItemDescriptions[137058]={["725b4e850e20affc:168"]="为了合力击败艾泽拉斯最大的敌人，最杰出的智者聚集起来，讨论着情报和战术，而他们的勇士则在前线奋勇厮杀。"}
D.ItemDescriptions[137059]={["b889c5fa5d02d7e5:74"]="被始祖龙迦拉克隆咬掉手之后，尤顿又为提尔造了一只新的。"}
D.ItemDescriptions[137060]={["ca288423f18b4f92:91"]="在冬拥湖深处的宝库内，岩石看守者阿尔卡冯对所有的入侵者恨之入骨。"}
D.ItemDescriptions[137061]={["d24b3ad4faf8eac1:39"]="即使世界……消逝……我们仍将长存。"}
D.ItemDescriptions[137062]={["93e4a98da214b6e2:31"]="伊瑟拉的梦境足以震动整个世界。"}
D.ItemDescriptions[137063]={["515f69e04ea3e465:42"]="坐下，放松身体，观察你周围的世界。"}
D.ItemDescriptions[137064]={["eb7b6f77320facac:152"]="“如果他们想杀我，那最好趁我睡觉时一次成功，把我彻底弄死。”——沃金，写于逃过加尔鲁什的刺杀之后。"}
D.ItemDescriptions[137065]={["af6b37191ef74114:132"]="这是大领主亚历山德罗斯·莫格莱尼戴过的头盔。要不是因为事出意外，本该由他的儿子雷诺·莫格莱尼和达里安·莫格莱尼继承。"}
D.ItemDescriptions[137066]={["05ca4ca57b6940c6:84"]="看起来就像熔火深渊的产物，它的邪焰似乎燃烧得更加坚定。"}
D.ItemDescriptions[137067]={["53c8aad9126cb9e0:68"]="对于它在大分裂时期的主人，“100%自然之怒的化身”是最恰当的描述。"}
D.ItemDescriptions[137068]={["fd3fcc1b9d55c34e:161"]="黑色烈焰致力于提供您所能用金钱买到的最好服务和娱乐。无论您是需要稀有物品、激烈的角斗还是有利可图的博彩，黑色烈焰永远都是您的最佳选择。"}
D.ItemDescriptions[137069]={["b0680c6ebfda5d77:123"]="自幼年起，瓦莉拉经历了父母双亡、幽禁和奴役。她的敌人总是低估她求生的意志。"}
D.ItemDescriptions[137070]={["7deb91da51087c09:79"]="实力源自力量，而真正的力量源自你坚实的双腿。"}
D.ItemDescriptions[137071]={["c5a65c8281b25841:78"]="钢铁议会的莫尔基姆能够用符文造成无数毁灭性的效果。"}
D.ItemDescriptions[137072]={["b64456b2048068f3:148"]="你要负起保护时空纯净的重任。记住，只有一条真正的时间流，但总有人想要肆意篡改它。你必须用生命去守护它。"}
D.ItemDescriptions[137073]={["32d2a2a17daabfee:126"]="你所能想象到的每一个地方都是真实的。它是存在于你头脑中的幻想之城，你了解它的每一个角落。你的思想自成一届，我们每个人都在其中占有一席之地。"}
D.ItemDescriptions[137074]={["bb40679eaa24fdf7:69"]="一万年前，永恒之井发生了大爆炸。它的影响一直绵延至今。"}
D.ItemDescriptions[137075]={["b2957fe5ee64e08a:106"]="在第一次入侵艾泽拉斯期间，燃烧军团的指挥官塔克瑟里特克斯是攻破暗夜精灵早期防线的关键人物。"}
D.ItemDescriptions[137076]={["63ceffc0a49bbd85:48"]="它们似乎散发着与黑暗之门一样的力量。"}
D.ItemDescriptions[137077]={["0e276b743f6af11f:160"]="所有生灵都认为大地亘古不变。他们完全不了解地表之下的暗涌，不理解它的负担，也不明白它的力量。"}
D.ItemDescriptions[137078]={["d5accc1ca4aafd8f:45"]="耐心点，年轻人，你迟早会得到它的。"}
D.ItemDescriptions[137079]={["d7b243748641f7bf:91"]="盖平抽取了潞水河的力量注入这条腰带，使其具有舒缓疗愈的能力。"}
D.ItemDescriptions[137080]={["cc358ab9373b626e:84"]="这条腰带是由暗夜精灵哨兵提汶使用传说中的七雄狮的鬃毛编制而成的。"}
D.ItemDescriptions[137081]={["d1b0837de0745eb2:115"]="哨兵都是暗夜精灵中的神射手和精英战士。这些骄傲的神射手有着无人能及的速度和敏捷。"}
D.ItemDescriptions[137082]={["2b0fef9a79a01367:56"]="冥狱深渊每吞噬一个灵魂，鬼魅般的哀嚎都将在浓雾中久久回荡。"}
D.ItemDescriptions[137083]={["4baf623ceea2a8bf:72"]="用巨型始祖龙鳞片制成，看上去非常古老，但摸上去还是热的。"}
D.ItemDescriptions[137084]={["be07760f5dc4b2e4:43"]="他的熔岩之力足以改变整个地貌。"}
D.ItemDescriptions[137085]={["5409d4b92eaad3fa:152"]="纳沙塔尔的纳迦都是巫术大师，也是天生的深海住民。穿着他们蜕下的皮能强化你对潮汐的掌控能力。"}
D.ItemDescriptions[137086]={["34d9eba761b19e84:107"]="它的锁链间回荡着一位古代瓦哈拉斯勇士的祈祷声：只要你沐浴在圣光之下，就永远不会孤军奋战。"}
D.ItemDescriptions[137087]={["e54955b6da7977d1:85"]="在纳迦中间，瓦丝琪的勇士、伊利丹·怒风的仆从纳因图斯的力量几乎无人能及。"}
D.ItemDescriptions[137088]={["a53de07e7a7602c5:49"]="传说中的战士总会直面对手。"}
D.ItemDescriptions[137089]={["3680eb744a530541:69"]="于是，雷霆之神对僭越者降下了天谴怒雷……"}
D.ItemDescriptions[137090]={["49ead5b363a778a6:44"]="只要你能拿稳锯子，就能拿稳战刃。"}
D.ItemDescriptions[137091]={["58b2905eef6ea1dd:118"]="在污染者高地与洛拉姆斯·萨里比迪斯的一战中，这对臂甲从拉瑟莱克的手腕上掉了下来，飞过了黑暗之门。"}
D.ItemDescriptions[137092]={["3b918cd5cad5c2ec:45"]="安格拉雅差点就把它命名为“欧奈斯的自负”了。"}
D.ItemDescriptions[137094]={["ee445888795f41db:81"]="扭曲的荒野德鲁伊希望有一天能掌握奥兹恩赋予这对护腕的力量。"}
D.ItemDescriptions[137095]={["5b1b53eb77f679b2:85"]="用一头永远乐观向上的上古公牛的牛皮制成。"}
D.ItemDescriptions[137096]={["bca3128370e7ff52:27"]="啊……闻起来像是雨后的味道。"}
D.ItemDescriptions[137097]={["bf9b399b964c2844:75"]="只要有足够的烈酒，诺森德强壮的维库人就可以适应各种恶劣的环境。"}
D.ItemDescriptions[137098]={["24f553c3311040ba:152"]="佐迪克家族的成员从出生起就接受暗杀训练。他们在驻地下层学习如何使用致命的毒药以及如何抵抗其毒性。"}
D.ItemDescriptions[137099]={["8759b3327949103b:82"]="在无法无天的旅店乱斗和自发的私斗中，精准极为重要。"}
D.ItemDescriptions[137100]={["7041431f7dccc240:121"]="如果你认为牛头人想要借暗影藏身是个笑话，那你应该去看看那些维库半巨人想要在光天化日之下潜行的样子！"}
D.ItemDescriptions[137101]={["c2cbbc157094cdb0:131"]="猎人与荒野有着深厚的羁绊——他们能够召唤野兽守护强化自身，并与最狂野的野兽成为朋友。"}
D.ItemDescriptions[137102]={["5b594c3ee17703d1:84"]="这对护腕上依然流淌着电光。你会感觉自己的力量永不枯竭且还在不断增长……"}
D.ItemDescriptions[137103]={["6d58ecd8c6a0d835:93"]="由一头古老的风暴巨龙的鳞片制成，能对附近的一切释放出无法控制的魔力。"}
D.ItemDescriptions[137104]={["2576d757769a66fa:66"]="先知努波顿心若死灰地离开他的城市，最后又带着元素的力量回来了。"}
D.ItemDescriptions[137105]={["5b59109df179b85a:136"]="白银之手的领袖，乌瑟尔·光明使者在战场上运用这种光环，使他的骑士们时常显得所向披靡，势不可挡。"}
D.ItemDescriptions[137107]={["4f4626779074d062:64"]="来吧，畅饮我的鲜血，你很快也将畅饮敌人的鲜血。"}
D.ItemDescriptions[137108]={["9d146ff7923527fe:177"]="伟大的战士卡库善在与伊瓦贡特一起捣毁了风鳞纳迦位于黑海岸的村庄后，用纳迦的皮制造了这副手甲。在纳迦们望风而逃时，这个维库人畅饮了他们同胞的鲜血。"}
D.ItemDescriptions[137109]={["d2a9af9ab6b84237:45"]="不背叛的话，会有成功的可能吗？"}
D.ItemDescriptions[137110]={["00639933b893e600:35"]="记载了最伟大的瓦拉加尔的事迹。"}
D.ItemDescriptions[137119]={["e04551e397191148:50"]="其中蕴含的恐怖只是观察者的内心写照。"}
D.ItemDescriptions[137173]={["339a7949cce6e220:130"]="征募官田吉会来到五晨寺，使你能够招募玄牛弟子，陪伴你的勇士执行任务。"}
D.ItemDescriptions[137185]={["eb541d232225439a:42"]="一块翻滚着邪能能量的魔法符文石。"}
D.ItemDescriptions[137186]={["89fb84ee74f68d95:48"]="一箱包含各种附魔的魔化牛皮纸。"}
