D.ItemDescriptions[137190]={["2ab0aa45f340f7e0:19"]="一块以邪能铭刻的符文。"}
D.ItemDescriptions[137193]={["1f88a7af9b2a3e76:64"]="一块能量充沛的水晶，来自暴怒的琥珀碎片。"}
D.ItemDescriptions[137195]={["ea2a47dd4ced9934:52"]="一件护甲，原本属于一位已经阵亡的至高岭防御者。"}
D.ItemDescriptions[137196]={["0b73f1c3d8f91074:64"]="灌注了魔法的粉尘，可以给雷霆图腾部族的护甲附魔。"}
D.ItemDescriptions[137206]={["c6908bcb214c4f1c:89"]="艾萨拉女王已经把潮汐之石的碎片拼起来了。把它带到达拉然的艾格文大厅去吧。"}
D.ItemDescriptions[137210]={["196bffb560607bcc:19"]="被邪能魔法封印着。"}
D.ItemDescriptions[137211]={["e97f35a0034def75:62"]="用树皮和树叶编织起来的书籍，用仙灵的文字写成。"}
D.ItemDescriptions[137212]={["c41f63e9704b0758:28"]="可以用来镶嵌指环。"}
D.ItemDescriptions[137213]={["83b88a751605ccae:57"]="漆黑的粉尘，可以通过分解黑鸦堡垒的暗夜精灵所携带的徽记获得。"}
D.ItemDescriptions[137214]={["c41f63e9704b0758:28"]="可以用来镶嵌指环。"}
D.ItemDescriptions[137215]={["c41f63e9704b0758:28"]="可以用来镶嵌指环。"}
D.ItemDescriptions[137220]={["2a72fdb8c814907d:99"]="末日领主卡扎克从他位于基尔加丹王座的宝座上站起，高举长剑，号召恶魔大军投入战斗。"}
D.ItemDescriptions[137221]={["c8e0ecb267c67615:49"]="带有拉文凯斯领主徽记的魔法徽记。"}
D.ItemDescriptions[137223]={["7b508d9ffcfc3368:144"]="来自虚空的黑暗低语表明这个印戒是纳斯雷兹姆在第三次大战前铸造的，并被赐予了天灾军团最强大的副官之一。"}
D.ItemDescriptions[137226]={["564bd7530ac7d620:74"]=S[361]}
D.ItemDescriptions[137227]={["05011f8543ff48c6:32"]="杀了这个家伙，我们就赢了。"}
D.ItemDescriptions[137235]={["3887f7051fb29c48:49"]="一袋非常古老的阿卡纳精华，但效力看起来依然强大。"}
D.ItemDescriptions[137246]={["7eee7c48b8a1556d:87"]="启迪者的尖叫声在阿古斯回荡，残酷地提醒着众人与恶魔打交道的代价。"}
D.ItemDescriptions[137247]={["564bd7530ac7d620:74"]=S[361]}
D.ItemDescriptions[137251]={["d277c87fe2a29d7e:105"]="贾九鹤会来到你的职业大厅，让你能够研究职业大厅的升级树。"}
D.ItemDescriptions[137268]={["2a17c11389093eba:52"]="获得这块萨维斯的灵魂碎片一定能削弱他的力量。"}
D.ItemDescriptions[137271]={["072f51b0be5be677:72"]="考古挖掘中获得的碎片。纳萨尼斯应该会对它感兴趣的。"}
D.ItemDescriptions[137273]={["6b9968a12c3d1ba6:31"]="一块散发着奇异光芒的石头碎片。"}
D.ItemDescriptions[137276]={["a93f077470eacdff:36"]="对我来说这些都是徒劳。"}
