D.ItemDescriptions[137378]={["fd303c41f024bda6:136"]="别人也能将狂暴的风暴压缩进一个小瓶子里，但风暴召唤者伊娜亚德对这一领域最大的贡献是能够同时保持风暴的寒气。"}
D.ItemDescriptions[137382]={["125b479578661772:98"]="蔑冬部族的狩猎大师沃顿著名的伙伴，兽王拜科的爪子。"}
