D.ItemDescriptions[137422]={["76fbc80ddad795aa:29"]="幸好它是纯文字版的。"}
D.ItemDescriptions[137423]={["414bc519108e5cf6:34"]="从咔啡到鱼人，包罗万象，应有尽有。"}
D.ItemDescriptions[137426]={["2e29cf92ff3b32a9:18"]="这可是初版！"}
D.ItemDescriptions[137485]={["19d191c09a0d2d75:53"]="这份文件简洁而精准。简洁是文书的灵魂。"}
D.ItemDescriptions[137490]={["7ec85e8879d7d1e1:71"]="凭借这些魔法文件你应该可以进入破碎群岛的任何聚会。"}
