D.ItemDescriptions[137616]={["0e259c36b39d782b:96"]="在冬拥湖深处的宝库内，风暴看守者埃玛尔隆抱着必死的决心坚守阵地。"}
D.ItemDescriptions[137617]={["eeb501e61ca5259d:38"]="一捆紧紧绑住的手写笔记。"}
D.ItemDescriptions[137618]={["d67a1f843bdb8e7b:68"]="来自至高岭地区的多彩水果，能提供最低限度的食物。"}
D.ItemDescriptions[137621]={["cb7b32d5d805ce6c:66"]="大巫妖克尔苏加德的日志，写于纳克萨玛斯时期。"}
D.ItemDescriptions[137622]={["64952112999f2a35:29"]="里面看起来有点狭小。"}
D.ItemDescriptions[137628]={["3fcea4789f5c25db:36"]="摸上去很柔软，却出奇地结实。"}
D.ItemDescriptions[137636]={["5cb864ddad45920e:42"]="虽然在当时是最好的，但早已风光不再。"}
D.ItemDescriptions[137637]={["2d3a4c97bbe96706:55"]="这些武器储存时间过久，已经无法用于战斗了。"}
D.ItemDescriptions[137638]={["94e3f1d45c30134f:82"]="这件制服似乎曾过于靠近邪能能量源，不该再穿了。"}
D.ItemDescriptions[137639]={["391d410f999148e8:96"]="这些武器在极度严寒的环境里放得太久了，它们在气温较高的战场上会变得非常易碎。"}
D.ItemDescriptions[137640]={["fe6db7fefa664359:92"]="由于长期暴露在温暖潮湿的环境下，这些武器非常湿滑而且发生了霉变。"}
D.ItemDescriptions[137641]={["4aa4bd338a304a2e:60"]="当地的钢铁部落金属显然不是耐用的武器材料。"}
D.ItemDescriptions[137642]={["08f1ba0e71355033:58"]="用于在PvP商人处换取旧版武器和护甲。"}
D.ItemDescriptions[137643]={["0da92e95f7893faa:51"]="看起来原本应该有一对，但比较好的那把丢失了。"}
D.ItemDescriptions[137644]={["c4e7464d3b48bd26:50"]="看起来不像熊的心脏。这是从哪儿来的？"}
D.ItemDescriptions[137649]={["2c106281582bc838:98"]="卡兹格罗斯之锤已经脱离了地底之王达古尔的魔掌。将它带到达拉然的艾格文大厅去吧。"}
D.ItemDescriptions[137654]={["b0fc79fefa2268ad:11"]="需要颜料。"}
D.ItemDescriptions[137659]={["49dfa04a01ba5123:25"]="闪烁着微弱的邪能魔法。"}
D.ItemDescriptions[137660]={["1df204d15ec1397a:65"]="我们从未有意踏上这条道路。而现在……现在这个年轻的世界将要面临毁灭。"}
D.ItemDescriptions[137661]={["bb8c79782f49ec33:101"]="这面盾牌可以映照出洛肯的谎言和阴谋。我将与你同在，帮助你赢得这场战争。"}
