D.ItemDescriptions[138004]={["e8e00c2ad4d2505d:46"]=S[13050]}
D.ItemDescriptions[138006]={["16dc8afd23ec3b90:43"]=S[13051]}
D.ItemDescriptions[138007]={["16dc8afd23ec3b90:43"]=S[13051]}
D.ItemDescriptions[138009]={["195ca64a3a2c417f:43"]=S[13052]}
D.ItemDescriptions[138010]={["195ca64a3a2c417f:43"]=S[13052]}
D.ItemDescriptions[138011]={["278e863e8fd34a19:38"]="教你学会制作丝纹背包。"}
D.ItemDescriptions[138012]={["fd0c7909027b3498:36"]="教你学会制作丝纹手套。"}
D.ItemDescriptions[138013]={["91924d44a71920f5:35"]="教你学会制作丝纹兜帽。"}
D.ItemDescriptions[138014]={["0cc85b8b37db577c:38"]="教你学会制作丝纹便鞋。"}
D.ItemDescriptions[138015]={["28abc7f890bb612b:40"]="教你学会制作丝纹马裤。"}
D.ItemDescriptions[138016]={["119d2f6e169bcfc7:50"]="教你学会制作衣柜：达拉然平民。"}
D.ItemDescriptions[138017]={["4f2bedfd85d95770:53"]="教你学会制作衣柜：卡拉赞歌剧院。"}
D.ItemDescriptions[138018]={["d3d2060aff3e360b:45"]="教你学会制作衣柜：熔火之心。"}
D.ItemDescriptions[138019]={["d0d4b930a0427a35:60"]="在傳奇難度中，放置在地城裡的能量之泉內。"}
D.ItemDescriptions[138020]={["a898116d11f4f9e4:24"]="维库人烧烤中最受欢迎的美味。"}
D.ItemDescriptions[138021]={["5c788952e68dc763:26"]="可以织成保暖的毛衣。"}
D.ItemDescriptions[138022]={["62e47bc4f93e62ed:30"]="这玩意儿差点咬掉你的手指。"}
D.ItemDescriptions[138023]={["a29e562d5523fc9c:53"]="经过仔细观察，你发现这些牙齿其实并不是石质的。"}
D.ItemDescriptions[138024]={["afe8923d190cffc4:37"]="这么大的鳍足够熬一大锅好汤了。"}
D.ItemDescriptions[138026]={["c39b3084da7ed211:45"]="神奇地不断散发着微弱的嗡鸣声。"}
D.ItemDescriptions[138097]={["01f1046822485dfb:26"]="他已经用不着它了。"}
D.ItemDescriptions[138098]={["85a22a1a1473f6d3:28"]=S[5490]}
D.ItemDescriptions[138111]={["aafb5ef2f5aa00c3:45"]="可以使用风暴峡湾各地的锚点。"}
D.ItemDescriptions[138112]={["ba5f9a0d362bb76a:60"]="强大的恶魔仪式经常需要来自纯洁的灵魂的完整颅骨。"}
D.ItemDescriptions[138113]={["de41fe5a9bb9e9bd:54"]="只有最黑暗的魔法才会用到真正的无辜者的鲜血。"}
D.ItemDescriptions[138114]={["7ccd07aadd6814a1:67"]="一种有着锋利牙齿的白化狂鱼，会在薄暮岛礁附近出没，不过非常少见。"}
D.ItemDescriptions[138117]={["b4ec77324680aa41:74"]="“要想控制狼，你必须把自己也变成狼。”——一位维库疯萨满的建议。"}
D.ItemDescriptions[138120]={["49ce393860b7ad55:126"]="莉莉丝会来到梦境林地，使你能够招募梦境林地树人，陪伴你的勇士执行任务。"}
D.ItemDescriptions[138121]={["9e08edcac8b94bfd:87"]="传说中的叶须让你能够研究职业大厅的升级树。"}
D.ItemDescriptions[138123]={["ba8645261467a2ad:20"]="感觉有点轻。"}
D.ItemDescriptions[138124]={["ae6810d4ac4ad51b:42"]="上面的涂料是如此耀眼，几乎能让你相信这就是真金！"}
D.ItemDescriptions[138125]={["0190ea6d1633f316:27"]="摸上去冷冰冰的。"}
D.ItemDescriptions[138126]={["ffb00c4fa8d1b262:31"]="这足以说明现在的温度了。"}
D.ItemDescriptions[138127]={["ef7ce8da47bfe519:23"]="看起来有点眼熟。"}
D.ItemDescriptions[138128]={["f949ed1ebfd9fde1:38"]="这种东西已经完全不值钱了！"}
D.ItemDescriptions[138129]={["2ddb520439b0d613:31"]="摸上去十分柔软，但有一股淡淡的臭味。"}
D.ItemDescriptions[138130]={["c9fb16d426ba448f:37"]="上面的棕榈树图案已经出卖了它。"}
D.ItemDescriptions[138131]={["60c3bf2760fc8e48:51"]="一旦种下，它们就能长出像山一样高的藤蔓！"}
D.ItemDescriptions[138132]={["78400aaf3d49ef02:17"]="你以为会是啥？"}
D.ItemDescriptions[138133]={["5eb75e2ec82cb931:48"]="据说能赋予饮用者神奇的力量和智慧。"}
D.ItemDescriptions[138134]={["9cc7802a9914d01f:32"]="你很确定这是地精的尿液。"}
D.ItemDescriptions[138136]={["25ffe91ef2100637:56"]="凑齐一对这种贝壳，就可以传递任何声音。"}
D.ItemDescriptions[138137]={["49ee34060144e6c3:140"]="哈尔玛·斯塔索姆队长会来到英灵殿，使你能够招募瓦拉加尔候选者，陪伴你的勇士执行任务。"}
D.ItemDescriptions[138138]={["90d15b047ed94193:110"]="符文法师艾纳尔会来到你的职业大厅，让你能够研究职业大厅的升级树。"}
D.ItemDescriptions[138139]={["79ce11d8fc759e13:133"]="这本书中记载的魔法知识能帮助主母玛沃伦丝穿透防止他人传送进黑暗神殿的神圣屏障。"}
D.ItemDescriptions[138140]={["6c91a095a8f79648:51"]="有时候使用控制方格会让这对护腕报废。"}
D.ItemDescriptions[138142]={["f1d9d36524560eec:52"]="枯木巨魔的首领，欧金巴的徽记。"}
D.ItemDescriptions[138147]={["d5d5fb3e6eb64f1b:61"]="通过徒手接触，能够随意升起或降下附近的屏障。"}
D.ItemDescriptions[138148]={["ec57300c58274edd:63"]="托尔贝恩家族代代传承的传奇长剑。"}
D.ItemDescriptions[138149]={["7e909544d23e2ad5:51"]="这块石头上的维库标志看起来像是某种警告。"}
D.ItemDescriptions[138150]={["571d58a76211b2bc:67"]="透过水晶折射进来的光线令它呈现出一种近乎液体的状态。"}
D.ItemDescriptions[138151]={["9336b4d44ae44fc5:51"]="看来不值什么钱，但可能包含着宝贵的知识。"}
D.ItemDescriptions[138190]={["d40b288d61fd268a:54"]="芬德利相信这玩意儿能钉死古代维库鲜血王子。"}
D.ItemDescriptions[138194]={["d0902da321341a64:44"]="一叠沉重的手抄笔记和卷轴。"}
D.ItemDescriptions[138196]={["e8e8802feacb2270:83"]="事实上，这本书具有强大的魔力，显然没人能够永久占有它。"}
D.ItemDescriptions[138201]={["24146c488b5a7fa3:31"]=S[13087]}
D.ItemDescriptions[138202]={["df7e3b511175d584:53"]="在我的马上加装烟火？这个主意听起来真是太棒了！"}
D.ItemDescriptions[138206]={["be2cbcb2f8547afb:40"]="由于含有未消化的魔石残渣而闪闪发光。"}
D.ItemDescriptions[138231]={["9af0110753ec1c88:130"]="战争领主加尔顿会来到邪能之槌号，使你能够招募灰舌战士，陪伴你的勇士执行任务。"}
D.ItemDescriptions[138232]={["607de25eee4da2e3:109"]="洛拉姆斯·萨里比迪斯会来到你的职业大厅，让你能够研究职业大厅的升级树。"}
D.ItemDescriptions[138238]={["6a28e7b8efcda9dd:12"]="当然了，有何不可？"}
D.ItemDescriptions[138239]={["3fd4b76dfcf7ef86:27"]="或许可以当碗用？他需要碗吗？"}
D.ItemDescriptions[138240]={["f057db33cc0b74a6:30"]="这种时候，你什么都得试试。"}
D.ItemDescriptions[138241]={["33d878beac70e559:40"]="从贝壳中抖出来的，光滑且大小一致的沙子。"}
D.ItemDescriptions[138242]={["7e764d1dc6de6026:57"]="迷信的精灵认为这些卡牌能够揭示未来。"}
D.ItemDescriptions[138243]={["e96efc1961845e8c:46"]="只残留了少量古代艾萨拉时期工艺的痕迹。"}
D.ItemDescriptions[138244]={["6c6ca1a3a66b48a8:65"]="燃烧军团的存在污染了这些夜之子偏爱的“零食”。"}
D.ItemDescriptions[138245]={["41f97ca928547404:33"]="过期的稀有酒水。"}
D.ItemDescriptions[138246]={["33a0c7fe4039c4f1:104"]="只有一个办法才能知道这到底是去年腌制的还是一万年前腌制的，打开罐子的任务最好还是留给别人吧。"}
D.ItemDescriptions[138247]={["dc2cae2ceef0f8cd:81"]="夜之子贵族最喜欢的乐器，但是因为使用不当而被轻易损坏了。"}
D.ItemDescriptions[138248]={["33c566c4a8f1166f:79"]="这尊小石雕的工艺与卓格巴尔在其他方面表现出的粗枝大叶完全不符。"}
D.ItemDescriptions[138249]={["03c236b68f228415:57"]="时光与风霜已经抹去了这本书中原本所有的秘密。"}
D.ItemDescriptions[138250]={["eaf403aee48da50f:54"]="女王的美丽雕像，已有几百年的历史。"}
D.ItemDescriptions[138251]={["332261ec7a4258b7:92"]="你很难说出这到底是几百年前从巢穴里偷出的龙蛋，还是一个石雕的仿制品。"}
D.ItemDescriptions[138252]={["cac3000fe53e61ec:110"]="记载者艾瑞安妮会来到你的职业大厅，让你能够研究职业大厅的升级树。"}
D.ItemDescriptions[138253]={["4766583ffec9c68a:43"]="一团黏糊糊的诱饵，主要由魔虫内脏制成。"}
D.ItemDescriptions[138258]={["69f5e24752b91ada:50"]=S[13091]}
D.ItemDescriptions[138270]={["39032963acd00b74:68"]="虽然扭曲破碎，但这一小块木材比看起来要结实得多。"}
D.ItemDescriptions[138271]={["c7a990b8793da5bb:41"]="这瓶水中翻滚着明亮的奥术能量。"}
D.ItemDescriptions[138272]={["df93eb0036c593ab:30"]="用于收集魔法之水。"}
D.ItemDescriptions[138273]={["0f13370ae447e7e1:81"]="在采集魔石矿时偶尔能发现这种矿石，老练的铁匠能用它来打造武器。"}
D.ItemDescriptions[138274]={["cadfb96781df25ec:77"]="装满了铁匠凯瑞尔制作的箭头、弹药以及矛头。"}
D.ItemDescriptions[138291]={["d1be40e70460973e:54"]="史密斯夫人还没有为这种新品最终定名。"}
D.ItemDescriptions[138294]={["155bdbb89792cced:68"]="最受欢迎的查丽妮葡萄酒，口感清爽，色泽乳白并带有一丝微酸的口感。"}
D.ItemDescriptions[138295]={["ff9bbb5b0daba4c6:99"]="查丽妮酒庄受法罗迪斯家族委托特别酿造的美酒，是一种具有复杂的口感，且对头脑有益的红酒。"}
D.ItemDescriptions[138296]={["19499a4e32155fb5:34"]="一小块经过切割的宝石，可以作为魔力焦镜使用。"}
D.ItemDescriptions[138297]={["27982a3c1a032f73:40"]="用古代精灵魔法制成的能量核心。"}
D.ItemDescriptions[138298]={["aa626932e235d3a3:27"]="它一秒钟前才出现在那儿的吧？"}
D.ItemDescriptions[138299]={["6c7d2b367db788a9:34"]="覆满尘土，散发着腐朽的味道。"}
D.ItemDescriptions[138300]={["6c16558c0fd29ce5:68"]="一个神秘的箱子，里面的空间比它看起来要大得多。"}
D.ItemDescriptions[138303]={["6f1f69b51d0958ee:76"]="装满了经过莉娅娜·星尘附魔的箭头、弹药以及矛头。"}
D.ItemDescriptions[138307]={["4129de6804f658b1:67"]="虽然不知道是什么时候过期的，但这块奶酪肯定过期了。"}
D.ItemDescriptions[138382]={["228666257643a18a:18"]="只能带来一丁点儿运气。"}
D.ItemDescriptions[138383]={["9d527e72870c5bef:13"]="多少能带来点运气。"}
D.ItemDescriptions[138384]={["da2d5c83e7a9d35c:11"]="能带来不少好运。"}
D.ItemDescriptions[138385]={["eb81473af2fc4d5f:15"]="能带来许多好运。"}
D.ItemDescriptions[138387]={["24146c488b5a7fa3:31"]=S[13087]}
D.ItemDescriptions[138388]={["564bd7530ac7d620:74"]=S[361]}
D.ItemDescriptions[138390]={["564bd7530ac7d620:74"]=S[361]}
D.ItemDescriptions[138397]={["b91c6dc7c98b7a86:115"]="萨格拉斯的力量在这个被邪能腐化的泰坦仪器中流淌。它就像一把万能钥匙，能打开所有被燃烧军团占领的世界，包括阿古斯。"}
D.ItemDescriptions[138398]={["fafa6a5db4243f0c:35"]="闪电在其中劈啪作响，就像一团雷云。"}
D.ItemDescriptions[138400]={["542e864b9f4da4c0:26"]="漂亮的小鸟……漂亮的小鸟……"}
D.ItemDescriptions[138414]={["dc725012b4bae9b7:28"]="为了一年之中其余的364天。"}
D.ItemDescriptions[138415]={["ce92024cdc9b3be7:25"]="里面还有几页是好的。"}
D.ItemDescriptions[138417]={["bbb7c7b4033da831:57"]="你可能会问他为什么会选红色的围裙。这是一个好问题。"}
D.ItemDescriptions[138419]={["4f1bbf7a03d45e63:48"]="铭刻着魔法符文，还使用了散发着能量的墨水。"}
D.ItemDescriptions[138420]={["784f39e4e2ea7d9d:74"]="秃鹫特别偏爱双头怪的筋，它们能大大减少筑巢所需的材料。"}
D.ItemDescriptions[138432]={["aafa2c5eefa7f2df:24"]="魔法使它们保持了锋利。"}
D.ItemDescriptions[138433]={["bf396382b31a4e11:25"]="散发着艾露恩的光辉。"}
D.ItemDescriptions[138435]={["f5e4c4d09e4560e1:42"]="精心栽培了几千年。"}
D.ItemDescriptions[138448]={["c49e2cf14c648b98:41"]="这个徽记似乎被鱼线缠住了。"}
D.ItemDescriptions[138450]={["ee886722c21fe8ef:67"]="授予出发参加破碎海滩之战的联盟英雄。"}
D.ItemDescriptions[138451]={["5c625403413db9d6:35"]="教你学会切割致命深海琥珀。"}
D.ItemDescriptions[138452]={["3effaa1bfdf9b568:33"]="教你学会切割迅捷阿苏奈特黄晶。"}
D.ItemDescriptions[138453]={["6bacdec2951becd9:40"]="教你学会切割精湛女王猫眼石。"}
D.ItemDescriptions[138454]={["ce290960c56b6bcf:39"]="教你学会切割致命先知之眼。"}
D.ItemDescriptions[138455]={["5c6be5cad605826b:34"]="教你学会切割迅捷晨光石。"}
D.ItemDescriptions[138456]={["1b05b726621150e7:39"]="教你学会切割精湛暗影紫玉。"}
D.ItemDescriptions[138477]={["17a51ca4d07f3ae5:49"]="它被摘取时，腐蚀还没有扩散到这里。"}
D.ItemDescriptions[138480]={["f9a148f2f1e3e9d3:65"]="一本发霉的书籍，里面写满了潦草的古代文字。"}
D.ItemDescriptions[138482]={["cae4000043c23fe9:46"]="收集足够的灵魂，为邪能之槌号的迁跃引擎提供能量。"}
D.ItemDescriptions[138483]={["7959fa8ec110306f:32"]="没错，可它到底能注射什么？"}
D.ItemDescriptions[138484]={["3261da03f923c9bc:84"]="它同时采用了尖端科技和强大的魔法。你最好还是把它留给专业人士，或是杰斯。"}
D.ItemDescriptions[138485]={["40dca8c92a96b08e:85"]="无论它有什么用，都不是什么好东西。不过至少它只对邪恶的灵魂起作用。反正它的名字是这么说的。"}
D.ItemDescriptions[138486]={["a10437b925b8f1be:66"]="由嗅盐和七种酒类混合而成的合剂，浑浊且散发着恶臭。"}
D.ItemDescriptions[138487]={["7dbf964518371922:34"]="一把邪恶的武器，被一个邪恶的存在所利用。"}
D.ItemDescriptions[138488]={["1c18274bd433c2aa:54"]="用未能晋级的争斗者们流下的泪水蒸馏而成。"}
D.ItemDescriptions[138490]={["d476b2da3cf67863:33"]="一位伟大的恢复萨满的标志。"}
D.ItemDescriptions[138623]={["83cef943a918309a:53"]="由于长期暴露在高温中，这些谷物被熏黑了，令其呈现出深棕色。"}
D.ItemDescriptions[138624]={["30f7e135367e79e2:19"]="有一点点硫磺味儿。"}
D.ItemDescriptions[138730]={["db870a0b90d1147e:30"]="警告：不要在骑乘坐骑时使用。"}
D.ItemDescriptions[138760]={["bbed3025b057b15c:131"]="指挥官安瑟拉会来到圣光之愿礼拜堂，使你能够招募新晋侍从，陪伴你的勇士执行任务。"}
D.ItemDescriptions[138761]={["0ef366979500274a:112"]="阿拉曼德·格雷索恩爵士会来到你的职业大厅，让你能够研究职业大厅的升级树。"}
D.ItemDescriptions[138763]={["92fc9808ef464dff:53"]="一头被关在笼子里的年幼地狱犬，你希望笼子足够结实。"}
D.ItemDescriptions[138788]={["a090089d8e6f9b64:23"]="劣魔的食物，别吃。"}
D.ItemDescriptions[138810]={["9d6d0e19bc8fb050:35"]=S[13094]}
D.ItemDescriptions[138811]={["9902aa808d6a3add:70"]=S[13089]}
D.ItemDescriptions[138815]={["dddd3dc94d82c41e:45"]="摧毁堵住熊怪大门的魔法劣魔根须。"}
D.ItemDescriptions[138817]={["3e2e4ce27480c013:73"]="燃烧着强大的邪能，在合适的人手中，可以被用来对抗燃烧军团。"}
D.ItemDescriptions[138826]={["9766ee1502d226bc:54"]="一堆颓石海滩附近的螃蟹残肢。"}
D.ItemDescriptions[138830]={["389249cb3278f854:56"]="有关乌萨勒斯，逆风收割者消息的最新报告。"}
D.ItemDescriptions[138840]={["5be3dd9a0d7d576f:25"]="适合真正的书虫。"}
D.ItemDescriptions[138841]={["7ff4d28148c03d4e:74"]="一个渔夫朋友借给我的旧手套。遇到会咬人的鱼时，它们可以保护你的手指。"}
D.ItemDescriptions[138842]={["f61fb6037b2f7798:51"]="等你不得不扔掉它们时，为什么不把皮革回收利用一下呢？"}
D.ItemDescriptions[138843]={["f8ac357b6217e9e4:51"]="真怀念那些可以戴着漂亮手套工作的日子。"}
D.ItemDescriptions[138848]={["6b0113765b11bf7f:31"]="它们竟然如此普通。"}
D.ItemDescriptions[138849]={["cbc5f2270c4d29a6:56"]="有关萨奇尔，堕落者之颅消息的最新报告。"}
D.ItemDescriptions[138850]={["ac9e73139883ac6a:66"]="如果你把大本营安在漩涡附近，船只就很容易损失货物。"}
D.ItemDescriptions[138853]={["3107ab6533076cb0:41"]="紫色与金色的漩涡在其中翻腾旋转着。"}
D.ItemDescriptions[138854]={["29dad6be5bf15e91:102"]="我被囚禁了一万年，又被逐出了自己的故乡。现在，你们竟敢闯入我的领地？真是自寻死路……"}
D.ItemDescriptions[138866]={["b8097e61c2e9d180:37"]="细腻的飞蛾粉尘围绕着它。"}
D.ItemDescriptions[138872]={["564bd7530ac7d620:74"]=S[361]}
D.ItemDescriptions[138874]={["9708f527964744c0:23"]="不可与卡亚可乐混合饮用。"}
D.ItemDescriptions[138875]={["6e516be12524dd88:74"]="枯法者和堕夜精灵通常会收集比这更小的水晶来缓解魔瘾。"}
D.ItemDescriptions[138877]={["4a26d4238f4bcf26:60"]="教你学会制作幻象之书：影踪派的秘密。"}
D.ItemDescriptions[138879]={["f5c487d07a287d21:109"]="根据历史记载，哲学家欧维德是少数不用剑的维库人之一，他选择使用言语作为自己的武器。"}
D.ItemDescriptions[138882]={["87b9f604fe0e46f7:46"]="教你学会制作幻象之书：德拉诺。"}
D.ItemDescriptions[138892]={["c30e3afe61ee954f:40"]="但愿他们有一天能理解我的所作所为。"}
D.ItemDescriptions[138893]={["0832952446f909ad:37"]="我想要一些法力……现在就要！立刻就要！马上就要！"}
D.ItemDescriptions[138894]={["2589c9e61ee8ef5f:28"]="请保佑我的祖父。"}
D.ItemDescriptions[138895]={["0adf04d807fb49ed:40"]="拜托，让我的孙女能开心点。"}
D.ItemDescriptions[138896]={["d1e49d605278cbe7:71"]="这次冒险真了不起，可我距离我的莫亚基太远了。希望我能早日回家。"}
D.ItemDescriptions[138897]={["db5d9f63ed84a36a:81"]="这是什么鬼？这些该死的蠢蛋为什么要把好好的硬币扔掉？！"}
D.ItemDescriptions[138898]={["8eedc6c6ff5fcea3:34"]="高尔克希望高尔克能挤出这座洞穴。"}
D.ItemDescriptions[138899]={["12b495c58fd35ba4:27"]="我想再长高一点。"}
D.ItemDescriptions[138900]={["abccc7ea7f84a621:20"]="你不可能把香肠当帽子戴！"}
D.ItemDescriptions[138901]={["9f27ad1e0952ff6f:76"]="我想要保护我珍视的一切，并继续传播艾露恩的仁慈与光辉。"}
D.ItemDescriptions[138902]={["f38a8c5475657b89:32"]="现在阻止梦魇已经太迟了吗？"}
D.ItemDescriptions[138903]={["5f69289939041528:74"]="如果我们能遏制住无穷无尽的恶魔大潮，这个世界或许就能恢复一些色彩。"}
D.ItemDescriptions[138904]={["cc145d1a42100187:53"]="愿我的部队经受住这片土地的考验。"}
D.ItemDescriptions[138905]={["2e8aa88a6e719721:47"]="我有点希望自己是个狼人。那很酷不是吗？"}
D.ItemDescriptions[138906]={["b111c8fc33f0c4a5:99"]="我要感谢塞纳里奥议会。愿这些凡人德鲁伊能够继续为我父亲的名字增光添彩。"}
D.ItemDescriptions[138907]={["3d8fd7531ce49bd4:39"]="唔……没硬币可丢。不知道这样行不行？"}
D.ItemDescriptions[138908]={["bcd72daef3bd36d1:37"]="我想我可能想要一大罐蜂蜜。"}
D.ItemDescriptions[138909]={["87af39e1b5e34b58:61"]="有时，我觉得鱼人们并不喜欢我为他们所做的一切。"}
D.ItemDescriptions[138910]={["5e517a0e3665fdcd:65"]="希望我儿子加把劲儿，快生几个孩子出来。我还想打一头驼鹿。"}
D.ItemDescriptions[138911]={["2e5ac3728eefcc77:24"]="哞嗚嗚，嘎啦啦嘎拉，哞嗚嗚，嘎啦啦嘎啦，嘎啦啦。"}
D.ItemDescriptions[138912]={["70bbc68afcd68059:36"]="纪念我失去的所有兄弟姐妹。"}
D.ItemDescriptions[138913]={["ee5dc24b90291e24:44"]="噢，噢！我希望可以用上超酷的真枪！砰！"}
D.ItemDescriptions[138914]={["4059b61b7e08a0fa:46"]="来吧，动起来，闪电！就像练习时那样！"}
D.ItemDescriptions[138915]={["9a3916388013dd1f:90"]="我想找个蜡烛王后！唔……也许杰西会感兴趣？我要把我的蜡烛送给她，看看会怎么样。"}
D.ItemDescriptions[138916]={["4dddb6890b758cd0:37"]="我恨一切东西。一切都好可怕。"}
D.ItemDescriptions[138917]={["7111a03841ae1233:21"]="力量。荣耀。权威。"}
D.ItemDescriptions[138918]={["8dbed54ff4f76056:65"]="哪怕是为着同样的目标，也无法抹杀被遗忘者曾犯下的暴行。"}
D.ItemDescriptions[138919]={["4c02ba6e011a1319:30"]="黑暗女王眷顾着这座喷泉。"}
D.ItemDescriptions[138920]={["ee45b932c435bb29:44"]="如果有人找到这枚硬币，请……亲自把它交还给我。"}
D.ItemDescriptions[138921]={["0e624cd3f6bfbe0a:41"]="老天爷，这是许愿池吗？真稀奇。"}
D.ItemDescriptions[138922]={["d227785ab809fb0d:42"]="呃……这肉太干了，再来点肉汁就好了。"}
D.ItemDescriptions[138923]={["8216f5e055377585:63"]="跟冒险者说话太累了……我只想清净几十年……"}
D.ItemDescriptions[138924]={["d31ef0b8b32d054d:24"]="骗到你了，你这个蠢喷泉。"}
D.ItemDescriptions[138925]={["5cf4b1e7bb7c51f6:72"]="愿被压迫的人民有一天能够站起来，取代那些压迫者。"}
D.ItemDescriptions[138926]={["761d6c3b06948a72:77"]="我要不惜一切代价保护我的人民远离那些想要伤害他们的邪恶外来者。"}
D.ItemDescriptions[138927]={["894d35aa6a2bdb9d:43"]="噢，我想要一个能跟得上我思路的学徒！"}
D.ItemDescriptions[138928]={["b49887bf78a1ab82:63"]="我希望我父亲还活着，指引我们渡过这个艰难的时代。"}
D.ItemDescriptions[138929]={["b2e71276d8a5ed35:13"]="嘎嚕嚕嘎啦，哞啦哞。"}
D.ItemDescriptions[138930]={["40109ac8b12038e1:55"]="还是把愿望留给你自己吧。我从不跟喷泉讨价还价。"}
D.ItemDescriptions[138931]={["cb7ea8ca6f065d67:25"]="我想让所有世界都化为火海。"}
D.ItemDescriptions[138932]={["7fd19e063f1470c3:17"]="我想要更多的小猫。"}
D.ItemDescriptions[138933]={["63f0d03ec6900c93:35"]="鱼是没有灵魂的。这毫无意义。"}
D.ItemDescriptions[138934]={["730a283140d92a58:17"]="你自己想吧。"}
D.ItemDescriptions[138935]={["1210743fdc8fb5ba:18"]="我希望自己变得更强大。"}
D.ItemDescriptions[138936]={["7fdfd7b1d56f82ec:127"]="我怀念那个美丽祥和的苏拉玛……可艾萨拉和她的上层精灵毁了一切。许愿什么都实现不了，只能留下悔恨。"}
D.ItemDescriptions[138937]={["e225920ec09ffbbb:190"]="这些法师让我进入这里。虽然大部分人只是用怀疑和蔑视的眼神打量我，甚至会有一些过激反应，但还有一些人能透过表面看出我的本质。我希望大家能够精诚合作，应对我们真正的敌人：燃烧军团。"}
D.ItemDescriptions[138938]={["9706ad98b352fbdb:167"]="在我的前半生，我会很乐意住在这座奇迹般的浮空城中，还会在练习魔法之余来这座魔法喷泉钓几天鱼。但那些日子早已一去不复返了。"}
D.ItemDescriptions[138939]={["9e80343f4dcae8d4:55"]="唯有杰出的领导和清晰的远见，才能引领我们走向胜利。"}
D.ItemDescriptions[138940]={["c24ad2f2fa4d2817:60"]="我可没时间钓鱼许愿，还有恶魔要杀呢。"}
D.ItemDescriptions[138941]={["610970e539804d8a:29"]="在本回合中，获得一个法力水晶。"}
D.ItemDescriptions[138942]={["a1d3b0d2eede46fd:62"]="许愿模式正忙。请稍后再试。（错误37）"}
D.ItemDescriptions[138943]={["d5841f3b1724491a:38"]="愿这片土地沐浴在圣光的荣耀之下。"}
D.ItemDescriptions[138944]={["63a460a9601ef51e:80"]="什么叫自然的召唤？我真的希望有人能来给我解释一下“自然的召唤”到底是什么。"}
D.ItemDescriptions[138945]={["23e6fd3062c47cc9:24"]="让燃烧军团去死。"}
D.ItemDescriptions[138946]={["1e9337891780ed3a:29"]="很快，你们都将感受我的怒火！！！"}
D.ItemDescriptions[138947]={["d58129dfa8479e2a:96"]="对！这样我就能在实现愿望的同时保住我的钱了。哈！噢不，线断了！该死的喷泉，把我的钱还给我……"}
D.ItemDescriptions[138948]={["bbc23800ae6b0eab:59"]="我希望有无穷的新大陆可供我们探索。"}
D.ItemDescriptions[138949]={["91d65e46603278c7:77"]="见证吞没无数世界的烈焰吧。万物都将在燃烧军团的火焰中化为灰烬！"}
D.ItemDescriptions[138951]={["f63bafde84f430c5:39"]="证明了你对火元素的掌控力。"}
D.ItemDescriptions[138952]={["e0a9bb942ce125b7:38"]="证明了你对气元素的掌控力。"}
D.ItemDescriptions[138953]={["e4c9bbfb9fbe300a:40"]="证明了你对水元素的掌控力。"}
D.ItemDescriptions[138966]={["8411c40ced364031:61"]="来自至高岭地区的多彩水果，散发着芬芳的果香。"}
D.ItemDescriptions[138968]={["c3b966385b72d5ff:34"]="用一千颗星辰的光芒编织而成。"}
D.ItemDescriptions[138969]={["76664ca19f01c09a:15"]="散发着微光。"}
D.ItemDescriptions[138971]={["a64cd2d513e50360:28"]="散发着阳光和欢笑的味道。"}
D.ItemDescriptions[138972]={["760848c9a080be62:66"]="罐子里装满了软烂的浆果，上面覆盖着一层“绿色”的保护物质。"}
D.ItemDescriptions[138973]={["90ccf4d12a964e5a:77"]="人们普遍认为绿色的部分是起保护作用的，千万不要吃。"}
D.ItemDescriptions[138974]={["ea39b2d477ab4497:54"]="已经烤焦了，完全看不出原先是什么。"}
D.ItemDescriptions[138975]={["ecd67b3c23b16263:67"]="保持了打来时的状态，但那可能是好久之前了……"}
D.ItemDescriptions[138976]={["b18775f70204d44c:77"]="由于过期，备蹄拿到了一个极低的折扣。但这些糕点看起来并没有坏。"}
D.ItemDescriptions[138978]={["412c3635010db496:34"]="前一天才加入了额外的草料。"}
D.ItemDescriptions[138979]={["22f4f232b17c09ad:47"]="散发着独特的辣椒、橄榄和玉米味儿？"}
D.ItemDescriptions[138981]={["00bba56ae10152c3:27"]="加工后轻了二十磅！"}
D.ItemDescriptions[138983]={["4bdc7b1e2d42a4a7:18"]="浆果味"}
D.ItemDescriptions[138986]={["7269bd4f4acde98a:23"]="一种阿苏纳“风格”的混合饮品。"}
D.ItemDescriptions[138988]={["75c8326ddc282834:43"]="这个被遗忘在时光中的灵魂始终无法安息。"}
D.ItemDescriptions[138989]={["acf7a2cfc0dd92e6:22"]="已彻底腐化，完全没救了。"}
D.ItemDescriptions[138990]={["450cb1859c91ec20:60"]="一件格罗玛什的精致复制品，附赠充气血吼一把！"}
D.ItemDescriptions[138991]={["5553bdd0a6d8b565:33"]="收集足够的鲜血来喂养血石。"}
D.ItemDescriptions[138992]={["687e975f8f229026:69"]="一枚珍贵的奖章，只授予联盟最勇敢的英雄。"}
D.ItemDescriptions[138993]={["eb74e0ab282b1148:30"]="水最纯粹的元素形态。"}
D.ItemDescriptions[138994]={["8be310c3772bf9a4:51"]="大部分人都看不到它，但对能看到它的人而言相当绚烂多彩。"}
D.ItemDescriptions[138995]={["37614bb87e4f957b:35"]="这根权杖散发着强大的能量。"}
D.ItemDescriptions[138996]={["904e73a552305f40:63"]="一枚珍贵的奖章，只授予部落最伟大的英雄。"}
D.ItemDescriptions[138997]={["114ef7a04f6dfa5f:15"]="硬得像……石头一样。"}
D.ItemDescriptions[138999]={["1a4799675830e014:49"]="一尊用沙色岩石雕刻而成的粗糙雕像。"}
D.ItemDescriptions[139000]={["81fdf1e519e4468e:66"]="曾经流淌在这把强大武器中的力量已经几乎消逝殆尽了。"}
D.ItemDescriptions[139001]={["97949612e50f30ab:80"]="征募官A会来到达拉然下水道，使你能够招募[A号部队]。"}
D.ItemDescriptions[139002]={["c21df1cc5a8094e1:105"]="温斯顿·沃尔菲会来到你的职业大厅，让你能够研究职业大厅的升级树。"}
D.ItemDescriptions[139003]={["b18d1240315d11fd:28"]="收容你的朋友们的新地方！"}
D.ItemDescriptions[139032]={["b409f8ff64d1beb8:47"]="泉水极其清澈，让瓶子看起来就像空的一样。"}
D.ItemDescriptions[139034]={["829a6cc1ff2ab9f8:38"]="一份由混沌之手所写成的发光卷轴。"}
D.ItemDescriptions[139035]={["92b5e4c309186aaa:47"]="这本书闪着诡异的光芒。你不敢打开它。"}
D.ItemDescriptions[139037]={["9eecf05fa47e0e24:42"]="剑刃上流淌着风元素领主的力量。"}
D.ItemDescriptions[139038]={["564bd7530ac7d620:74"]=S[361]}
D.ItemDescriptions[139039]={["564bd7530ac7d620:74"]=S[361]}
D.ItemDescriptions[139041]={["0716ae1c7b19a29b:55"]="能够吸取法师精华的魔法容器。"}
D.ItemDescriptions[139043]={["38149bbc03b4b4e1:31"]=S[20123]}
D.ItemDescriptions[139044]={["2d9002291a4e1096:32"]="一个装满了魔石浮标的袋子。"}
D.ItemDescriptions[139046]={["f6c63262e9c56d93:46"]="有关萨格拉斯权杖消息的最新报告。"}
D.ItemDescriptions[139133]={["48c33273ce614d6c:15"]="艾瑞雅的帽子。"}
D.ItemDescriptions[139134]={["e4e5cdb9fa22d9a8:17"]="莉娅娜的帽子。"}
D.ItemDescriptions[139135]={["29bc25c40d48f5af:17"]="穆瑞尔的帽子。"}
D.ItemDescriptions[139136]={["a01382827366a7e3:19"]="洛瑞妮的帽子。"}
D.ItemDescriptions[139138]={["564bd7530ac7d620:74"]=S[361]}
D.ItemDescriptions[139139]={["564bd7530ac7d620:74"]=S[361]}
D.ItemDescriptions[139140]={["ccd34e7fb0debe48:127"]="征募官乐娜拉会来到神射手营地，使你能够招募弓箭手，陪伴你的勇士执行任务。"}
D.ItemDescriptions[139141]={["c4ff995075dc2e2d:120"]="黑暗召唤师马洛格会来到阿彻鲁斯，使你能够招募结群食尸鬼，陪伴你的勇士执行任务。"}
D.ItemDescriptions[139142]={["f12dbcb849639c4d:138"]="资深学者格斯拉会来到虚空之光神殿，使你能够招募助祭，陪伴你的勇士执行任务。"}
D.ItemDescriptions[139143]={["0d8acc7b62cceaca:108"]="档案员祖巴什会来到你的职业大厅，让你能够研究职业大厅的升级树。"}
D.ItemDescriptions[139144]={["cbf6cec54def71b0:104"]="执政官托瑞亚斯会来到你的职业大厅，让你能够研究职业大厅的升级树。"}
D.ItemDescriptions[139145]={["564bd7530ac7d620:74"]=S[361]}
D.ItemDescriptions[139146]={["564bd7530ac7d620:74"]=S[361]}
D.ItemDescriptions[139147]={["564bd7530ac7d620:74"]=S[361]}
D.ItemDescriptions[139148]={["564bd7530ac7d620:74"]=S[361]}
D.ItemDescriptions[139149]={["564bd7530ac7d620:74"]=S[361]}
D.ItemDescriptions[139150]={["564bd7530ac7d620:74"]=S[361]}
D.ItemDescriptions[139151]={["564bd7530ac7d620:74"]=S[361]}
D.ItemDescriptions[139179]={["564bd7530ac7d620:74"]=S[361]}
D.ItemDescriptions[139180]={["564bd7530ac7d620:74"]=S[361]}
D.ItemDescriptions[139181]={["c2ba42eaa13e2121:49"]="托尔巴拉德的囚犯名册，但已经很破了。"}
D.ItemDescriptions[139182]={["a062482a7bff5d73:55"]="有关艾露尼斯，护法者之杖消息的最新报告。"}
D.ItemDescriptions[139183]={["b6b76d06b656ea97:38"]="有关烈焰之击消息的最新报告。"}
D.ItemDescriptions[139184]={["b134542d0daf2b38:54"]="有关黑檀之寒，阿洛迪的圣杖消息的最新报告。"}
D.ItemDescriptions[139185]={["f449a036ab8c2e9b:19"]="依靠魔法得到了妥善保存。"}
D.ItemDescriptions[139215]={["8b45635e2fa662f5:76"]="你用尽全力，也找不到这些环环相扣的锁链是从哪里开始，在哪里结束的。"}
D.ItemDescriptions[139275]={["0077e3e65204401f:20"]="护法者之杖"}
D.ItemDescriptions[139276]={["ac0908bb70afa0a8:49"]="用来开启六触的兄弟们最珍贵的宝箱。"}
D.ItemDescriptions[139279]={["8d40520631ac6527:104"]="这些生活在洞穴中的鱼从未见过阳光。而那些捕食它们的人通常也别想再见到阳光了……"}
D.ItemDescriptions[139286]={["564bd7530ac7d620:74"]=S[361]}
D.ItemDescriptions[139287]={["564bd7530ac7d620:74"]=S[361]}
D.ItemDescriptions[139290]={["4d1accedbb6c60a4:107"]="这本古代精灵书籍是一本账簿。它发霉泛黄的书页详细记载了各种进口物品的每日申领状况。"}
D.ItemDescriptions[139302]={["f3d91beba8109518:92"]="一个未完成的故事，讲述了渡鸦之眼诞生的神话，以及库塔洛斯·拉文凯斯领主是如何得到它的。"}
D.ItemDescriptions[139306]={["564bd7530ac7d620:74"]=S[361]}
D.ItemDescriptions[139307]={["564bd7530ac7d620:74"]=S[361]}
D.ItemDescriptions[139316]={["6b903b237e302ec4:75"]="只是一张发霉的纸而已。上面曾记载过多么神奇的故事呢？"}
D.ItemDescriptions[139317]={["96fd19e4fda2423f:30"]="这把武器已经断裂生锈了。"}
D.ItemDescriptions[139318]={["8fe03d108b17eeb1:64"]="无论这块碎布原本是做什么用的，现在都已经看不出来了。"}
D.ItemDescriptions[139319]={["fffd2946784d2611:83"]="这颗宝石不仅有着完美无瑕的外表，对于无冕者的作用更是无可估量。"}
D.ItemDescriptions[139337]={["18b3a1d16a4dc036:23"]="为你带来一整年的欢乐！"}
D.ItemDescriptions[139350]={["564bd7530ac7d620:74"]=S[361]}
D.ItemDescriptions[139353]={["77acd40bb4984da8:22"]="玛维的护甲和战刃。"}
D.ItemDescriptions[139361]={["564bd7530ac7d620:74"]=S[361]}
D.ItemDescriptions[139363]={["564bd7530ac7d620:74"]=S[361]}
