D.ItemDescriptions[139366]={["564bd7530ac7d620:74"]=S[361]}
D.ItemDescriptions[139367]={["564bd7530ac7d620:74"]=S[361]}
D.ItemDescriptions[139368]={["53cbccd141a6ed4a:55"]="纯净的圣光残留物，采集自艾泽拉斯的各个圣地。"}
D.ItemDescriptions[139369]={["564bd7530ac7d620:74"]=S[361]}
D.ItemDescriptions[139370]={["564bd7530ac7d620:74"]=S[361]}
