D.ItemDescriptions[139373]={["564bd7530ac7d620:74"]=S[361]}
D.ItemDescriptions[139374]={["700d180bbf43782e:57"]="这个护符是由两半拼合而成的，幸好这两半都完好无损。"}
D.ItemDescriptions[139375]={["fd48bb939f08f7b8:65"]="达拉然下水道的马修·莱比斯愿意用盲目之眼来换取它们。"}
D.ItemDescriptions[139377]={["564bd7530ac7d620:74"]=S[361]}
D.ItemDescriptions[139379]={["564bd7530ac7d620:74"]=S[361]}
D.ItemDescriptions[139388]={["f4ef3c83bc2b95cc:107"]="金属球体上蚀刻数千个微小的邪能符文，描述了燃烧军团入侵破碎群岛的行动细节。"}
D.ItemDescriptions[139389]={["d14bf1e75180d15e:32"]="里面的铭文已经难以辨认了。"}
D.ItemDescriptions[139390]={["aebd98d01c41bbdd:71"]=S[5544]}
D.ItemDescriptions[139396]={["4f4b5f7def7444f8:91"]="一种全新的矿物，几乎坚不可摧！如果我们能好好处理一下它就好了，比如做成盾牌什么的……"}
D.ItemDescriptions[139397]={["63125a7c8d6656a9:51"]="极其厚实，很重，但已经开始发臭了。"}
D.ItemDescriptions[139398]={["bd0a3fb449af21bf:68"]="精心摆放，看起来就像一条裤子。另外，如果炼金术不成功的话……"}
D.ItemDescriptions[139399]={["27cf949918e0010a:55"]="软泥中漂浮着金属、毛皮和牙齿。"}
D.ItemDescriptions[139400]={["7c7a954ef2c99a59:144"]=S[4124]}
D.ItemDescriptions[139401]={["4806e21b05e84092:88"]=S[12494]}
D.ItemDescriptions[139402]={["37006a1694f6aafb:124"]=S[10254]}
D.ItemDescriptions[139403]={["b0e13dd847a34f57:103"]="详细记述了历史上的各种魔法神器和武器，由大法师卡莱研究并撰写。"}
D.ItemDescriptions[139404]={["05060e9292e1d239:57"]="听上去很重要。但愿杰斯知道该怎么处理它。"}
D.ItemDescriptions[139409]={["7749c4721018f40b:44"]="以漂亮的书法写着你的名字。"}
D.ItemDescriptions[139410]={["7749c4721018f40b:44"]="以漂亮的书法写着你的名字。"}
D.ItemDescriptions[139416]={["0393e9b74ab24a14:37"]="他在……等着它……吃得脑满肠肥。"}
D.ItemDescriptions[139419]={["e85d851e4c7b6927:29"]="可以作为度量的参考物。"}
D.ItemDescriptions[139432]={["60db810944424ba2:43"]="古代智慧石板，莱登秘典的第一部分。"}
D.ItemDescriptions[139433]={["845bfcd299d54b9f:44"]="古代智慧石板，莱登秘典的第二部分。"}
D.ItemDescriptions[139434]={["17ebf1bba8ff4ae2:45"]="古代智慧石板，莱登秘典的第三部分。"}
D.ItemDescriptions[139445]={["981d65ecc574fbc1:47"]="沉重的金属搭扣锁住了这本书内的漆黑书页。"}
D.ItemDescriptions[139457]={["a6d3669b79d17926:85"]=S[8432]}
D.ItemDescriptions[139458]={["63e32555303e3efe:52"]=S[5481]}
D.ItemDescriptions[139460]={["50c9bc68445283c5:89"]="扭转命运，可给你一次在翡翠梦魇或暗夜要塞获得额外宝物的机会。"}
D.ItemDescriptions[139463]={["63e32555303e3efe:52"]=S[5481]}
D.ItemDescriptions[139464]={["debad5cb37d8aa82:74"]="通过某种不见于记载的仪式，你头脑中的影像可以凭借透镜投射出来。"}
D.ItemDescriptions[139465]={["6f8e97d356b14648:36"]="里面的液体如同有生命般翻滚冒泡着。"}
D.ItemDescriptions[139466]={["26fe9c0b99e2c23e:53"]="禁锢风元素领主桑德兰的左半个镣铐。"}
D.ItemDescriptions[139468]={["1286cf1e9ffc30d1:54"]="禁锢风元素领主桑德兰的右半个镣铐。"}
D.ItemDescriptions[139471]={["8b1098193083ae68:116"]="拉文凯斯阁下，燃烧军团接受你的提议。援军将如期抵达。完成你应尽的义务吧。"}
D.ItemDescriptions[139472]={["93b352ea95b09807:110"]=S[11585]}
