D.ItemDescriptions[139485]={["b803bc3a12548467:19"]="散发着圣光。"}
D.ItemDescriptions[139513]={["3b6b6fdef9e95419:60"]="用柔和的荧光墨水写成。羊皮纸上还散发着淡淡的花香。"}
