D.ItemDescriptions[139535]={["77864ba732cc4b14:52"]=S[16951]}
D.ItemDescriptions[139536]={["7e963faf707f87c4:73"]="风元素领主桑德兰著名的长剑中蕴藏的元素之力的秘密。"}
D.ItemDescriptions[139537]={["d0983ff4b6f045df:84"]="每一代地底之王从即位之日起就会佩戴这根充满了魔力的萨满穗带。"}
D.ItemDescriptions[139538]={["ee2d3e097855d256:50"]="这根鞭子是由萨维斯本身的黑暗能量形成的。"}
D.ItemDescriptions[139539]={["1898498514278644:45"]="早已死去的蔑潮战士的尊贵武器。"}
D.ItemDescriptions[139540]={["ec1952def52d42a9:15"]="匆匆写成，字迹潦草。"}
D.ItemDescriptions[139541]={["fb9db24fee47f15a:38"]="当附近有燃烧军团的传送门时，它会闪闪发光。"}
D.ItemDescriptions[139542]={["d7c0b9845974f42d:32"]="你很怀疑裁缝会不会用得上它。"}
D.ItemDescriptions[139543]={["39ae8f6b85e6cf4e:39"]="出色的造船匠或许可以修好它。"}
D.ItemDescriptions[139544]={["fee3060ce3ea7c65:44"]="曾骄傲地飘荡在维库人长船的桅杆上。"}
D.ItemDescriptions[139545]={["23220328fa14686d:37"]="用于在浓雾中给其他船只打信号。"}
D.ItemDescriptions[139546]={["4c58e66476e260ed:107"]="一件失败的试验品，企图从死者身上窃取能量，最终造成了大规模的扭曲和暴动。"}
D.ItemDescriptions[139547]={["e0cacfcd57846434:104"]="用一种早已被当今的生者遗忘的古代语言写成，可不知为何，这些单词仍然在你的舌尖翻滚，呼之欲出。"}
D.ItemDescriptions[139548]={["00989cb2717e9feb:116"]="在冰冠堡垒稳定的能量滋养下，这件粗糙但残忍的武器可以轻易地被加工成致命的利器。"}
D.ItemDescriptions[139549]={["aea54226263e3d55:58"]="一件渴望再次畅饮鲜血的黑暗武器，它的主人早已死去。"}
D.ItemDescriptions[139550]={["965338dcea8e8a27:148"]="钢铁卫士原本是德莱尼的坚固构造体，后来被燃烧军团转化成了毁灭的工具，早在攻占奥达奇的故乡时就被摧毁了。"}
D.ItemDescriptions[139551]={["30f8c429f05b0a5c:72"]="一种来自翡翠梦境的稀有鲜花，自从上古之战后就从艾泽拉斯消失了。"}
D.ItemDescriptions[139552]={["460ee80cf2526a6b:98"]="来自一位避世而居的荒野之神身上的羽毛。有了它，利爪德鲁伊就能学会一种前所未见的形态。"}
D.ItemDescriptions[139553]={["8135c60dfd6b4e9e:82"]="乌索尔为野熊施加的强大印记。可以在必要的时候强化它们，使它们成为荒野的守护者。"}
D.ItemDescriptions[139554]={["71a01fde9cb438e1:96"]="梦境中最古老的一棵树被梦魇腐蚀之前，它的一些魔法橡实被保留了下来。"}
D.ItemDescriptions[139555]={["bd3dab9298837103:167"]="制造大师级魔法科技长弓的详细图纸，使用强大的泰坦动力源作为核心。它们是怎么从米米尔隆的档案中流传出来的还有待推敲。"}
D.ItemDescriptions[139556]={["c1efd49ee3321675:110"]="制造优雅而强大的十字弩的详细图纸。由于所需的材料并不存在而逐渐被遗忘在历史的长河中。"}
D.ItemDescriptions[139557]={["bd2daa1f4e89b462:106"]="乌索克曾两次为荒野献出生命，但他为其他高贵的守护者留下了遗产，以便他们填补他离去后的空白。"}
D.ItemDescriptions[139558]={["f70a40e77e17ea1c:78"]="“牧羊人”考特·梅特卡夫也无法解开这根会咩咩叫的神秘法杖的秘密。"}
D.ItemDescriptions[139559]={["714eade91cb291f4:76"]="夜之子法术之刃的设计图纸，能够反射夜之子最珍视的星座图。"}
D.ItemDescriptions[139560]={["ea2c07b76715a478:83"]="一块冰冷的水晶，表面燃烧着毫无温度的冷焰。可以触摸，毫无融化的迹象。"}
D.ItemDescriptions[139561]={["bf2c7485f5bf847c:136"]="一种后劲十足的特殊酒类，据说是美猴王亲自酿造的。酒桶十分精致，除了用来装酒外，可能还有别的用处……"}
D.ItemDescriptions[139562]={["1de005076e788c08:79"]="不停旋转的魔法能量之泉，据说来自太古巨龙的胃袋。"}
D.ItemDescriptions[139563]={["f09d7ed5dc3c19d6:128"]="几乎没有人了解风暴之拳是怎么制造出来的，但它的力量似乎源于塞拉赞恩和奥拉基尔，一个出人意料的组合。"}
D.ItemDescriptions[139564]={["b79a979fa91ece4c:134"]="我们发誓将希望带回这个混乱的世界。搜寻暴政和邪恶扎根之地……以正义之锤打击邪恶。"}
D.ItemDescriptions[139565]={["85180a0ca28cfe4f:192"]="随着大主教凯里奥斯的倒下，守住神殿的希望也随之消失。燃烧军团赢了。现在，唯一能让他们觉得欣慰的就是那些逃走的人。但很快，这最后一点希望也会被燃烧军团浇灭。"}
D.ItemDescriptions[139566]={["950be745c395c84e:78"]="灰烬使者的残酷历史片段，许多人都不希望它重演。"}
D.ItemDescriptions[139567]={["48e9c02775b59182:75"]="从档案员散失的书籍中收集来的只言片语，预言了黑暗的时代即将到来。"}
D.ItemDescriptions[139568]={["57f6a3fde6de86aa:79"]="这根法杖静静地与瓦尔基拉的力量共鸣着。当你触碰到它时，这种声音就会消失。"}
D.ItemDescriptions[139569]={["c05abfec1f4f188b:49"]="双眼开合，肌肉翕张。这玩意儿还是活的。"}
D.ItemDescriptions[139570]={["5c79e8a38bf32cdc:172"]="早已死去的刺客“碎骨者”的秘密。据说曾经有一个死在她手下的人死而复生，向她复仇。从此之后，她就养成了打碎受害者腿骨的习惯。"}
D.ItemDescriptions[139571]={["2fbeb5421ae96083:129"]="赞达拉暗影猎手世代相传的文稿，详细记载了他们用来杀敌的一些稀有武器以及毒药。"}
D.ItemDescriptions[139572]={["5f8299dd674d444a:191"]="早已失传的巨魔文稿，集中讲述了历代领袖的兴衰史。其中的大量篇幅都集中在一个名叫阿泰纳萨的巨魔以及他用来巩固自身统治的一只魔爪上。"}
D.ItemDescriptions[139573]={["9975a91a5c8dfa2d:156"]="虽然有着精雕细琢的外表，但这把野蛮的钉锤在不自觉地向原始之神西瓦尔拉致敬的过程中夺取了许多生命。很久之前，持有它的大祭司将它失落在了海中。"}
D.ItemDescriptions[139574]={["d7050091a425e1bc:142"]="在波涛下潜行的上层精灵已经与过去完全不同。他们已经和深海融为一体，并成为海底更黑暗的某种存在的仆从。"}
D.ItemDescriptions[139575]={["ad6f8ae25accec85:97"]="从强大勇士的颅骨中榨出的精华，能为那些愿意付出黑暗代价的人提供强大的力量。"}
D.ItemDescriptions[139576]={["a3ae4403a898f14e:171"]="这一时期最突出的颅相学家当中就包括萨奇尔和阿克蒙德。而萨奇尔由于拥有巫师始祖的颅骨而名声在外，他也因此备受崇敬。"}
D.ItemDescriptions[139577]={["7234646573321f12:78"]="深红色的宝石中燃烧着漆黑的饥渴之火，当你靠近时会不断拍打边界。"}
D.ItemDescriptions[139578]={["549f046fc19d13dc:85"]="由苍穹要塞的锻造大师海尔加手工打造，这把战斧足以超越艾泽拉斯的一切武器。"}
D.ItemDescriptions[139579]={["d063408a70fc95c5:121"]="两把装饰有巨龙头骨的可怕战斧，以维库魔法符文木为柄。以任何一个战士的眼光来看，都称得上是令人印象深刻的武器。"}
D.ItemDescriptions[139580]={["5c3bd8a5979dcb20:154"]="奈萨里奥的黑色熔火之血从他的背脊中喷涌出来，在他昔日的巢穴中闷烧了无数年，等待着与主人的失落鳞片重逢。"}
D.ItemDescriptions[139583]={["f3f8e5b291411cd9:48"]="石头上刻着难以辨认的符号。"}
D.ItemDescriptions[139595]={["02e143bd3a069530:34"]="在这一万年中，时尚是不断进化的。"}
D.ItemDescriptions[139613]={["593289b50ad8f67a:93"]="通过代代相传，这些法杖的持有者们了解至高岭上下数百年的历史。"}
D.ItemDescriptions[139617]={["e10632ad16ed833c:52"]="镣铐束缚之物留下了印记。"}
D.ItemDescriptions[139618]={["b87b9d693368cd6c:32"]="里面含有浓缩的法力。"}
D.ItemDescriptions[139620]={["01a7b7c7e0f274c6:35"]="某些人可能会对它非常感兴趣。"}
D.ItemDescriptions[139624]={["696112b7667495b8:88"]="水晶中隐约弥漫着黑烟，但深处有微弱的尖叫声传来。"}
D.ItemDescriptions[139631]={["17a9b051e8344b74:90"]="瓶子上刻着一段文字：“愿光中之光永远照耀着我们辉煌的帝国。”"}
D.ItemDescriptions[139633]={["5f2f1a6738d3fb34:49"]="梦魇腐蚀的具现实体。"}
D.ItemDescriptions[139634]={["4000ce4a2d93a211:62"]=S[20241]}
D.ItemDescriptions[139635]={["36043cf0ebc18965:38"]="教你学会制作凡图斯符文：乌索克。"}
