D.ItemDescriptions[140197]={["61a62dbb5aea38a0:83"]="书页自动翻转，每一页上的文字不断明灭闪烁着。"}
D.ItemDescriptions[140198]={["62ba6227796405a6:38"]="最好别让它落入歹徒的手中。"}
D.ItemDescriptions[140199]={["34d3e50003159ce9:75"]="一块暗夜井的晶化碎片，极受夜之子统治阶层的觊觎。"}
D.ItemDescriptions[140200]={["d1453a3195201112:52"]="一件用暗夜碎片镶嵌起来的奢华装饰品。"}
D.ItemDescriptions[140205]={["10c3729e88705939:24"]="有着美丽的乳白色纹理。"}
D.ItemDescriptions[140220]={["99748c29d8c46e76:76"]="内含来自破碎群岛的布料。可以被拥有拾荒者附魔的玩家拾取。"}
D.ItemDescriptions[140221]={["2cfcbf0e9b7acd7f:75"]="内含来自破碎群岛的各种宝石。可以被拥有寻宝者附魔的玩家拾取。"}
D.ItemDescriptions[140222]={["48bbfa742f2a6a33:90"]="内含来自破碎群岛的各种草药和鱼类。可以被拥有收割者附魔的玩家拾取。"}
D.ItemDescriptions[140224]={["e1ae264ab8dc5c15:90"]="内含来自破碎群岛的各种肉类和皮革。可以被拥有屠戮者附魔的玩家拾取。"}
D.ItemDescriptions[140225]={["a0b6d7feb02ca9f7:88"]="内含来自破碎群岛的各种护甲和矿石。可以被拥有回收者附魔的玩家拾取。"}
D.ItemDescriptions[140226]={["6ff3deb19678b3e0:104"]="内含来自破碎群岛的各种药水和魔法材料。可以被拥有觅法者附魔的玩家拾取。"}
D.ItemDescriptions[140227]={["4b469087083873d6:92"]="可能含有来自破碎群岛的珍贵材料。可以被拥有猎血者附魔的玩家拾取。"}
D.ItemDescriptions[140228]={["24146c488b5a7fa3:31"]=S[13087]}
D.ItemDescriptions[140230]={["24146c488b5a7fa3:31"]=S[13087]}
D.ItemDescriptions[140231]={["b0cf2fcc2d62cce5:98"]="曾经有一名上层精灵女法师非常以自己的容貌为傲，所以她制作了一面镜子，让别人在镜子里看到她的脸。"}
D.ItemDescriptions[140232]={["24146c488b5a7fa3:31"]=S[13087]}
D.ItemDescriptions[140233]={["24146c488b5a7fa3:31"]=S[13087]}
D.ItemDescriptions[140237]={["3dc155af8968e3e6:58"]="艾德瑞斯在她的命名日那一天收到了这块灌注了强大力量的石头。"}
D.ItemDescriptions[140242]={["b13bd0f41dffa1d5:49"]="但愿我父亲留下的某件圣物能够救我们。"}
D.ItemDescriptions[140246]={["f76415f39bfde440:40"]="这颗雪梅被魔力酒浸泡过。"}
D.ItemDescriptions[140249]={["8af5d9499e5d4e8c:97"]=S[302]}
D.ItemDescriptions[140251]={["85673a61d98206e2:38"]="这个图腾仍然散发着强大的魔力。"}
D.ItemDescriptions[140255]={["47d63006b974dbc9:82"]="这枚代代相传的硬币上寄托了之前所有持有者的知识。"}
D.ItemDescriptions[140261]={["9d6d0e19bc8fb050:35"]=S[13094]}
D.ItemDescriptions[140265]={["28d394e6d7841dfb:65"]="这种广受好评的饮品口感丝滑，还带有榛子的香气。"}
D.ItemDescriptions[140266]={["4e0861fb3b2d8aac:93"]="这种引进自昆莱山的黑色烘焙咔啡滋味浓郁，加入新鲜牦牛奶味道更佳！"}
D.ItemDescriptions[140269]={["f63f53a45e4c0f89:101"]="这种甜美柔和的饮品加入了珍贵的香料，经过至高岭冰雪冷冻，是牛头人部族的最爱。"}
D.ItemDescriptions[140271]={["71ec45fe5a484a81:47"]="这种黑咖啡与蜜酒的混合饮料口感顺滑，后劲十足。"}
D.ItemDescriptions[140272]={["e3843dd3c70b3f04:75"]="这种香料茶从上古卡多雷时期风靡至今，散发着苹果和肉桂的香气。"}
D.ItemDescriptions[140273]={["3578aee35750c18e:29"]="以坚果和蜂蜜新鲜烘焙而成，"}
D.ItemDescriptions[140274]={["9d6d0e19bc8fb050:35"]=S[13094]}
D.ItemDescriptions[140277]={["85ebdd0fb7be51f6:27"]="这块石头上有一个力量印记。"}
D.ItemDescriptions[140278]={["9b8577d7b9584ad6:47"]="这封古怪的加密信件上有军情七处的印记。"}
D.ItemDescriptions[140285]={["8f12c80d370c7fc6:41"]="这把生锈的剑与它的最后一任主人长眠在了一起。"}
D.ItemDescriptions[140286]={["8113deccb800d44f:30"]="不只是一顿饭，更是一次美味之旅。"}
D.ItemDescriptions[140294]={["5bd1b2cda3f0d4c4:42"]="这件衣服上满是邪气污渍。"}
D.ItemDescriptions[140296]={["c06feb0c0ecb668f:18"]="由真正的胶质制成！"}
D.ItemDescriptions[140297]={["70ebcc64766e9007:34"]="天然原料，天然美味。"}
D.ItemDescriptions[140298]={["ad696c773297c6e2:32"]="气泡丰富，让你远离头疼烦恼！"}
D.ItemDescriptions[140300]={["0bc01e18597b477d:15"]="本地原产。"}
D.ItemDescriptions[140301]={["1f434f62e9ce54ab:26"]="无关魔法，永远新鲜。"}
D.ItemDescriptions[140302]={["830d2f7e9807a7f1:37"]="奶香浓郁的去壳海鲜汤。"}
D.ItemDescriptions[140308]={["f77a7e4da6b6fd08:43"]="你救出的瓦拉加尔会加入你的队伍。"}
D.ItemDescriptions[140309]={["6d8599dfb60d5d96:78"]="光线在其中反射了数千次，制造出了宝石在发光的假象。"}
D.ItemDescriptions[140315]={["255f1acec4e5d4f5:32"]="带着救赎的希望精心培养出来的。"}
D.ItemDescriptions[140316]={["9d6d0e19bc8fb050:35"]=S[13094]}
D.ItemDescriptions[140317]={["1d730aad51a10e34:34"]="看上去似乎是某种重要组件。"}
D.ItemDescriptions[140318]={["ee590aa2e3ec4d35:40"]="它们与更大的能量柱同步脉动着。"}
D.ItemDescriptions[140320]={["9d6d0e19bc8fb050:35"]=S[13094]}
D.ItemDescriptions[140323]={["9d6d0e19bc8fb050:35"]=S[13094]}
D.ItemDescriptions[140326]={["fdf9b8f01de59315:23"]="内含一股古代能量。"}
D.ItemDescriptions[140327]={["50d2d906568916b3:51"]="他掌握的所有魔法的研究和草稿。"}
D.ItemDescriptions[140328]={["bd14b619b785a170:28"]="不断震荡，散发着强大的能量。"}
D.ItemDescriptions[140329]={["f30cf7dd3e18b010:38"]="能够存储大量能量。"}
D.ItemDescriptions[140337]={["c0686017ed4e7546:79"]="大量的盐分使它在艾泽拉斯的乡间小镇极受欢迎。"}
D.ItemDescriptions[140338]={["8604a23be5e3e7dc:72"]="这种馅饼是来自西部荒野的家常菜。为了保证新鲜，馅饼外面包裹了一层法力膜。"}
D.ItemDescriptions[140339]={["38f892ec883bfdf3:59"]="商人声称这是著名的奥特兰克宫廷最喜爱的食物。"}
D.ItemDescriptions[140340]={["fcaf22cf9f54dfe6:56"]="他们成功地在不使用魔法的情况下给它注入了气泡。"}
D.ItemDescriptions[140341]={["70e135c6d723b84b:27"]="来自遥远的北方水域。"}
D.ItemDescriptions[140342]={["e3b50297c301c984:47"]="这头巨兽可能来自另一个世界！"}
D.ItemDescriptions[140343]={["804ea71ec901e7cd:57"]="来自一片被迷雾笼罩的土地，适合最资深的老饕品尝的美食。"}
D.ItemDescriptions[140344]={["d2933243d6f79c74:98"]="把它卖给我的商人说，这是大名鼎鼎的黑铁酒吧最受欢迎的菜，是一种非常罕见的美味。"}
D.ItemDescriptions[140348]={["24146c488b5a7fa3:31"]=S[13087]}
D.ItemDescriptions[140350]={["24146c488b5a7fa3:31"]=S[13087]}
D.ItemDescriptions[140353]={["24146c488b5a7fa3:31"]=S[13087]}
D.ItemDescriptions[140354]={["24146c488b5a7fa3:31"]=S[13087]}
D.ItemDescriptions[140355]={["add7ae445a629355:33"]="达拉然苹果树的馈赠。"}
D.ItemDescriptions[140356]={["0c697f617f5d4162:52"]="哪怕是以恶魔的标准，这字迹也太难辨认了。"}
D.ItemDescriptions[140357]={["12f203a063387fad:25"]="总是热乎乎的。"}
D.ItemDescriptions[140358]={["25d3f71fac3762bc:43"]="它似乎一直都保存得很好，是在最近才损坏的。"}
D.ItemDescriptions[140359]={["cba171f85cc13c7f:57"]="佐斯之眼是躲不开的，需要用其他方法去处理。"}
D.ItemDescriptions[140360]={["58b0410f4291f27a:56"]="不算很锋利，但很坚固，足以刺入石头。"}
D.ItemDescriptions[140361]={["b5ffc3eb74dfe5ca:52"]="里面已经没有魔力了，但它的嗡鸣声很好听。"}
D.ItemDescriptions[140362]={["64ff0b49dcc0f780:68"]="虽然这种粉尘本身不含任何能量，但却有一种超凡脱俗的感觉。"}
D.ItemDescriptions[140363]={["3413f2dc5ab91f0b:40"]="把它放进口袋里其实不是什么好主意。"}
D.ItemDescriptions[140364]={["bbd7fafea04e44ff:67"]="仍然散发着能量，肯定是它飞越冰冠堡垒时断裂的。"}
D.ItemDescriptions[140365]={["ea9e8c4291c3b7dd:79"]="这种花曾经开遍整个洛丹伦。某个细心的人在书里夹了几片花瓣。"}
D.ItemDescriptions[140366]={["66cf2783f1538e40:69"]="一本圣光赞美诗合集，由血色十字军收集并整理。"}
D.ItemDescriptions[140367]={["190a928335b990f0:77"]="在音乐爱好者看来，这似乎是“罗密欧与朱丽叶”的伴奏乐谱。"}
D.ItemDescriptions[140368]={["6621831eae0008f5:19"]="死亡带走了一切。"}
D.ItemDescriptions[140369]={["07af8b3024084f71:87"]="这似乎是某种提神薄荷酒的配方。也可能是某种能够毁灭艾泽拉斯所有生灵的瘟疫配方。或许两者都是。"}
D.ItemDescriptions[140370]={["3aa3e3a6c9bb4683:27"]="里面有一只小小的昆虫。"}
D.ItemDescriptions[140371]={["7c29432d36206e10:115"]="信的开头是这么写的：“亲爱的尼娅米，我万分遗憾地通知你，你的儿子也在被兽人绑架的人质中间，只怕是凶多吉少。”"}
D.ItemDescriptions[140373]={["f01e821ef9d9af75:65"]="似乎是从一双曾经非常漂亮的靴子上掉下来的。"}
D.ItemDescriptions[140374]={["b77da07a9c1d481b:54"]="没人知道它原本的主人是谁，但它很长很可怕。"}
D.ItemDescriptions[140375]={["022d6df5c18e3a1a:42"]="上一个主人已经不再需要它们了。"}
D.ItemDescriptions[140376]={["2ed581958050670c:46"]="根据在马顿生存的特性进行了调整。"}
D.ItemDescriptions[140377]={["66e727446c1373af:51"]="它曾属于一位卡拉波牧师，但早已风光不再了。"}
D.ItemDescriptions[140378]={["c0e2840e98a68d5f:33"]="让你能够招募伊利达雷精锐。"}
D.ItemDescriptions[140379]={["1a38803b221fda96:43"]="只有强大的力量才能折断这把剑。"}
D.ItemDescriptions[140380]={["1cc5eb31b9fdd772:41"]="这根羽毛为鲜艳的蓝紫色。"}
D.ItemDescriptions[140381]={["60657bb79454e44e:57"]="这个指环散发着古老的力量，紧紧套在手指上。"}
D.ItemDescriptions[140382]={["36478c6cef0d43fb:34"]="对于一个成年邪能图腾成员来说太小了。"}
D.ItemDescriptions[140383]={["d27058d117134f62:18"]="被咬了几口。"}
D.ItemDescriptions[140384]={["f27450131bbc6b62:30"]="赐予女王的顾问。"}
D.ItemDescriptions[140385]={["cc9e1a60ee12955b:67"]="反复折叠了太多次，上面的字几乎都看不清了。"}
D.ItemDescriptions[140387]={["a567a0f79778ad84:48"]="就连鬼母都知道雅致的小饰品有多可贵。"}
D.ItemDescriptions[140388]={["f2920cbcf3ab28e1:49"]="闪闪发亮。欧瑞斯将他的宝贝石头藏得很好。"}
D.ItemDescriptions[140389]={["87a3d9594b5fac58:59"]="这块石头会时不时闪过一丝火光，仿佛里面还在燃烧。"}
D.ItemDescriptions[140390]={["5a0ec1cb8088fdc4:93"]=S[18221]}
D.ItemDescriptions[140391]={["46da6d8ce1843a4b:46"]="被随身携带了数千年，摩挲得闪闪发光。"}
D.ItemDescriptions[140392]={["0e2ff413a4993ea0:15"]="从来没有安装过。"}
D.ItemDescriptions[140393]={["33ebf38eed298a73:16"]="由于经常使用，已经很旧了。"}
D.ItemDescriptions[140396]={["d02f0cdf03c8967c:28"]="给胜利者的魔法硬币。"}
D.ItemDescriptions[140399]={["5a0ec1cb8088fdc4:93"]=S[18221]}
D.ItemDescriptions[140400]={["6ea0ed7ff2af17b8:31"]="所有的花瓣都完好无损。"}
D.ItemDescriptions[140401]={["5a0ec1cb8088fdc4:93"]=S[18221]}
D.ItemDescriptions[140402]={["27ef1605ece18dc8:43"]="钳胫以为自己已经做好准备，能够保护自己的蛋了。"}
D.ItemDescriptions[140407]={["24146c488b5a7fa3:31"]=S[13087]}
D.ItemDescriptions[140408]={["24146c488b5a7fa3:31"]=S[13087]}
D.ItemDescriptions[140409]={["ae2965e5bd1f092e:87"]="你很明智地拿了这本书。这么多年来，它已经吸收了魔法回廊中的大量知识。"}
D.ItemDescriptions[140410]={["1c610a368b4f42fd:69"]="看来你真的出名了。阿鲁因把这枚魔法硬币给了你，以示支持。"}
D.ItemDescriptions[140414]={["773dde9063bec2b7:36"]=S[18090]}
D.ItemDescriptions[140418]={["665e256464b5e221:34"]=S[8570]}
D.ItemDescriptions[140419]={["e1ca90bac75fba45:38"]=S[10145]}
D.ItemDescriptions[140421]={["f661a9611b68c764:121"]="有传言说这个雕像是斯特拉瑞斯公爵的珍藏。看来是某个早就知道他回不了家的人把它偷出来的。"}
D.ItemDescriptions[140422]={["56bf5aba9dd9c9ad:61"]="莉莉丝的私人藏品。闪烁着艾露恩的祝福。"}
D.ItemDescriptions[140444]={["a4c7c65397e92b3c:41"]="精华中滴下的一滴梦境之泪。"}
D.ItemDescriptions[140452]={["ec2537e1a29bde26:52"]=S[371]}
D.ItemDescriptions[140453]={["f2c9929e56f5a697:85"]=S[373]}
D.ItemDescriptions[140454]={["bfa07a31afb11ee8:87"]=S[372]}
D.ItemDescriptions[140455]={["ec2537e1a29bde26:52"]=S[371]}
D.ItemDescriptions[140456]={["f2c9929e56f5a697:85"]=S[373]}
D.ItemDescriptions[140457]={["bfa07a31afb11ee8:87"]=S[372]}
D.ItemDescriptions[140458]={["9125f774c541405d:36"]="有着如同干涸的血迹一样的颜色，而且很扎手。"}
D.ItemDescriptions[140459]={["a48a19c1d1e4dc8e:49"]="来自神殿某位女祭司的谢礼。"}
D.ItemDescriptions[140460]={["9f8a040d450f0bd8:61"]="它们非常锋利，足以切开海巨人的血肉，而且显然成功过。"}
D.ItemDescriptions[140461]={["337d77ff5e4cbd76:93"]="许多年前，鹰身人把它当宝贝一样拖回了自己的巢穴。上面的铭文早就被磨掉了。"}
D.ItemDescriptions[140462]={["5a98608a25f71db9:43"]="凶残尖锐，只适合维库人尺寸的靴子。"}
D.ItemDescriptions[140463]={["f4b7b765bb722eb8:46"]="材料的质量并不如想象中的那么好。"}
D.ItemDescriptions[140464]={["86eb045550b981be:42"]="制作粗糙，可能是某个孩子的作品。"}
D.ItemDescriptions[140465]={["4dbe19dd8b74d24e:52"]="哪怕是最严苛的工艺都无法让它软化。"}
D.ItemDescriptions[140466]={["e3acc2d4de5c9f6b:60"]="有人把它扔进了下水道，化学药剂对其造成了严重的损伤。"}
D.ItemDescriptions[140467]={["a81858c85abe9341:77"]="邪能魔力融入了这个死掉的可怜生物的甲壳里。"}
D.ItemDescriptions[140468]={["1670873224bea1ed:42"]="早就碎了，但这颗蛋原本很巨大。"}
D.ItemDescriptions[140469]={["7a2e13c766aff770:38"]="有人试图反击。关键词：试图。"}
D.ItemDescriptions[140470]={["ea9e05a53fd4c3d0:43"]="源自诅咒降临、隔离墙筑起之前的时代。"}
D.ItemDescriptions[140471]={["c8d8e76ff963e55e:72"]="曾属于纳迦皇室的财产，被发现于临近阿苏纳的海底。"}
D.ItemDescriptions[140472]={["93fe114a2360c98d:61"]="这种语言极其古老，只有最年长的精灵才有可能看得懂。"}
D.ItemDescriptions[140473]={["0cd3209af0b4bf87:27"]="不算精致巧妙的武器。"}
D.ItemDescriptions[140474]={["ca58be76042ba9bf:49"]="曾是一件精美的艺术品，但已经碎了几十年了。"}
D.ItemDescriptions[140475]={["aca59a3bb666ef80:50"]="这种草在苏拉玛各地的废墟都有生长。"}
D.ItemDescriptions[140476]={["ecdb27cbd4e7ace2:57"]="它在兽人攻城时坏掉了，已经无法运转。"}
D.ItemDescriptions[140477]={["74d1cd6496c516f7:52"]="并非所有人都通过了大法师卡德加在德拉诺设下的试炼。"}
D.ItemDescriptions[140478]={["b4081d9847f4b31d:20"]="生命本身就是最神奇的魔法。"}
D.ItemDescriptions[140479]={["a5a71d85d0e875fc:47"]="它反复播放着同一段听起来很恼怒的信息。"}
D.ItemDescriptions[140480]={["c1706f077710d28e:64"]="曾经为某个夜之子构造体提供过能量。而现在，它只是一个漂亮的镇纸。"}
D.ItemDescriptions[140481]={["d351a0ed01140264:46"]="走时精准——但完全属于另一个世界。"}
D.ItemDescriptions[140482]={["c7c7c03bb41f2e34:74"]="巨大、尖锐，而且不含任何魔力，平凡得叫人失望。"}
D.ItemDescriptions[140483]={["659224a831b5ffbf:34"]="曾是一个小青龙雕像的一部分。"}
D.ItemDescriptions[140484]={["54ebb74dda4f3896:34"]="仍然散发着某种酒味儿。"}
D.ItemDescriptions[140485]={["0cbe83c0cca6015b:16"]="有一点开裂了。"}
D.ItemDescriptions[140486]={["3f5b012f51ad8cb6:35"]="一片柔软、闪亮的腹部鳞片。"}
