D.ItemDescriptions[141216]={["3398f81464ba5ae9:43"]="教你学会召唤一头可供骑乘的林地污染者。"}
D.ItemDescriptions[141217]={["78282fdc5942d741:85"]=S[13093]}
D.ItemDescriptions[141294]={["3908056e5cfc9b29:66"]="授予出发参加破碎海滩之战的部落勇士。"}
D.ItemDescriptions[141295]={["117f5e7b4273d128:12"]="闻上去很新鲜。"}
D.ItemDescriptions[141302]={["a31c08994e8be55a:92"]="深爱着女王的雷杉德尔冰封的灵魂，她牺牲了自己，成为复仇的化身。"}
D.ItemDescriptions[141303]={["a3e3087608bfcacb:52"]=S[20159]}
D.ItemDescriptions[141304]={["a3e3087608bfcacb:52"]=S[20159]}
D.ItemDescriptions[141305]={["a3e3087608bfcacb:52"]=S[20159]}
D.ItemDescriptions[141307]={["25b69cd782503052:50"]="这颗巨大的、浅绿色的心脏还在你手中跳动。"}
D.ItemDescriptions[141308]={["f6b4ec4d70f06fb4:46"]="一头强大恶魔腐烂纠结的内脏。"}
D.ItemDescriptions[141309]={["e72fe0751007c322:23"]="科达娜在注视着你……"}
D.ItemDescriptions[141310]={["f84ab70a8fd862bf:58"]="法兰纳尔的居民经常佩戴的古代能量护符。"}
D.ItemDescriptions[141311]={["5cad0afced70b151:58"]="教你学会一次性对大量魔石矿石进行选矿。"}
D.ItemDescriptions[141312]={["1cc3735368ad5c3a:55"]="教你学会一次性对大量邪能页岩进行选矿。"}
D.ItemDescriptions[141313]={["a6fb18f280f5d525:69"]="前一棵树爆炸时，许多生物都受到了它的魔力影响。"}
D.ItemDescriptions[141314]={["c6413b990e6a7d66:82"]="这个容器是树疗者在种下第一棵魔力树时所使用的众多仪式用品之一。"}
D.ItemDescriptions[141316]={["10c4c9357d7ce790:29"]="教你学会召唤滑滑。"}
D.ItemDescriptions[141317]={["dee0d10035d55475:23"]="这颗宝石散发着魔力。"}
D.ItemDescriptions[141321]={["01cdc27776098a62:83"]="据信，破坏魔比燃烧军团的其他大部分成员还要狂热三倍。"}
D.ItemDescriptions[141323]={["b71f8d4d95dfdd92:15"]="你会得到什么呢？"}
D.ItemDescriptions[141324]={["dc498033da6d9076:76"]=S[20119]}
D.ItemDescriptions[141325]={["dc498033da6d9076:76"]=S[20119]}
D.ItemDescriptions[141326]={["dc498033da6d9076:76"]=S[20119]}
D.ItemDescriptions[141327]={["43f74a1f5220be42:36"]="看上去很完整且情况良好。"}
D.ItemDescriptions[141328]={["311c153966b3a3c8:53"]="这叠笔记详细介绍了一种强大的结界仪式。"}
D.ItemDescriptions[141329]={["8e3de4c78fc26034:34"]="这块水晶看来经过了精心的加工。"}
D.ItemDescriptions[141330]={["1187ba9ce4a01d83:47"]="这块发光的石头闪耀着神奇的光辉。"}
D.ItemDescriptions[141331]={["1cc21c7e110b0797:61"]="它的效果是可以逆转的。瑟玛普拉格可能已经在制作解药了……"}
D.ItemDescriptions[141332]={["763c2ddfb8b4bcbc:136"]="共分十二卷，详细介绍了教团及其成员的一切信息。档案员伊克弗吉似乎很想找回这套书。"}
D.ItemDescriptions[141333]={["52e9e77e6832eae9:76"]=S[5486]}
D.ItemDescriptions[141334]={["8accf760821cac2d:82"]="擅长清除各种不小心染上的污渍。同样擅长将你当做所谓的“污渍”而抹杀。"}
D.ItemDescriptions[141335]={["2860985adb98fc95:81"]="有关古代武器的详尽笔记，由肯瑞托的老菲尔麦夫所撰写，被粗心大意的信使遗失。"}
D.ItemDescriptions[141348]={["68e6c54d324990e4:43"]="教你学会召唤神奇的智慧之球。"}
D.ItemDescriptions[141349]={["ced8ded0a51fcddf:65"]="通过仔细检查，你发现嗡鸣声其实是数百人的低语声。"}
D.ItemDescriptions[141351]={["38149bbc03b4b4e1:31"]=S[20123]}
D.ItemDescriptions[141352]={["9d6d0e19bc8fb050:35"]=S[13094]}
D.ItemDescriptions[141353]={["111ef04c62982493:34"]="小玩意儿也能造成大爆炸！"}
D.ItemDescriptions[141383]={["462c1fc9ff80867e:44"]="来自艾露恩的祝福，为你照亮最黑暗的时刻。"}
D.ItemDescriptions[141385]={["c53f227680a7d271:41"]="哪怕是潮汐之石的一小块碎片也含有庞大的力量。"}
D.ItemDescriptions[141389]={["ac9f2a9026ed2771:53"]="作为星眼家族的家徽，这枚宝石已经传承了数千年。"}
D.ItemDescriptions[141390]={["540436217143ee78:84"]="能够汇集萨维斯的梦魇能量，以腐蚀任何生物，无论大小。"}
D.ItemDescriptions[141391]={["ce85942561164a0e:43"]="哪怕在最黑暗的年代，勇气也具有力量。"}
D.ItemDescriptions[141392]={["a3a9b1c80c48f85f:63"]="海拉赐下的灵魂牢笼能够压制一切生物的灵魂。"}
D.ItemDescriptions[141393]={["e880f5f60e525669:32"]="强有力地提醒着你要坚持下去。"}
D.ItemDescriptions[141395]={["39bf487ab1b33ad3:32"]="刻在一块带有魔力的魔石上。"}
D.ItemDescriptions[141396]={["9cbc0a0f984f83f2:33"]="抚育生命需要巨大的力量。"}
D.ItemDescriptions[141400]={["9df217a1aab0a8a8:29"]="卓格巴尔酋长的徽记。"}
D.ItemDescriptions[141404]={["3b517701aa64431c:39"]="这枚徽记上烙印着阿克萨拉克斯的名字。"}
D.ItemDescriptions[141409]={["e8b3f6eaba381db1:37"]="珠宝上刻着首字母缩写“C.T.”。"}
D.ItemDescriptions[141446]={["52e9e77e6832eae9:76"]=S[5486]}
D.ItemDescriptions[141447]={["b4a100b21d39a1d3:43"]="教会你制作宁神书卷。"}
D.ItemDescriptions[141486]={["a86d031d65f0e1d2:40"]="镶嵌着数百块细碎的邪能绿翡翠。"}
D.ItemDescriptions[141530]={["b68474600bf969c7:30"]="教你学会召唤雪牙。"}
D.ItemDescriptions[141532]={["9d6d0e19bc8fb050:35"]=S[13094]}
D.ItemDescriptions[141539]={["97ff310db7cdd7e0:66"]="传说中经常提到，在古代精灵帝国时期，存在着能够自动行驶的船只。"}
D.ItemDescriptions[141572]={["bfa0e3a5b89a8032:27"]="每走一步都带有永恒的回响。"}
D.ItemDescriptions[141575]={["9923e3dac69ee641:94"]="只要有光心夫人在他身边，格洛格就能抵挡任何风暴——就连大分裂也无法将他们分开。"}
D.ItemDescriptions[141577]={["0c8861c9a2921106:94"]="克雷泰带领他的部族取得了无数胜利，他无穷的力量则来自女王伊莎瑞的智慧。"}
D.ItemDescriptions[141579]={["445e3f1a1cc31701:37"]="里面有一层薄薄的灰。"}
D.ItemDescriptions[141580]={["fec0bb226b83eba1:53"]="在奥布达克的大军中，这种指环象征着军官们的军衔。"}
D.ItemDescriptions[141585]={["c7abfb304ef21601:70"]="力量强大，扇出的轻风足以让最强大的生物冷静下来。"}
D.ItemDescriptions[141587]={["9527e0c778af7820:109"]="伊莎瑞与克雷泰领主共同统治着他们的部族，哪怕是在战争时期，她的决断依然带领着部族走向繁荣。"}
D.ItemDescriptions[141588]={["0995bdebb46a6b32:86"]="贾米尔对圣光的坚定信仰吸引了格洛格，并在大分裂中保护了他们的安全。"}
D.ItemDescriptions[141589]={["1735eac0ec9b9499:27"]="用纯净的星光编织而成。"}
D.ItemDescriptions[141590]={["48937db5aa3b2428:44"]="玛塔尔从怪诞而拙劣的旅程中带回的纪念品。"}
D.ItemDescriptions[141591]={["c86b8935f1aa3db8:59"]="教你学会更加高效的制作宁神圣典。"}
D.ItemDescriptions[141592]={["2fd14e2158835356:64"]="教你学会更加高效的制作宁神圣典。"}
D.ItemDescriptions[141618]={["1673468878c03d27:19"]="死亡会来带新生。"}
D.ItemDescriptions[141638]={["8923a047993b8880:48"]="法兰纳尔的奥术师们使用的强大古代工具。"}
D.ItemDescriptions[141639]={["e811981d188865d6:35"]="稀有的法兰纳尔神器，极其强大。"}
D.ItemDescriptions[141642]={["92ca4d291ac22226:40"]="教你学会制作清心书卷。"}
D.ItemDescriptions[141643]={["edf991c7d96349ce:41"]="教你学会制作清心圣典。"}
D.ItemDescriptions[141644]={["6f027fa3288d3954:45"]="进行此研究可以让你学会新的雕文。"}
D.ItemDescriptions[141649]={["6f0f24d63a796cf5:21"]="这不是玩具……"}
D.ItemDescriptions[141667]={["9e0251592fc8fac2:44"]="塞兰提娅守护了沙尔艾兰数千年。"}
D.ItemDescriptions[141668]={["85a1f02e4e03a0f1:66"]="凯尔丹纳斯使用这本强大的秘典来保存笔记并协助他研究。"}
D.ItemDescriptions[141669]={["1841482eafe9349d:87"]="虽然里面的知识没有达到凯托斯预期的效果，但这本书仍然具有强大的力量。"}
D.ItemDescriptions[141672]={["593312b05f4f9ae9:128"]="镶嵌在多米蒂勒头盔上的宝石，表面下有着盘旋的精华，仿佛是由缓缓流动的暗夜井之水构成的。"}
D.ItemDescriptions[141673]={["d5ba046e6b9aa2a9:79"]="随着拉塔娜的动作，一支包裹着强大力量的箭矢终于离开了她的箭袋。"}
D.ItemDescriptions[141674]={["b93f9dc3b29c7a70:60"]="石板上脉动的魔法之血等待着被释放的那一刻。"}
D.ItemDescriptions[141675]={["886e95d999c827ea:62"]="在地表非常少见，含有的魔力令它们散发出浅蓝色的光芒。"}
D.ItemDescriptions[141677]={["e83f8f658d22488e:66"]="集市商人秘密铸造的钥匙，代表着他们的感激。"}
D.ItemDescriptions[141678]={["924acb414d28204a:142"]="这本看似简单的书中含有完善魔力酒的秘密，在暗夜井的运转核心吸收了庞大的残余能量。"}
D.ItemDescriptions[141679]={["b092dbda48439a17:69"]="晶化的蓝色树脂里神奇地包裹着一只昆虫。"}
D.ItemDescriptions[141680]={["58778ff7dab1339c:49"]="阿斯塔瓦家族代代相传的强大圣物。"}
D.ItemDescriptions[141681]={["eacbb17d0687b558:22"]="由初代守护者所制。"}
D.ItemDescriptions[141683]={["8627b09d973b8468:24"]="上面的回路在时刻燃烧着。"}
D.ItemDescriptions[141700]={["82d214a9581380c4:30"]="学习如何烹饪银鲭鱼。"}
D.ItemDescriptions[141705]={["b081aa7a524b2e21:70"]="你只能看懂其中对苏拉玛贵族政治的批判那部分。"}
D.ItemDescriptions[141713]={["24146c488b5a7fa3:31"]=S[13087]}
D.ItemDescriptions[141714]={["9d6d0e19bc8fb050:35"]=S[13094]}
D.ItemDescriptions[141843]={["10763ed41aea27fd:55"]="教你学会召唤血仇角斗士的风暴巨龙。"}
D.ItemDescriptions[141844]={["fd3540141ea21f7b:53"]="教你学会召唤无畏角斗士的风暴巨龙。"}
D.ItemDescriptions[141845]={["f93cbd7a96ca5ef9:50"]="教你学会召唤残虐角斗士的风暴巨龙。"}
D.ItemDescriptions[141846]={["25d7f70eadf56dbb:54"]="教你学会召唤凶猛角斗士的风暴巨龙。"}
D.ItemDescriptions[141847]={["5a4f934d6af50632:51"]="教你学会召唤暴烈角斗士的风暴巨龙。"}
D.ItemDescriptions[141848]={["b2537e5957764404:53"]="教你学会召唤专横角斗士的风暴巨龙。"}
D.ItemDescriptions[141849]={["1fa71666e4ada63b:44"]="教你学会制作里弗斯模块：华丽模式。"}
D.ItemDescriptions[141850]={["11ccc131a05783e2:45"]="教你学会制作骑乘大角鹿缰绳。"}
D.ItemDescriptions[141863]={["e129064a3d8a329f:47"]="其实并不比成为“主人”更加宝贵。"}
D.ItemDescriptions[141865]={["193b8e264ae4bb97:46"]="将刚召唤来的恶魔送回扭曲虚空。"}
D.ItemDescriptions[141866]={["3d49508ce286ab7d:45"]="幸好，第二和第六只手套还完好无损。"}
D.ItemDescriptions[141867]={["5a5a74d1a9a66cfc:80"]="这条裤子折叠地非常整齐，以备在正式场合穿着。不过那一天恐怕永远都不会到来了。"}
D.ItemDescriptions[141876]={["025b340b4b630522:22"]="这套系统非常高效。"}
D.ItemDescriptions[141878]={["ed121060262204ed:69"]="瓶中旋转着的能量可以保护携带者不受魔法偷袭。"}
D.ItemDescriptions[141879]={["fd7bf23eff1d9b55:49"]="看来鱼人也有类似的风俗。"}
