D.ItemDescriptions[142245]={["98193e941d973027:34"]="这把武器中蕴藏着强大的能量。"}
D.ItemDescriptions[142246]={["ecc53536f9498b57:60"]="这块怀表已经支离破碎了。里面还有一张皱巴巴的纸条。"}
D.ItemDescriptions[142248]={["21ebfc5c07657bbf:19"]="气味十分特别。"}
D.ItemDescriptions[142249]={["6b03702414edb63f:12"]="一滴美酒。"}
D.ItemDescriptions[142250]={["40a8f1f6b76c1d79:102"]=S[8723]}
D.ItemDescriptions[142251]={["c00b863c555df3ad:78"]="虽然是匆匆写成的，但莉莉丝的笔迹和文法都十分优美。"}
D.ItemDescriptions[142258]={["79b23f6e77b6a2eb:49"]="由战术大师拉文凯斯领主亲自撰写。"}
D.ItemDescriptions[142260]={["b72cb7736b45f456:37"]="对夜之子的能量尤为有效。"}
D.ItemDescriptions[142261]={["255f1acec4e5d4f5:32"]="带着救赎的希望精心培养出来的。"}
