D.ItemDescriptions[142265]={["c21bcaadcde66c7e:17"]="或许没什么坏处。"}
D.ItemDescriptions[142266]={["2ae9b1c3ad91b200:25"]="机械宠物都爱小齿轮。"}
D.ItemDescriptions[142267]={["3052c78663853bd3:30"]="湿鳞主母的心脏"}
D.ItemDescriptions[142268]={["ad8cb751dec65650:58"]="来自巫师加鲁格，这个核心能让岩石获得生命。"}
D.ItemDescriptions[142269]={["ca67bff94ffc2ea0:41"]="元素守护者特拉古尔的心脏。"}
D.ItemDescriptions[142270]={["bbcdb09930766f24:26"]="鳞翼女王的心脏。"}
