D.ItemDescriptions[142311]={["5098edb966ff9018:81"]="交给搏击竞技场的布鲁诺·防火棉，为所有人购买2分钟的免费饮料时间！"}
D.ItemDescriptions[142312]={["34750342a9129e61:18"]="工艺粗糙但很实用。"}
D.ItemDescriptions[142313]={["b605b6b18d0a1fa2:87"]="交给搏击竞技场的柯吉尔·电扳，为所有人购买10分钟的免费飞艇旅程！"}
