D.ItemDescriptions[142315]={["488a9ea0a4408de5:35"]="海拉的仆从灵魂为其提供了能量。"}
D.ItemDescriptions[142317]={["d611f8a165ac4f02:96"]="交给搏击竞技场的艾斯米·日影，在搏击俱乐部里购置一块墓地，持续30分钟。"}
