D.ItemDescriptions[142327]={["12e78d4ab98a6759:41"]="这些水晶碎片摸上去是热的。"}
D.ItemDescriptions[142328]={["a400e7d28a1a41b3:70"]="碎片内传出充满恨意的尖叫声，令你的掌心发烫。"}
