D.ItemDescriptions[142340]={["c118c8152029637a:35"]="卡拉赞遭到入侵的铁证。"}
D.ItemDescriptions[142341]={["0aa6c3f986335a8a:31"]="艾泽拉斯最浪漫的航程。"}
D.ItemDescriptions[142342]={["df4f25b107cbeee4:55"]="里面的东西似乎被某种强大的法术增强过了。"}
D.ItemDescriptions[142345]={["0dd320005ebe15bd:36"]="从火腹食人魔的斧子上断裂的斧刃。"}
D.ItemDescriptions[142346]={["20222239c02791b2:35"]="教你学会制作冷木斧。"}
