D.ItemDescriptions[142362]={["2c51cf6fd8202856:28"]="表面刻满了发光的符文。"}
D.ItemDescriptions[142363]={["6d2ae1dee0d0036f:24"]="狩猎成功的象征。"}
D.ItemDescriptions[142365]={["5ce11c5e4e4f6e7b:52"]="没有拉风护肩的外观不是好外观。"}
D.ItemDescriptions[142366]={["3b604eee6c9159e9:27"]="它大概宁肯饿着。"}
D.ItemDescriptions[142367]={["4d0b6f0a17911f6d:44"]="来自艾泽拉斯各地的风都在向艾维娜倾诉。"}
D.ItemDescriptions[142368]={["5707be1c0c0443f7:21"]="往昔的见证者。"}
D.ItemDescriptions[142369]={["24146c488b5a7fa3:31"]=S[13087]}
D.ItemDescriptions[142370]={["39709ba18248d040:38"]="教你学会制作奥金勇士剑。"}
D.ItemDescriptions[142371]={["b38b791624570933:48"]="摸上去还是热的，能够烧焦凡人的血肉。"}
D.ItemDescriptions[142372]={["9a7d33a8c07e82b9:41"]="织造精美的丝绸，散发着浓郁的香水味。"}
D.ItemDescriptions[142373]={["ca0c8cf0f39a692f:76"]="背面的铭文写着：“愿隐者指引我们获取更伟大的智慧。”"}
D.ItemDescriptions[142374]={["1fee6e40ddf131b3:70"]="鲁博斯在火焰试炼中失败了太多次，导致它的边缘有点烧焦了。"}
D.ItemDescriptions[142376]={["aafd15f9451084ec:79"]="除了散发着邪能的光芒外，它与永歌森林的其他植物几乎没有区别。"}
D.ItemDescriptions[142377]={["7e2d3b7afc44ea19:66"]="这根长矛似乎被本地生物当成了磨牙棒。"}
D.ItemDescriptions[142378]={["6f51206783929c3c:26"]="散发着魔法能量。"}
D.ItemDescriptions[142379]={["9d6d0e19bc8fb050:35"]=S[13094]}
D.ItemDescriptions[142380]={["9d6d0e19bc8fb050:35"]=S[13094]}
D.ItemDescriptions[142381]={["6b8a95993a2393e6:19"]="这是给你的。"}
D.ItemDescriptions[142382]={["30bf2e9ed9b92807:61"]="虽然很难解读，但这似乎是潜入达拉然的计划！"}
D.ItemDescriptions[142383]={["ebbf8afa07b2586f:30"]="教你学会制作黑暗之矛。"}
D.ItemDescriptions[142384]={["12a6a05b19059ecc:60"]="残余的黑暗能量在这颗刻满符文的水晶内虚弱地脉动着。"}
D.ItemDescriptions[142385]={["9b7c2bd97efe0f8c:88"]="从安戈洛各地的营地里偷来的金属锭，应该可以用来锻造任何物品。"}
D.ItemDescriptions[142386]={["ab0b4c2a3643f4ab:40"]="它的力量“几乎”能与强力魔精相媲美了。"}
D.ItemDescriptions[142387]={["7165092fe5387ff4:31"]="必要时，可以取代大块翡翠。"}
D.ItemDescriptions[142388]={["2e3f5e935a4cab1e:34"]="像钻石一样纯净，硬度也与之接近。"}
D.ItemDescriptions[142392]={["921df63dabab4e8e:55"]="这份潦草的笔记描述了窃取聚焦之虹的计划。"}
D.ItemDescriptions[142393]={["5ae532c32cd3a9da:23"]="散发着邪能。"}
D.ItemDescriptions[142394]={["a817bc12016c666d:86"]="乍看之下，这份摧毁敌方岗哨的指令很像真的。但它散发着邪能魔力，而且也太新了。"}
D.ItemDescriptions[142395]={["9a1f49048a1bbef3:75"]="牛头人图腾的部件，散发着邪能。它只可能来自至高岭。"}
D.ItemDescriptions[142396]={["b4fbdf73f558d1c4:34"]="上面刻着一个名字：“莱维娅·劳伦斯”。"}
D.ItemDescriptions[142397]={["5c4bcc2722976860:42"]="筒身上的记号似乎是维库符文。"}
D.ItemDescriptions[142398]={["9902aa808d6a3add:70"]=S[13089]}
D.ItemDescriptions[142401]={["48ae6c2a9012b939:38"]="立即传送一队枯法者入场。"}
D.ItemDescriptions[142402]={["7080ea78c215b3cb:42"]="教你学会制作轻型地铸利刃。"}
D.ItemDescriptions[142403]={["24146c488b5a7fa3:31"]=S[13087]}
D.ItemDescriptions[142407]={["1a4185e83efd4f57:38"]=S[13074]}
D.ItemDescriptions[142408]={["1a4185e83efd4f57:38"]=S[13074]}
D.ItemDescriptions[142409]={["1a4185e83efd4f57:38"]=S[13074]}
D.ItemDescriptions[142436]={["78282fdc5942d741:85"]=S[13093]}
D.ItemDescriptions[142437]={["24146c488b5a7fa3:31"]=S[13087]}
D.ItemDescriptions[142447]={["f5bd0d25363a33ae:55"]="显然被克丽萨的小鸟们撕成布条，拿去筑巢了。"}
D.ItemDescriptions[142448]={["ae2c5188406c4763:45"]=S[13094]}
D.ItemDescriptions[142449]={["dcfbbf98dadc8497:76"]="法杖早就烂掉了，但这个神秘的杖首依然散发着能量。"}
D.ItemDescriptions[142450]={["b1dfb51b50eb8a64:93"]="噢，这真是不可思议的天才……呃，我是说可怕堕落的技术和魔法。"}
D.ItemDescriptions[142451]={["3900c88106ca0e68:85"]="虽然用在其他结界上可能会爆炸，但一件强大的神器或许能化解这种力量。"}
D.ItemDescriptions[142454]={["ea96467b42518096:19"]="你能发现美吗？"}
D.ItemDescriptions[142455]={["4fc3aa913da9a93a:68"]="虽然这些碎片已经不能用来占卜了，但它们仍然含有强大的力量。"}
D.ItemDescriptions[142487]={["ffdbbbe1bcb5c4fa:39"]="失窃的瓦拉加尔灵魂的碎片。"}
D.ItemDescriptions[142491]={["6da9c63a05c6e947:39"]="警告：该宝珠为实验型号，后果未知。"}
D.ItemDescriptions[142502]={["1b551ac242dd0ec7:48"]="由乔安娜制造，能够激活克希雷姆的传送门残影。"}
D.ItemDescriptions[142522]={["c9f705fc6266ca97:31"]="写给你的信，用汗水封的口。"}
D.ItemDescriptions[142527]={["a68f29e1061e96b4:19"]="这或许能派上用场。"}
D.ItemDescriptions[142534]={["9bbf8b11a15094b2:56"]="哪怕遭到黑暗侵蚀，这股不屈的力量也不会熄灭。"}
D.ItemDescriptions[142535]={["0d52984455ec654b:91"]="捕捉飘过门槛的灵魂是种卑鄙的行为，更别说还配上了强大的护符。"}
D.ItemDescriptions[142536]={["ca2ffddec9831407:44"]="这个盒子里回荡着昔日的记忆。"}
D.ItemDescriptions[142552]={["69f5e24752b91ada:50"]=S[13091]}
D.ItemDescriptions[142553]={["e0a43fa0e8c8c0af:64"]="一小撮浓密发亮的矮人胡须，这是你的勇士获胜的证据。"}
D.ItemDescriptions[142554]={["3b0e671cbe84da49:39"]="击败清洁工比尔的证据。"}
D.ItemDescriptions[142555]={["680dc8d2613d07a3:88"]="这根古老的手杖属于一位著名的领袖，里面浸透了它的主人多年的奉献以及对他人的关爱之情。"}
D.ItemDescriptions[142559]={["1d5aa0306e2e6341:107"]="这个盒子里似乎储存过某种早已消散的魔力。或许达拉然有人了解它的详细情况……"}
D.ItemDescriptions[143330]={["3a302dedd29f8d70:36"]="中央的宝石散发着邪能。"}
D.ItemDescriptions[143331]={["5f2cf23ba9f5f3bc:66"]="这些破烂书页上的内容是在多年前由奈鲁斯·月牙所写的。"}
D.ItemDescriptions[143332]={["edf5b9029082a233:72"]="除了一片空白的纸面，卷轴上只有一个小小新月标志。"}
D.ItemDescriptions[143333]={["f3e09a9f740f25e8:62"]="一枚强大的徽记。早在护盾开启前，就是希尔格林的珍藏了。"}
D.ItemDescriptions[143478]={["aeccdbaf41ac881c:54"]="字迹端正的手写字条，以阵亡战士的鲜血作为墨水写成。"}
D.ItemDescriptions[143479]={["d97e0ca1b658f8f8:50"]="血迹和破损反而增添了它的光彩。"}
D.ItemDescriptions[143486]={["3ce69b08c329bd0b:91"]="塑魔者精心打造的水晶，它的力量虽然会被压制，但却不会消失。"}
D.ItemDescriptions[143487]={["cc944fe2be95d417:97"]="人们时常会发现一些天生就具有强大魔力的暮色百合，或许这就是它会成为如此强大象征的原因。"}
D.ItemDescriptions[143488]={["47d63006b974dbc9:82"]=S[20217]}
D.ItemDescriptions[143489]={["7c14671a0eedda37:45"]="教你学会召唤一头先知的狂怒风暴。"}
D.ItemDescriptions[143490]={["1a1ab4c00d0e837b:47"]="教你学会召唤一头暗影之刃的猩红预兆。"}
D.ItemDescriptions[143491]={["482be7829e73f433:47"]="教你学会召唤一头暗影之刃的怨恨预兆。"}
D.ItemDescriptions[143492]={["fbaf3cbfa14241bc:46"]="教你学会召唤一头暗影之刃的致命预兆。"}
D.ItemDescriptions[143493]={["403b240b65a59cb4:49"]="教你学会召唤一头暗影之刃的谋杀预兆。"}
D.ItemDescriptions[143494]={["5ec4765065c31f81:46"]="这似乎是卡兰姆提到过的某个邪教徒写的。"}
D.ItemDescriptions[143496]={["450fc3ee9a00b0cb:47"]="这些文件详细介绍了虚空之誓教派的宗旨。"}
D.ItemDescriptions[143498]={["0d63d092d9b4004f:106"]="大魔导师越来越疯狂了。这家伙的一根小指头里所蕴藏的毁灭性的能量，就足以夷平半个王宫。"}
D.ItemDescriptions[143499]={["00e6f850d920fefd:80"]="这个仓促制成的面具灌注了太多力量，看起来随时可能四分五裂。"}
D.ItemDescriptions[143501]={["41e156a61eabe577:32"]="原产自苏拉玛的芬芳花朵。"}
D.ItemDescriptions[143502]={["f1659b5ec024b88d:46"]="教你学会召唤一头大领主的金辉战马。"}
D.ItemDescriptions[143503]={["55993d41c00935e4:48"]="教你学会召唤一头大领主的复仇战马。"}
D.ItemDescriptions[143504]={["2625076394eacb34:48"]="教你学会召唤一头大领主的警戒战马。"}
D.ItemDescriptions[143505]={["28f8934007a504ad:48"]="教你学会召唤一头大领主的英勇战马。"}
D.ItemDescriptions[143533]={["43cde51f716cbf72:132"]="虽然已经是个强大的恶魔，但洛兹勒斯在驻扎于苏拉玛期间似乎还吸收了许多远古魔力。从他的邪能之躯上断裂下来的獠牙就散发着这种魔力。"}
D.ItemDescriptions[143534]={["2e4f4244efc0775f:27"]="魔导师威勒姆·韦斯特制造"}
D.ItemDescriptions[143535]={["3a302dedd29f8d70:36"]="中央的宝石散发着邪能。"}
D.ItemDescriptions[143537]={["aee94721794dfc9e:60"]="光线在穿过这个东西时，会发生诡异的偏折和扭曲。"}
D.ItemDescriptions[143538]={["6b2cfb3f20dc63c8:151"]="同时包含所有可能的传送结果，理论上可以将你传送到你想去的任何地方。可实际上，它只有在你想去厕所时才可靠。"}
D.ItemDescriptions[143540]={["ad6f7d5a230f9d9b:100"]="别被骗了，它虽然不能摧毁魔网操纵器，但这并不意味着它就不强大。"}
D.ItemDescriptions[143542]={["689484700a83416f:98"]="此种滋补剂未经过炼金局认证。饮用此种药水者需自行承担一切后果。"}
D.ItemDescriptions[143544]={["b236120365489dfe:48"]="恶魔的力量不会全部回归扭曲虚空。"}
D.ItemDescriptions[143545]={["3bd35a00268c4293:64"]="由强大的恶魔监视者使用射线蚀刻而成，能够引导庞大的邪能能量。"}
D.ItemDescriptions[143548]={["8c4a4f1f86b5f522:77"]="这个背包使用邪能兽的肌腱和皮肤纤维缝制而成，散发着邪能能量。"}
D.ItemDescriptions[143551]={["7e2ee48b76f9d9e0:50"]="人们不会思念他们，最后的演出已经谢幕。"}
D.ItemDescriptions[143552]={["87847510af8fbed5:64"]="两位主角走向末路之刻，也是演出绽放光彩之时。"}
D.ItemDescriptions[143553]={["1ec5e4ea58ea8fad:84"]="难怪朱丽叶会沦落到这种地步。她应该喝下自酿的毒药。"}
D.ItemDescriptions[143554]={["a213137ec6243705:76"]="沦为轮换剧目的《罗密欧与朱丽叶》，它唯一的亮点是带给我们一个糟糕的夜晚。"}
D.ItemDescriptions[143556]={["51e810f366c3d83a:49"]="这些骨头还在闷烧，需要小心处理。"}
D.ItemDescriptions[143558]={["f6f6d6dae124d629:60"]="这个箱子里放着各种来自至高岭野外的资源。"}
D.ItemDescriptions[143560]={["645ee53bb31c72b6:29"]="可以分解成邪能碎片。"}
D.ItemDescriptions[143561]={["6b7a9dea5626333b:80"]="对于照明没什么用，但这是证明你的勇士获胜的最佳证据。"}
D.ItemDescriptions[143590]={["ed12b267a0e0cb16:38"]="一件恶劣、恐怖的战利品，来自搏击俱乐部。"}
D.ItemDescriptions[143597]={["338d6da12a7d7fc0:139"]="这颗果实中的古老力量能让夏多雷的生命精华和奥术之灵达到平衡，让他们摆脱对暗夜井的依赖。"}
D.ItemDescriptions[143613]={["5c14859ba752c2a8:68"]="暗夜井的毁灭破坏了这种精心制作的材料。"}
D.ItemDescriptions[143615]={["aaf792a1d85aff6a:49"]="教你学会制造蛮牛吼雷雕文。"}
D.ItemDescriptions[143616]={["eab36e69472557c4:44"]="教你学会制造忠诚战马雕文。"}
D.ItemDescriptions[143618]={["64314041acb06f14:21"]="字体“那么”大。"}
D.ItemDescriptions[143620]={["3877c22d46232c1e:40"]="你必须恢复正常体型才能打开这个箱子。"}
D.ItemDescriptions[143631]={["24146c488b5a7fa3:31"]=S[13087]}
