D.ItemDescriptions[143635]={["e28d732f175e4780:58"]=S[5207]}
D.ItemDescriptions[143636]={["e28d732f175e4780:58"]=S[5207]}
D.ItemDescriptions[143637]={["eb64b6ddebd7533e:54"]="教你学会召唤一匹虚空领主的硫磺愤怒战马。"}
D.ItemDescriptions[143638]={["c5aea97039b3ef2d:56"]="教你学会变形为大德鲁伊的月翼形态。"}
