D.ItemDescriptions[143654]={["ba338d942a4a3b1b:81"]="需要轻拿轻放。如果标本接触皮肤，需立即清洗接触部位。"}
D.ItemDescriptions[143656]={["ca6c97426f7541d9:65"]=S[20154]}
D.ItemDescriptions[143657]={["ca6c97426f7541d9:65"]=S[20154]}
D.ItemDescriptions[143658]={["ca6c97426f7541d9:65"]=S[20154]}
D.ItemDescriptions[143661]={["3479f1a7d41f7b38:31"]="用于捕捉强大的失落之魂。"}
D.ItemDescriptions[143663]={["b3bd50fedf63b7f1:32"]="散发着淡淡的玫瑰清香以及……腐败气味。"}
D.ItemDescriptions[143676]={["c2109f628a8f05cd:33"]="散发着强大的能量。"}
D.ItemDescriptions[143679]={["9d6d0e19bc8fb050:35"]=S[13094]}
D.ItemDescriptions[143681]={["2dc515901fda72ef:15"]="烧焦的食物：2级"}
D.ItemDescriptions[143717]={["e845092cc120976d:81"]="这个脆弱的茶杯被放在玩具箱的最底层，躲过了一劫。"}
D.ItemDescriptions[143718]={["9bdf340dfb1d7978:32"]="能够安全保存被污染的尸体。"}
D.ItemDescriptions[143728]={["c92991f5a2d8565a:52"]="带着致命的冷静，像落锤一样跃入战场。"}
D.ItemDescriptions[143731]={["3d8c1cacaa4e5bb9:27"]="警告：饮用者后果自负。"}
D.ItemDescriptions[143732]={["88b282cbd429271a:28"]="记住谁才是你真正的敌人……"}
D.ItemDescriptions[143736]={["2f93664eb96eca59:30"]="由艾萨莱斯特精心配制。"}
D.ItemDescriptions[143738]={["744d1e67b4df1a84:36"]="阿鲁因以前送给奥露乐的礼物。"}
D.ItemDescriptions[143739]={["1653a34e6dd1593f:53"]="阿戈斯是个浮夸的家伙，希望让所有人都知道他的事迹。"}
D.ItemDescriptions[143740]={["57985c7e41d9fb0d:94"]="血精灵使用这种带有强力结界的旗帜标记边界，威慑进攻者。"}
D.ItemDescriptions[143741]={["378e14022fd03ff7:86"]="这些受艾露恩祝福的旗帜环绕着暗夜精灵的前线营地，可提供保护和援助。"}
D.ItemDescriptions[143742]={["19b68033c975f9ba:49"]="英格拉从另一个世界带来的强大节杖。"}
D.ItemDescriptions[143743]={["0d692571cafbb82a:54"]="被阻塞了数千年，充斥着能量。"}
D.ItemDescriptions[143744]={["c1a032a5334697da:108"]="一对被牧师祝福过的利刃，具有不可思议的能量。对于新手来说恐怕有点不好掌握。"}
D.ItemDescriptions[143745]={["74225dbfee696c62:34"]="伟大的工作需要伟大的工具。"}
D.ItemDescriptions[143746]={["c0620549c2c11876:24"]="融合了能量的强大武器。"}
D.ItemDescriptions[143747]={["5f4866fbe973ff56:103"]="数千年来，它已经不仅仅是一把钥匙而已了。拿上它吧！用它来解锁能量，而不是把其他人拒之门外。"}
D.ItemDescriptions[143749]={["f5b8d6fbbd6ce610:122"]="这个复杂的夜之子护符已经被扭曲腐化，用来进行骇人听闻的暴行。应该将它的能量抽取出来进行崇高的事业。"}
D.ItemDescriptions[143751]={["09f40fed7c81980e:42"]="教你学会制作暮光花蕾雕文。"}
D.ItemDescriptions[143752]={["795d57b9e8eb6c66:36"]="教你学会召唤音波测试坐骑。"}
D.ItemDescriptions[143753]={["7403eb7c14cfec3b:90"]="通常会含有一些宠物绷带和宠物符咒，但偶尔也会包含一只特殊的宠物。"}
D.ItemDescriptions[143754]={["ae2c5188406c4763:45"]=S[13094]}
D.ItemDescriptions[143755]={["ae2c5188406c4763:45"]=S[13094]}
D.ItemDescriptions[143756]={["ae2c5188406c4763:45"]=S[13094]}
D.ItemDescriptions[143757]={["4e38f6019c27a5d0:162"]="作为古尔丹的法杖杖首，它是暗影议会的象征。由于和暗影界有着密切联系，它在古尔丹和他的燃烧军团主子手中成了一件强大的工具。"}
D.ItemDescriptions[143758]={["791b06e226855535:78"]="交给比兹莫搏击俱乐部的酒吧老板汤斯丽，为所有人购买2分钟的免费饮料时间！"}
D.ItemDescriptions[143759]={["8a7df2de610e720f:87"]="交给比兹莫搏击俱乐部的贵宾室保镖，让所有人在10分钟内免费享用贵宾室！"}
D.ItemDescriptions[143760]={["554086cda376bbc0:102"]="交给比兹莫搏击俱乐部的奎肯布什，购买一桶药水，并在接下来的30分钟内为所有人免费发放药水。"}
D.ItemDescriptions[143761]={["2bab11d09f5c50e1:96"]="交给比兹莫搏击俱乐部的莉迪亚·佩顿，在搏击俱乐部里购置一块墓地，持续30分钟。"}
D.ItemDescriptions[143762]={["6adf72bcddcab43d:77"]="交给比兹莫搏击俱乐部的高奇·金链，购买一次竞猜机会，持续30分钟。"}
D.ItemDescriptions[143763]={["dcdc0301d3f9469c:75"]="交给比兹莫搏击俱乐部的比兹莫搏击俱乐部保镖，随机开启一种搏击模式，持续30分钟。"}
D.ItemDescriptions[143764]={["69f5e24752b91ada:50"]=S[13091]}
D.ItemDescriptions[143772]={["727aeb5d814e6260:93"]=S[5636]}
D.ItemDescriptions[143773]={["2f93664eb96eca59:30"]="由艾萨莱斯特精心配制。"}
D.ItemDescriptions[143778]={["ba0b6a5f0f04264c:75"]="这个邪恶的图腾似乎能给附近的生物灌注邪能，而这通常都会害死它们。"}
D.ItemDescriptions[143779]={["bba70fe79c648b02:77"]="蓝龙军团的古老神器，具有不可思议的魔力。"}
D.ItemDescriptions[143780]={["52e9e77e6832eae9:76"]=S[5486]}
D.ItemDescriptions[143785]={["52e9e77e6832eae9:76"]=S[5486]}
D.ItemDescriptions[143794]={["ee5c4a0578f34462:96"]="向一名搏击俱乐部代表出示此卡牌以挑战海鸥。你同一时间内只能拥有一张挑战卡牌。"}
D.ItemDescriptions[143795]={["a692594772d1e612:39"]="脉动着卡萨纳提尔压抑的怒火。"}
D.ItemDescriptions[143799]={["773dde9063bec2b7:36"]=S[18090]}
