D.ItemDescriptions[143827]={["90d217be7d305757:13"]="我是脑袋！"}
D.ItemDescriptions[143828]={["3f92d927e5911802:17"]="噢，那我来当身体！"}
D.ItemDescriptions[143829]={["9e07f909f6de3a4e:16"]="那我就是尾巴了……"}
D.ItemDescriptions[143836]={["8842cdab20910e92:53"]="这个碟子里似乎灌注了大量火焰能量。"}
D.ItemDescriptions[143837]={["cab5a7f377568060:54"]="这个碟子里似乎灌注了大量冰霜能量。"}
D.ItemDescriptions[143838]={["afdaef2f6a687182:55"]="这个碟子里似乎灌注了大量奥术能量。"}
D.ItemDescriptions[143840]={["014683140256a6d5:26"]="并不是神器武器。"}
D.ItemDescriptions[143842]={["9d6d0e19bc8fb050:35"]=S[13094]}
D.ItemDescriptions[143845]={["a396ef89fbc25772:26"]="在你看来更像牙齿……"}
D.ItemDescriptions[143852]={["09100b87960bd3de:34"]="能让你走运，但对这只兔子就未必了。"}
D.ItemDescriptions[143853]={["33637d66e3e06d25:13"]="少了一只脚。"}
D.ItemDescriptions[143856]={["236c5c42a052638f:44"]="被困在其中的灵魂发出痛苦的呻吟。"}
D.ItemDescriptions[143860]={["9981f1af37439be4:66"]="受到过玛加萨的影响，以及无数元素的强化。"}
D.ItemDescriptions[143863]={["bf82d1591adbaa44:38"]="这个邪能的图腾已经改头换面，能够发挥积极作用了。"}
D.ItemDescriptions[143864]={["24146c488b5a7fa3:31"]=S[13087]}
D.ItemDescriptions[143866]={["b616377be39c69c2:85"]="穿着全套暮光异教徒护甲使用强力风石，召唤深渊领主。"}
D.ItemDescriptions[143867]={["73694f2984d0b500:78"]="穿着全套暮光异教徒护甲使用强力风石，召唤深渊公爵。"}
D.ItemDescriptions[143888]={["7d005f9aa6a6b7b5:47"]="正在快速冷却，但你最好还是戴上手套。"}
D.ItemDescriptions[143899]={["ecd9bc47a6587312:102"]="向一名搏击俱乐部代表出示此卡牌以挑战背叛者奥索。你同一时间内只能拥有一张挑战卡牌。"}
D.ItemDescriptions[143918]={["761960fa43394607:40"]="触摸时会发出愤怒的高频嗡鸣声。"}
D.ItemDescriptions[143924]={["3b740e130a0ff592:43"]="制作这把钥匙所用的金属会发烫。"}
D.ItemDescriptions[143932]={["e5dbbbdf7d1ad61c:43"]=S[810]}
D.ItemDescriptions[143933]={["c5fe6891a91e4314:20"]="难闻，也难喝。"}
D.ItemDescriptions[143934]={["39ae11cfd9c50b94:14"]="尚未开封！"}
D.ItemDescriptions[143948]={["e57820455d0ac112:54"]="内含三袋来自半山新鲜农场的蔬菜。"}
D.ItemDescriptions[143953]={["9d6d0e19bc8fb050:35"]=S[13094]}
D.ItemDescriptions[143954]={["9d6d0e19bc8fb050:35"]=S[13094]}
D.ItemDescriptions[144050]={["40858f64cb5e664d:32"]=S[472]}
D.ItemDescriptions[144064]={["0ac1d400d956e7fd:32"]="以其卓越的净化能力而久负盛名。"}
D.ItemDescriptions[144071]={["488a9ea0a4408de5:35"]="海拉的仆从灵魂为其提供了能量。"}
D.ItemDescriptions[144072]={["596db7cfe1e1eb76:38"]="它们只想有人陪它们玩。"}
D.ItemDescriptions[144179]={["48039ba8ce55ac55:30"]=S[18931]}
D.ItemDescriptions[144196]={["8f027895cfa16e46:35"]=S[8716]}
D.ItemDescriptions[144236]={["009d6422c5439e4d:58"]="能看见的敌人都不可怕，最可怕的是看不见的敌人。——马迪亚斯·肖尔，军情七处"}
D.ItemDescriptions[144238]={["577207f2fbc888c1:30"]="身份不明、年代不详的遗骸。"}
D.ItemDescriptions[144239]={["bac48528784b472f:54"]="从堕落的风暴守护者，至高守护者莱登那里偷来的。"}
D.ItemDescriptions[144240]={["cd9c0b9bfc14b058:44"]="只沾上了一点点邪能黏质，可能还是好的。"}
D.ItemDescriptions[144241]={["ad12087f279ee8be:39"]="这些骨头已经被邪能破坏了。"}
D.ItemDescriptions[144242]={["5fc1e1a5669c01b8:157"]="只要松妮在附近，她的盟友就会倍受鼓舞。虽然她是有史以来最强大的德鲁伊之一，但她的许多手法其实是从传奇牧师皮瑞克丝那里学来的。"}
D.ItemDescriptions[144244]={["d44626d634023425:49"]="因一位特立独行的牧师而得名，没人知道他的名字到底该怎么念。"}
D.ItemDescriptions[144247]={["962e7d024b3e5c55:67"]="拉玛尔现出真身后，维鲁斯很快就明白了他的真正动机。"}
D.ItemDescriptions[144249]={["41c0b053cbffb8e6:131"]="作为燃烧军团的大领主，污染者阿克蒙德拥有无尽的魔力，摧毁了无穷宇宙中的无数世界。"}
D.ItemDescriptions[144255]={["0a71872461570bc5:18"]="里面的邪能已经消耗一空了。"}
D.ItemDescriptions[144256]={["5ae532c32cd3a9da:23"]="散发着邪能能量。"}
D.ItemDescriptions[144258]={["dff4705bbfcc4ef4:128"]="不朽者维伦被他的人民称为先知，具有预言的天赋。在圣光的帮助下，他已经领导德莱尼超过25000年了。"}
D.ItemDescriptions[144259]={["6beb42d631e0fd2b:182"]="作为燃烧军团的最高指挥官，欺诈者基尔加丹的目标很简单：吞噬所有的生命和魔力，将所有种族都并入燃烧军团，杀掉所有敢于反抗的人，并摧毁一切造物。"}
D.ItemDescriptions[144260]={["1e36a1436f80d790:51"]="这些家伙似乎总藏着好几手神奇的底牌。"}
D.ItemDescriptions[144273]={["74937965be7d910c:20"]="圣光使我们永存。"}
D.ItemDescriptions[144274]={["3f23851ad06d3aa1:81"]="各种力量和能量的存在与混合常常会形成强大的魔力漩涡。"}
D.ItemDescriptions[144275]={["065ecc487de72783:86"]="与残忍的玛提斯的谎言正相反，撒鲁安始终坚定，直到他远离了圣光。"}
D.ItemDescriptions[144277]={["b19f845fccfabb4c:55"]="它们曾属于酿酒与锻造大师魏豪酒。"}
D.ItemDescriptions[144279]={["a7ffa7f3d3542c5e:23"]="强大的力量……任何代价都行。"}
D.ItemDescriptions[144280]={["c4ddbe3eb146d35b:40"]="在这个世界上，除了死亡，没有任何东西是确定的。"}
D.ItemDescriptions[144281]={["7a7ad64fe94e3be2:20"]="以血换血"}
D.ItemDescriptions[144283]={["7df06eb39e6c0026:51"]="一块破碎的冬鳞蚌壳，形状有点像一颗心。"}
D.ItemDescriptions[144284]={["c1e0a4a838c49065:25"]="它看上去有点像你。"}
D.ItemDescriptions[144285]={["1b13bda5ae9be59a:43"]="一块粘着几根海藻的扁平石头。"}
D.ItemDescriptions[144286]={["a6f3a7665cc11f9b:43"]="你的蝌蚪为你留了一半午餐。"}
D.ItemDescriptions[144287]={["fe7c50af52df1424:43"]="你的蝌蚪在送你这件礼物时十分激动。"}
D.ItemDescriptions[144288]={["5f186b1ca091aa53:78"]="你的蝌蚪非常自豪地将这把沙子送给了你。它肯定是潜入了很深的海底才找到它们的。"}
D.ItemDescriptions[144289]={["94d6ccf063d39477:74"]="你的蝌蚪满怀期待地将这份精心制作的午餐送给了你。"}
D.ItemDescriptions[144290]={["643dc2800a9fc0b9:29"]="这颗珍珠真的很漂亮。"}
D.ItemDescriptions[144292]={["5deb13c35d9338d2:113"]="黑炎之龙有时会对使用者造成严重伤害。可一旦被控制住，它就会为使用者带来巨大的力量。"}
D.ItemDescriptions[144293]={["ef0efe70c40ed20b:85"]="在临死时……辛达苟萨的心中充满了痛苦、仇恨和对复仇的渴望。"}
D.ItemDescriptions[144294]={["b40a643477fe2441:44"]="这应该就是格雷森要找的骑甲。"}
D.ItemDescriptions[144295]={["6644468b52231968:95"]="通过反思和努力，大德鲁伊托玛考斯学会了复制双月的力量。"}
D.ItemDescriptions[144298]={["d07e785990e0b56e:11"]="即抛型。"}
D.ItemDescriptions[144299]={["2d2872bc8052ae23:41"]="使用的石材与废墟中随处可见的乱石完全一致。"}
D.ItemDescriptions[144300]={["bcc05b224ea5653b:40"]="木材上刻着复杂的符文。"}
D.ItemDescriptions[144301]={["4f5fd1a03af67bf7:26"]="由大师精心制作。"}
D.ItemDescriptions[144302]={["7fd64a1af2a33e27:46"]="镶嵌着无数不同大小和颜色的宝石。"}
D.ItemDescriptions[144303]={["049532aef8658a71:64"]="当然是通过保持角动量做到的了！这很简单的，真的。"}
D.ItemDescriptions[144308]={["e33f7a3cf4653707:52"]="教你学会施加精通之印的附魔效果。"}
D.ItemDescriptions[144309]={["3ff3ed61e7afb7dc:67"]="教你学会更加高效地施加精通之印的附魔效果。"}
D.ItemDescriptions[144310]={["2a4fe28ebfcbcce9:71"]="教你学会极其高效地施加精通之印的附魔效果。"}
D.ItemDescriptions[144311]={["ff4d4afff98d2348:55"]="教你学会施加全能之印的附魔效果。"}
