D.ItemDescriptions[144313]={["78c40671f2c66568:74"]="教你学会极其高效地施加全能之印的附魔效果。"}
D.ItemDescriptions[144314]={["5b10f34dc3fe3056:51"]="教你学会施加急速之印的附魔效果。"}
D.ItemDescriptions[144315]={["b213ca52bc6c36cd:66"]="教你学会更加高效地施加急速之印的附魔效果。"}
D.ItemDescriptions[144316]={["3206cfffa0cfbada:70"]="教你学会极其高效地施加急速之印的附魔效果。"}
D.ItemDescriptions[144317]={["8a071f2318855716:52"]="教你学会施加致命之印的附魔效果。"}
D.ItemDescriptions[144318]={["a8143f6816aa600d:67"]="教你学会更加高效地施加致命之印的附魔效果。"}
D.ItemDescriptions[144319]={["6ec7e015d35ca41a:71"]="教你学会极其高效地施加致命之印的附魔效果。"}
D.ItemDescriptions[144322]={["333324eff52487a2:40"]="原本鲜亮的色彩已经在岁月流逝中变得黯淡了。"}
D.ItemDescriptions[144323]={["caf7f5aeeeb6c5ab:27"]="手工缝制，摸上去十分柔软。"}
D.ItemDescriptions[144324]={["2af26f72ca7e4063:50"]="柔软的金属上刻着两组缩写字母。"}
D.ItemDescriptions[144325]={["5f226eb90c3ab63c:26"]="闪烁着艾露恩的光辉。"}
D.ItemDescriptions[144326]={["145800d45e001009:32"]="不听话的宠物都会被做成护肩。"}
D.ItemDescriptions[144329]={["995976967304d30d:86"]="来自链齿容器，拥有工匠的恩赐附魔的玩家可以获得这种宝箱。"}
D.ItemDescriptions[144330]={["c857192255c21c7d:97"]="内含来自破碎群岛的工程学材料。拥有工匠的恩赐附魔的玩家可以获得这种宝箱。"}
D.ItemDescriptions[144335]={["94ba66ed87c556c6:42"]="教你学会制作布甲爆头者。"}
D.ItemDescriptions[144336]={["565235b78a28ef96:40"]="教你学会制作毛皮爆头者。"}
D.ItemDescriptions[144337]={["f199e11caca79713:39"]="教你学会制作链甲爆头者。"}
D.ItemDescriptions[144338]={["3e601db669320e19:39"]="教你学会制作重甲爆头者。"}
D.ItemDescriptions[144340]={["d0c244d6341ff5dd:70"]="林恩照看着我们，就像昔日皇帝少昊照看着林恩和潘达利亚的其他子民一样。"}
D.ItemDescriptions[144343]={["36b2d74573ef0548:47"]="教你学会制作可充电的里弗斯电池。"}
D.ItemDescriptions[144344]={["52e6a2f00fbc1afb:40"]=S[3574]}
D.ItemDescriptions[144345]={["debd5f119f0c026c:80"]="内含来自破碎群岛的宠物补给。可以被拥有动物管理员附魔的玩家拾取。"}
D.ItemDescriptions[144347]={["52e6a2f00fbc1afb:40"]=S[3574]}
D.ItemDescriptions[144348]={["52e6a2f00fbc1afb:40"]=S[3574]}
D.ItemDescriptions[144349]={["52e6a2f00fbc1afb:40"]=S[3574]}
