D.ItemDescriptions[144354]={["4f55fe80e5cc1da9:93"]="猫咪都是任性的。如果它们亲近你，那很好。但如果你想亲近它们，那就未必有用了。"}
D.ItemDescriptions[144355]={["b8bcf8b86b14190f:62"]="火当然可以用来攻火。火可以用来解决一切问题。"}
D.ItemDescriptions[144358]={["fd5c8e39e963cb6c:32"]="灰烬……灰烬……统统化为灰烬。"}
D.ItemDescriptions[144361]={["51307651ca0009fc:19"]="啊……新鲜的肉……"}
D.ItemDescriptions[144362]={["5ae532c32cd3a9da:23"]="散发着邪能。"}
D.ItemDescriptions[144364]={["13ca72dd68678316:53"]="俗话说种瓜得瓜种豆得豆……好吧，我想我还是快点开始播种吧。"}
D.ItemDescriptions[144369]={["3b0e78e3d27f53ba:111"]="日益加剧的混乱是区分过去与未来的标志，也是时间轴方向建立的依据。——时空教授霍金"}
