D.ItemDescriptions[144385]={["c57d4ef8593cb90f:167"]="萨奇尔是个惊才绝艳的巫师，他领导着一群擅长召唤与束缚的艾瑞达法师，名为启迪者。这个徽记象征着他们至死不渝的忠诚。"}
D.ItemDescriptions[144394]={["ae2c5188406c4763:45"]=S[13094]}
D.ItemDescriptions[144395]={["74e86b98082fa31d:87"]="对初始调查笔记的综述，记载了许多在艾泽拉斯历史上占有一席之地的伟大武器。"}
D.ItemDescriptions[144401]={["1a03f726c8f92e7f:59"]="如果你想轻松携带大量刀具，那你就走运了。"}
D.ItemDescriptions[144402]={["90e4ea4ef55c6707:54"]="哪怕是一小块魔能机甲核心的碎片也蕴含着庞大的力量。"}
D.ItemDescriptions[144403]={["01f83f8789fddcb2:46"]="别在春天穿，除非你想被人嘲笑。"}
D.ItemDescriptions[144408]={["353188345e445bab:44"]="这块碎片里原本的能量都已经被抽取殆尽了。"}
D.ItemDescriptions[144410]={["199002c21b565b4d:21"]="这种酒还装在桶里。"}
