D.ItemDescriptions[144432]={["4441d1b68796ea0b:26"]="狗靠一张嘴，树靠一张皮……"}
D.ItemDescriptions[144433]={["aebd98d01c41bbdd:71"]=S[5544]}
D.ItemDescriptions[144434]={["aebd98d01c41bbdd:71"]=S[5544]}
