D.ItemDescriptions[144438]={["1ea9bdc794b7d602:86"]="你以为我会怕死吗？我已经死过无数次，实在是再擅长不过了。你才死过几次？"}
D.ItemDescriptions[144439]={["beb1ba3c658a8325:93"]="向一名搏击俱乐部代表出示此卡牌以挑战克伦克。你同一时间内只能拥有一张挑战卡牌。"}
D.ItemDescriptions[144442]={["505ec87a998ab7d1:31"]="没有球和其他配套的部分就没法玩。"}
D.ItemDescriptions[144443]={["32b6e9997fff5b90:51"]="勉强容纳了大量的邪能。"}
D.ItemDescriptions[144444]={["f3158682da71b969:64"]="这些野兽富含魔力的血液是术士仪式中常用的材料。"}
D.ItemDescriptions[144445]={["b5c5b7f7ee996e38:67"]="由恐惧魔王赫尔努拉斯制造，用于引诱并束缚克索诺斯的地狱战马。"}
D.ItemDescriptions[144457]={["6aff233da0f30f7a:65"]="一份稀有的维库人文稿，记载了一个有关瓦尔基拉的预言。"}
D.ItemDescriptions[144458]={["42ca42a1f2aac21a:24"]="在其内心深处，依然是纯净的。"}
D.ItemDescriptions[144464]={["352d9af19a26f5de:49"]="暗影扫过它的表面，打破了某种看不见的壁垒。"}
D.ItemDescriptions[144467]={["9fd85f3c119f2317:52"]="这个华丽的瓶子上带有高阶女祭司德雅娜的徽记。"}
