D.ItemDescriptions[146123]={["facc7fdc14b39f97:61"]="灌注了魔法能量，能够确保用它锁上的锁不会被打开。"}
D.ItemDescriptions[146126]={["85300bfcb308e293:68"]="这本书末尾的历史经过了篡改，将维伦描述成了一个叛徒。"}
D.ItemDescriptions[146127]={["6770569d0656eb24:42"]="没有人知道燃烧军团到底焚毁了多少个世界。"}
D.ItemDescriptions[146308]={["d754ebc6d64d9949:20"]="恶魔的克星！"}
D.ItemDescriptions[146309]={["6b1447339e7be146:52"]="成功施放上层精灵法术后留下的材料残渣。"}
D.ItemDescriptions[146310]={["56929b4d452cb794:34"]="勉强被压制住的邪能在其中沸腾着。"}
D.ItemDescriptions[146311]={["f3b6c7a48db297a7:40"]="瓶中的血液愤怒地沸腾着。"}
D.ItemDescriptions[146312]={["3c35acf34a0e5d24:26"]="散发着微弱的邪能。"}
D.ItemDescriptions[146313]={["76dcba03d0d0047c:44"]="蓝色的陶土上刷着玫瑰色的颜料。"}
D.ItemDescriptions[146314]={["6f5dae7ec0762473:56"]="这个箭头可能属于某位古代上层精灵哨兵。"}
D.ItemDescriptions[146315]={["98a6e9fce06ce0a5:36"]="这份恩赐也无法防止其流散。"}
D.ItemDescriptions[146316]={["c17b47c4eceb18db:67"]="这种类型的硬币在至少7000年前就已经不在苏拉玛流通了。"}
D.ItemDescriptions[146317]={["2316566d06d26100:43"]="通常会含有宠物补给和一些宠物符咒。"}
D.ItemDescriptions[146318]={["404e529dd41d1dee:46"]="与食人魔的指骨几乎没什么差别。"}
D.ItemDescriptions[146319]={["f860f02fc5dbac26:30"]="一撮散发着恶臭的灰烬和恶魔血液。"}
D.ItemDescriptions[146320]={["a846fba4771a75d1:67"]="这种宝石经常被高阶恶魔镶嵌在护甲或武器上。"}
D.ItemDescriptions[146321]={["2506b8e17b7715b6:35"]="某个早已陨落的恶魔的恐怖剪影。"}
D.ItemDescriptions[146322]={["2dbefdc9e94595dc:53"]="这些古老的恶魔口粮保存得非常完好。"}
D.ItemDescriptions[146323]={["76ebbcc4c9e8edbf:17"]="上面的蜡烛不见了。"}
D.ItemDescriptions[146324]={["ef1694418fea9684:69"]="如果保存环境足够干燥，这种羽毛就会变得像骨头一样硬。"}
D.ItemDescriptions[146325]={["049a30656252d1b6:45"]="一个满是破洞的袋子，里面的粮食早就不见了。"}
D.ItemDescriptions[146326]={["fce925eff6423938:48"]="灼热的葬礼柴堆的残留物。"}
D.ItemDescriptions[146327]={["f9073a3dbcb8c5aa:42"]="某位早已离世的牛头人萨满留下的图腾，已经被世人所遗忘。"}
