D.ItemDescriptions[150744]={["8364c859cd56cd26:61"]="修复一切邪恶、堕落以及反自然之力留给大地的伤痕。"}
D.ItemDescriptions[150745]={["903d0194138a68db:97"]="关于如何在第四次大战中迅速打残联盟位于东部王国部队的详细战略手册。"}
D.ItemDescriptions[150746]={["6856cb119014bf3c:88"]="关于如何为位于东部王国的岗哨及时提供补给的几点建议。"}
D.ItemDescriptions[150750]={["79862dd85c2d9b6f:37"]="只要一小勺，就能治愈一切疾病！"}
D.ItemDescriptions[150936]={["e0cb458cfb92b5b9:136"]="无冕者藏身于暗影大厅。他们拥有弑君灭国之能，他们用无人知晓的利刃书写着这个世界的真正历史。"}
D.ItemDescriptions[150942]={["445f455b756c4afc:34"]="虽然有些磨损，但依然散发着能量。"}
D.ItemDescriptions[150993]={["155cd62c441b5fbb:85"]="由圣光军团斥候布莱所写，这个密码本可以用来破译燃烧军团的指令。"}
D.ItemDescriptions[150995]={["429814d3e1f1f5dc:114"]="这些下达给部队的指令用邪能魔法写成，有燃烧军团指挥官的可怕力量作为背书，必须有相应的密码本才能解读。"}
D.ItemDescriptions[151016]={["16c493ef24f7191a:68"]="这个邪能容器保留的能量只够收割最弱小的生物了。"}
D.ItemDescriptions[151028]={["b7b5ac750065e704:78"]="灵魂能壮大燃烧军团的部队，但它们不稳定的性质很难控制。"}
D.ItemDescriptions[151061]={["ed1b75f70a36df82:41"]="克罗库会妥善安葬这些尸骨的。"}
