D.ItemDescriptions[151636]={["4e356b7495234fcf:116"]="塞纳里奥议会生活在梦境林地。他们是自然的守护者，平衡的维系者，所有生命的保护者。"}
D.ItemDescriptions[151638]={["07cca3cae614c71b:29"]="这个袋子的一部分已经损坏了。"}
D.ItemDescriptions[151639]={["469eccbbeb3693aa:112"]="伊利达雷驾驶着邪能之槌号。他们屠杀恶魔并驾驭它们的禁忌力量，不惜一切代价与混沌的大军作斗争。"}
D.ItemDescriptions[151640]={["883de6e357200172:109"]="黑锋骑士团的大本营位于阿彻鲁斯：黑锋要塞。他们曾是天灾军团的勇士。现在，他们掌握了诅咒的力量。"}
D.ItemDescriptions[151641]={["e9e001964a282db7:113"]="隐秘通途生活在神射手营地。他们是荒野上的守望者，他们是长风中的雄鹰，他们孤独地行走在自己的道路上。"}
D.ItemDescriptions[151642]={["5549a4a9a5571e6e:154"]="提瑞斯秘法会位于守护者圣殿。他们是达拉然的精锐法师卫士，曾经受到提瑞斯法议会的召唤，代替空缺的守护者战斗。"}
D.ItemDescriptions[151643]={["1b358cdde598d712:94"]="残寺派生活在五晨寺中。他们是黯淡未来的希望使者。"}
D.ItemDescriptions[151644]={["f1086bd607598775:137"]="白银之手骑士团的大本营位于圣光秘殿。他们是由银色北伐军、阿古斯之手、烈日行者和血骑士组成的联合部队。"}
D.ItemDescriptions[151645]={["89ac720054d018fd:39"]="教你学会召唤和解散挖洞蛛。"}
D.ItemDescriptions[151646]={["e23e7f06bdd4d86d:148"]="教团的大本营位于虚空之光神殿。他们是圣光的大师和虚空的拥抱者——因为光明与黑暗是相辅相成的。"}
D.ItemDescriptions[151647]={["9c56ffa0bee78e93:144"]="大地之环隐居在艾泽拉斯之心。他们掌握着元素的力量，同时也维持着元素的平衡。他们是真正的元素大师。"}
D.ItemDescriptions[151649]={["7007fcdb3e7627b8:125"]="黑暗收割议会坐落于恐痕裂隙。他们是灵魂的收割者、恶魔的号令者和黑暗艺术的大师。"}
D.ItemDescriptions[151650]={["a38c14141be4ce95:102"]="瓦拉加尔生活在苍穹要塞。他们是奥丁选中的强大勇士，保护世界远离一切威胁。"}
D.ItemDescriptions[151652]={["1bf67e9293f27c59:108"]="用户需自行对最终传送目的地负责，不得对本设备的制造者采取任何法律手段。"}
