D.ItemDescriptions[151737]={["56b5b543957e6f46:36"]="教你学会切割迅捷圣光榍石。"}
D.ItemDescriptions[151738]={["677fd0fb9fe040f4:37"]="教你学会切割精湛阿古斯晶石。"}
D.ItemDescriptions[151739]={["1a257ac351392110:40"]="教你学会切割万能拉长石。"}
D.ItemDescriptions[151740]={["f7c027f2671ece1d:42"]="教你学会制作魔化护肩。"}
D.ItemDescriptions[151741]={["4fba2b178a96f182:57"]="教你学会更加高效地制作魔化护肩。"}
D.ItemDescriptions[151742]={["30a9e245291e4b9c:61"]="教你学会极其高效地制作魔化护肩。"}
D.ItemDescriptions[151743]={["c941f439e191f8b4:37"]="教你学会制作魔化肩胄。"}
D.ItemDescriptions[151744]={["f629bdba3a9b4a13:52"]="教你学会更加高效地制作魔化肩胄。"}
D.ItemDescriptions[151745]={["8bd0c02806b0ef79:56"]="教你学会极其高效地制作魔化肩胄。"}
D.ItemDescriptions[151746]={["b1e0278d1d03be02:38"]="教你学会制作光纹马裤。"}
D.ItemDescriptions[151747]={["aed46032f3e26667:53"]="教你学会更加高效地制作光纹马裤。"}
D.ItemDescriptions[151748]={["f95bb060d29c1a81:57"]="教你学会极其高效地制作光纹马裤。"}
D.ItemDescriptions[151750]={["6313b0018bd64f5e:28"]="真应该听那匹马的。"}
D.ItemDescriptions[151753]={["fbdd5730325b642b:70"]="家长警告：长时间曝“光”可能会导致腐烂以及（或者）死亡。"}
D.ItemDescriptions[151755]={["78ed51577de29fd8:35"]="还有什么能比一根签名鼓槌更好呢？"}
D.ItemDescriptions[151756]={["d7e8ee119fe07eec:32"]="金卡总是比较强。"}
D.ItemDescriptions[151757]={["fb1948298314ee6a:15"]="只印刷了10,000份。"}
D.ItemDescriptions[151758]={["577fe321d9ce4114:41"]="著名贝斯手的封装肖像。"}
D.ItemDescriptions[151759]={["422122ec804febd9:34"]="他在签名时极其冷酷。"}
D.ItemDescriptions[151760]={["6f9cd14af1cbf457:43"]="如果你仔细看，就会发现上面的人在动！"}
D.ItemDescriptions[151761]={["67dfd034b4e1db1d:65"]="卷轴上的字迹潦草凌乱，但又异常眼熟。"}
D.ItemDescriptions[151774]={["4890082671d5c9fb:11"]="始终冰冷如初。"}
D.ItemDescriptions[151775]={["11d8bea77073f0f8:29"]="它很有营养，这就是它的价值。"}
D.ItemDescriptions[151782]={["7c0d661234694855:60"]="房间中的人们来来往往，/ 谈论着奥蕾莉亚和图拉扬。"}
D.ItemDescriptions[151783]={["1060d1670d698890:101"]="守护者平静地接受了这一真理：万物都无法永存，无论是参天的大树，还是缠绵的爱情，甚至就连暴力的死亡也一样。"}
D.ItemDescriptions[151784]={["c964f3b01784e64f:61"]="迷雾中分出两条道路，而我……/我选择了第三条无人行走的道路。"}
D.ItemDescriptions[151785]={["ac5dd031513bb9de:90"]="恶魔的怒火将考验它们的价值；/大地祭坛上的偶像碎裂了。"}
D.ItemDescriptions[151786]={["99423266f18f872d:41"]="给我你的力量，永生就将属于我们。"}
D.ItemDescriptions[151787]={["b5b50ae4745a7623:89"]="群星投下了它们的投枪/用它们的眼泪润湿了穹苍/她是否微笑着欣赏她的作品？"}
D.ItemDescriptions[151788]={["9f9c04cf6e18b7a2:71"]="怒拳为谁握？护国安邦惩奸恶……道法自然除心魔！"}
D.ItemDescriptions[151789]={["983b93e359e70496:51"]="将携带者排除在歼灭协议之外。"}
D.ItemDescriptions[151795]={["ae4e1279e16dfdb6:85"]="没有人知道夺灵者的来历。所有泰坦文献中都没有提到过他。"}
D.ItemDescriptions[151796]={["ea44fc6badc11ee6:103"]="冰封之心的跳动声可以传到遥远的地方，提醒着所有的生者，死亡是无法避免的。"}
D.ItemDescriptions[151798]={["9a73807e1b59e809:69"]="混沌中存在着重复性、反馈循环，以及潜在的定式。"}
D.ItemDescriptions[151799]={["0a8a94b106f6dc32:43"]="湮灭是对这个世界最好的指引。"}
D.ItemDescriptions[151800]={["5624dc84a4bcdf17:49"]="汝不知星辰是否燃烧，\n汝不知太阳是否运转。"}
D.ItemDescriptions[151801]={["64b231b60d3f085d:26"]="不要唤醒沉睡的猛虎。"}
D.ItemDescriptions[151802]={["6d858927169e4c28:100"]="自然与超自然之力或许很难和谐共处，但这必将通向真正的伟大。"}
D.ItemDescriptions[151803]={["71658a91f5c2adf8:132"]="你的心就如风中的箭矢一般勇往直前，姐姐。你是我们最睿智的领袖，你是我们最亲爱的同胞。——希尔瓦娜斯，致奥蕾莉亚。"}
D.ItemDescriptions[151805]={["afa30bf591b84da4:59"]="一种稀有的能力，通常只属于那些天生就与蛇类亲近的人。"}
D.ItemDescriptions[151807]={["7f9f1bb727f9b62e:53"]="哪怕是最强大的敌人也存在可利用的弱点。"}
D.ItemDescriptions[151808]={["01a392539939f57c:121"]="数千年前，奎尔萨拉的高等精灵将魔法技艺传授给了人类。后来，这些人创建了肯瑞托并统治了达拉然。"}
D.ItemDescriptions[151809]={["ba56f3d7bfb6f266:104"]="这颗地狱火核心频繁地喷出火焰，其温度足以熔化最坚固的金属。"}
D.ItemDescriptions[151810]={["dddd6519c2720e60:96"]="使用阿尔萨斯在辛达苟萨之墓造成的浩劫残片铸造而成，能让穿戴者毛骨悚然。"}
D.ItemDescriptions[151811]={["3127102758a98e50:42"]="旭日东升，狂风呼啸，强敌授首。"}
D.ItemDescriptions[151812]={["b8691366f56a8923:41"]="当圣光涤尽邪秽之时，其光芒闪耀得最为耀眼。"}
D.ItemDescriptions[151813]={["bf4c427a43853203:87"]="你们还不明白吗，兄弟姐妹们？要想将天灾军团赶出艾泽拉斯，那就只有一个办法。"}
D.ItemDescriptions[151814]={["bb8d88d53cec1118:52"]="虚空不空。这里充满了怨恨、绝望以及死亡。"}
D.ItemDescriptions[151815]={["3a1ce571ceadd4aa:54"]="一旦你给狗戴上桂冠，就很难再给它拴上锁链了。"}
D.ItemDescriptions[151817]={["abad64354a5372cc:40"]="我们很容易焦躁。我们需要找点事情做。"}
D.ItemDescriptions[151818]={["4f1d63ffea18daf2:28"]="死亡终将降临于我们所有人……"}
D.ItemDescriptions[151819]={["220a7af784d59bb4:100"]="这双手套中灌注了数千火元素的精华，可它们摸上去还是出人意料的凉爽。"}
D.ItemDescriptions[151821]={["fb6c4d66cd3b9915:41"]="最强大的灵魂源自苦难。"}
D.ItemDescriptions[151822]={["991042da44369dc5:102"]="他将巨龙、神祇和恶魔的鲜血灌入这块闪闪发亮的钢铁。即使在彼世，他也守护着自己的朋友。"}
D.ItemDescriptions[151823]={["79d8e33032e86981:55"]="在旋风眼中，不存在高低之分，也没有天地之别。"}
D.ItemDescriptions[151824]={["d7c48cda7f102d57:32"]="他们从不以低调著称。"}
D.ItemDescriptions[151825]={["93f7b4732e5d6f80:40"]="让战吼响起来吧。我们将并肩出击！"}
D.ItemDescriptions[151828]={["ae2c5188406c4763:45"]=S[13084]}
D.ItemDescriptions[151829]={["ae2c5188406c4763:45"]=S[13084]}
D.ItemDescriptions[151837]={["e46345fa35f07269:83"]="这些纤细修长的水晶广受追捧，因为它们能够将圣光聚焦形成狂野的冲击波。"}
D.ItemDescriptions[151838]={["ccd90bd6f9018cd7:83"]="据说，审判核心是圣光军团技师们的巅峰技术成就。"}
D.ItemDescriptions[151839]={["c3d4d0f8b7aaea89:86"]="圣光军团的光铸盔甲都经过反复打磨，能够保护他们的守备官，抵抗燃烧军团的邪能魔法。"}
D.ItemDescriptions[151845]={["01c97e3735584fa2:49"]="里面似乎还残留了一些金色液体。"}
D.ItemDescriptions[151851]={["712c3b907c298c43:51"]="纯净的邪能核心，充斥着混沌的能量。"}
D.ItemDescriptions[151856]={["5121a73ef85ebac1:27"]="没用的草药。"}
D.ItemDescriptions[151857]={["3aa1d4446a27d6ff:21"]="一株星辰之耀幼苗。"}
D.ItemDescriptions[151858]={["c46484cc505fb51d:69"]="一小团蚕茧般的根系，内部散发着微弱的能量。"}
D.ItemDescriptions[151860]={["87d0086dc50f084e:43"]="这块矿石的表面散发着点点星光。"}
D.ItemDescriptions[151861]={["6482b9678416c4aa:27"]="天界金矿石的残余物质。"}
D.ItemDescriptions[151862]={["801bd410fb245ac3:28"]="开裂的天界金矿石核心。"}
D.ItemDescriptions[151863]={["87d0086dc50f084e:43"]="这块矿石的表面散发着点点星光。"}
D.ItemDescriptions[151864]={["3fdfeb081eff607f:51"]="一块天界金矿石，但里面大部分都是没用的石头。"}
D.ItemDescriptions[151865]={["a160ff5daf51d3f2:32"]="小块天界金矿石。"}
D.ItemDescriptions[151866]={["802dedfa6bc3fcf5:63"]="这些恶魔皮革碎片似乎被污染了，散发着一股恶臭。"}
D.ItemDescriptions[151867]={["bfda2cafe08c4790:66"]="野兽散发出的腐蚀糟蹋了这块皮革。"}
D.ItemDescriptions[151868]={["88d4a0d391edd27a:67"]="野兽体内的腐蚀已经扩散到了这颗利齿内，它已经没用了。"}
D.ItemDescriptions[151871]={["bf1d5239103c13d8:25"]="一大箱邪能页岩矿石。"}
D.ItemDescriptions[151872]={["3bac767d4dfca084:36"]="一件闪闪发光、金白两色相间的盔甲。"}
D.ItemDescriptions[151874]={["856df63f82b9672c:48"]="一台刻满金色符文的精美织布机。"}
D.ItemDescriptions[151876]={["d9ae712948f35b9a:50"]="一本收录了各种珠宝加工图鉴的书籍。"}
D.ItemDescriptions[151877]={["976380408cd5c0c5:48"]="太有趣了，你知道该怎么做的。"}
D.ItemDescriptions[151878]={["3c5356b66dd0280f:55"]="这顶嵌满宝石的王冠就如星辰般闪耀。"}
D.ItemDescriptions[151879]={["2919987bfc65c4fc:81"]="被净化之后，这块皮革就不再散发臭味，也不会令拿起它的人感到不适了。"}
D.ItemDescriptions[151880]={["4101d559809035c2:66"]="一小瓶纯净的金色液体，打开时会散发出鲜花般的芳香。"}
D.ItemDescriptions[151923]={["93b95f2246c72583:30"]="一个用天界金铸造的小铆钉。"}
D.ItemDescriptions[151924]={["94054860455ba6b1:28"]="胸甲的前挡板。"}
D.ItemDescriptions[151925]={["681211281a03a731:27"]="胸甲的后挡板。"}
D.ItemDescriptions[151927]={["985b18b10686bed0:70"]="霍巴特的减重便鞋原型款，可能需要校准。"}
D.ItemDescriptions[151931]={["270e1c2ec54fec2f:18"]="王冠底座"}
D.ItemDescriptions[151932]={["7b2ea90fc34ed6aa:25"]="海丝利安石的镶嵌托架。"}
D.ItemDescriptions[151933]={["3eb9ec5be7fc02e0:31"]="炫彩孔雀石的镶嵌托架。"}
D.ItemDescriptions[151958]={["cb673c07c3b7c59c:80"]="塔拉图斯是个囚禁着无数叛逆恶魔的世界，那里太阳的光辉让人惊叹不已。"}
D.ItemDescriptions[152200]={["08bdad6e363e0607:76"]="这些水晶构件可以充当小型艾瑞达科技产品的能源。"}
D.ItemDescriptions[152201]={["b7518e34816d88b7:66"]="将所有碎片拼凑起来后，你发现这是一个复杂的符文石板。"}
D.ItemDescriptions[152203]={["a177b717bbb17422:69"]="重铸的钥匙能让你破除执政团武器库的封印。"}
D.ItemDescriptions[152204]={["f11ca9417db84b34:33"]=S[1566]}
D.ItemDescriptions[152205]={["f11ca9417db84b34:33"]=S[1566]}
D.ItemDescriptions[152296]={["aacdf4e4adcf5ce3:48"]="将抑魔金与源生萨格里特混合后获得。"}
D.ItemDescriptions[152357]={["5a7ed12e25c86c6d:87"]="这颗脉动的水晶能够为贵族卫兵充能，他们曾保护过玛凯雷的殿堂。"}
D.ItemDescriptions[152407]={["a546eedfc759f596:61"]="一块阿古尼特水晶碎片，上面铭刻着数百个微型符文。"}
D.ItemDescriptions[152419]={["d22bafead0828ff3:50"]="石化树脂，源自阿古斯古老的石化树木。"}
D.ItemDescriptions[152465]={["3eb4837bc96aa258:82"]="军团打碎了这些石头，以防它们落入圣光军团之手。"}
D.ItemDescriptions[152466]={["0aca3dd9e7bfc93c:32"]="呼叫光铸者援军。"}
D.ItemDescriptions[152469]={["374e995ce6017665:112"]=S[15016]}
D.ItemDescriptions[152470]={["374e995ce6017665:112"]=S[15016]}
D.ItemDescriptions[152504]={["17594c7cd4bd8079:87"]="经过了数百年，艾格文用来封印萨格拉斯之墓的庞大力量仍然徘徊于此，依稀可辨。"}
D.ItemDescriptions[152555]={["9d6d0e19bc8fb050:35"]=S[13094]}
D.ItemDescriptions[152565]={["054312569713e9e7:37"]="教你学会烹制百鱼宴。"}
D.ItemDescriptions[152575]={["b1ed8acf099a6604:31"]="一张写满黑暗符文的古老卷轴。"}
D.ItemDescriptions[152583]={["caffae759b104d78:51"]="一块璀璨的绿色宝石，在海底失落了数百年。"}
D.ItemDescriptions[152602]={["67e3c8c98b3a3d58:36"]="虽然枯竭了，但还剩下了一个暗影核心。"}
D.ItemDescriptions[152616]={["33256f63e2d6bde6:41"]="教你学会配制星界治疗药水。"}
D.ItemDescriptions[152617]={["9aa921e866a67141:56"]=S[13156]}
D.ItemDescriptions[152618]={["9aa921e866a67141:56"]=S[13156]}
D.ItemDescriptions[152620]={["f5238dc89dc02d4f:38"]="教你学会配制星界法力药水。"}
D.ItemDescriptions[152621]={["f217c66d749ed5b4:53"]=S[13157]}
D.ItemDescriptions[152622]={["f217c66d749ed5b4:53"]=S[13157]}
D.ItemDescriptions[152626]={["a499263834fe480b:29"]="与我们一同坠入深渊吧。"}
D.ItemDescriptions[152648]={["25c428e132098680:45"]="一件燃烧着神圣魔法的古代德莱尼圣物。"}
D.ItemDescriptions[152658]={["71a4922bcb4b2136:54"]="教你学会如何将一块混沌水晶击碎成为魔光碎片。"}
D.ItemDescriptions[152689]={["42ccad18f0736019:94"]="这个构造体曾是某个古代艾瑞达灵魂的宿体，经过了漫长的警戒生涯，现在只剩下了一个水晶核心。"}
D.ItemDescriptions[152714]={["d3b26aeb3f56598c:54"]="这些幽灵已经摆脱了束缚，但它们携带的能量保留了下来。"}
D.ItemDescriptions[152725]={["8e18656181e3470e:49"]="教你学会如何一次研磨大量的星辰之耀。"}
D.ItemDescriptions[152726]={["cdba097b0a9edd26:55"]="教你学会一次性对大量天界金矿石进行选矿。"}
D.ItemDescriptions[152786]={["23222853d81c222e:115"]="制作一个骨质雕像。小鬼的骨头，邪犬的骨头，乌祖尔的骨头。只有这样才能召唤出千面吞噬者。"}
D.ItemDescriptions[152788]={["69f5e24752b91ada:50"]=S[13091]}
D.ItemDescriptions[152789]={["69f5e24752b91ada:50"]=S[13091]}
