D.ItemDescriptions[152891]={["8bf223addf9782be:36"]="能为军团飞行员的传送门发生器供能。"}
D.ItemDescriptions[152900]={["9195cebb877aa14c:50"]="泰坦之血，已经凝结成了坚硬的水晶。"}
D.ItemDescriptions[152901]={["75c1eefa4fd969a9:92"]="教你学会召唤或解散一头紫罗兰魔翼鸦。这种坐骑的速度会根据你的骑术等级和所在区域改变。"}
